export default "loymentLlmListResponse,\\n    DeploymentProviderAccountCreateRequest,\\n    DeploymentProviderAccountUpdateRequest,\\n    DeploymentSnapshotListResponse,\\n    DeploymentUpdateRequest,\\n    DeploymentUpdateResponse,\\n    RunCreateResponse,\\n    RunStatusResponse,\\n)\\nfrom langflow.services.adapters.deployment.watsonx_orchestrate.constants import (\\n    WATSONX_ORCHESTRATE_DEPLOYMENT_ADAPTER_KEY,\\n)\\nfrom langflow.services.adapters.deployment.watsonx_orchestrate.eligibility import get_wxo_flow_eligibility_error\\nfrom langflow.services.adapters.deployment.watsonx_orchestrate.payloads import (\\n    PAYLOAD_SCHEMAS as WXO_ADAPTER_PAYLOAD_SCHEMAS,\\n)\\nfrom langflow.services.database.models.deployment.model import Deployment\\nfrom langflow.services.database.models.deployment_provider_account.model import DeploymentProviderAccount\\nfrom langflow.services.database.models.deployment_provider_account.utils import (\\n    check_provider_url_allowed,\\n    extract_tenant_from_url,\\n)\\nfrom langflow.services.database.models.flow_version_deployment_attachment.crud import (\\n    list_deployment_attachments_for_flow_version_ids,\\n)\\n\\nif TYPE_CHECKING:\\n    from sqlalchemy.ext.asyncio import AsyncSession\\n\\n    from langflow.services.database.models.flow_version.model import FlowVersion\\n    from langflow.services.database.models.flow_version_deployment_attachment.model import (\\n        FlowVersionDeploymentAttachment,\\n    )\\n\\n\\n@dataclass(frozen=True)\\nclass _NormalizedAttachmentRow:\\n    attachment: FlowVersionDeploymentAttachment\\n    flow_version: FlowVersion\\n    flow_name: str | None\\n    snapshot_id: str\\n\\n\\nclass _FlowToolPayload(TypedDict):\\n    display_name: str\\n    provider_data: AdapterPayload\\n    raw_name: str\\n\\n\\ndef _validate_wxo_flow_artifacts(flow_artifacts: list[tuple[UUID, BaseFlowArtifact]]) -> None:\\n    \\\"\\\"\\\"Reject incompatible flow versions before the deployment adapter can call wxO.\\\"\\\"\\\"\\n    for flow_version_id, artifact in flow_artifacts:\\n        eligibility_error = get_wxo_flow_eligibility_error(artifact.data)\\n        if eligibility_error:\\n            detail = (\\n                f\\\"Flow '{artifact.name}' (version {flow_version_id}) cannot be deployed as a Watsonx Orchestrate tool. \\\"\\n                f\\\"{eligibility_error}\\\"\\n            )\\n            raise HTTPException(status_code=status.HTTP_422_UNPROCESSABLE_CONTENT, detail=detail)\\n\\n\\n@register_mapper(AdapterType.DEPLOYMENT, WATSONX_ORCHESTRATE_DEPLOYMENT_ADAPTER_KEY)\\nclass WatsonxOrchestrateDeploymentMapper(BaseDeploymentMapper):\\n    \\\"\\\"\\\"Deployment mapper for Watsonx Orchestrate provider.\\\"\\\"\\\"\\n\\n    PROVIDER_LABEL = \\\"watsonx Orchestrate\\\"\\n\\n    api_payloads = DeploymentApiPayloads(\\n        deployment_create=PayloadSlot(\\n            adapter_model=WatsonxApiDeploymentCreatePayload,\\n            policy=PayloadSlotPolicy.VALIDATE_ONLY,\\n        ),\\n        deployment_update=PayloadSlot(\\n            adapter_model=WatsonxApiDeploymentUpdatePayload,\\n            policy=PayloadSlotPolicy.VALIDATE_ONLY,\\n        ),\\n        deployment_update_result=PayloadSlot(\\n            adapter_model=WatsonxApiDeploymentUpdateResultData,\\n            policy=PayloadSlotPolicy.VALIDATE_ONLY,\\n        ),\\n        deployment_list_result=PayloadSlot(\\n            adapter_model=WatsonxApiDeploymentListProviderData,\\n            policy=PayloadSlotPolicy.VALIDATE_ONLY,\\n        ),\\n        config_list_result=PayloadSlot(\\n            adapter_model=WatsonxApiConfigListProviderData,\\n            policy=PayloadSlotPolicy.VALIDATE_ONLY,\\n        ),\\n        config_item_data=PayloadSlot(\\n            adapter_model=WatsonxApiConfigListItem,\\n            policy=PayloadSlotPolicy.VALIDATE_ONLY,\\n        ),\\n        snapshot_list_result=PayloadSlot(\\n            adapter_model=WatsonxApiSnapshotListProviderData,\\n            policy=PayloadSlotPolicy.VALIDATE_ONLY,\\n        ),\\n        deployment_item_data=PayloadSlot(\\n            adapter_model=WatsonxApiDeploymentFlowVersionItemData,\\n            policy=PayloadSlotPolicy.VALIDATE_ONLY,\\n        ),\\n        execution_create_result=PayloadSlot(\\n            adapter_model=WatsonxApiAgentExecutionCreateResultData,\\n            policy=PayloadSlotPolicy.VALIDATE_ONLY,\\n        ),\\n        execution_status_result=PayloadSlot(\\n            adapter_model=WatsonxApiAgentExecutionStatusResultData,\\n            policy=PayloadSlotPolicy.VALIDATE_ONLY,\\n        ),\\n        execution_input=PayloadSlot(\\n            adapter_model=WatsonxApiExecutionInput,\\n            policy=PayloadSlotPolicy.VALIDATE_ONLY,\\n        ),\\n        deployment_llm_list_result=PayloadSlot(\\n            adapter_model=WatsonxApiDeploymentLlmListResultData,\\n            policy=PayloadSlotPolicy.VALIDATE_ONLY,\\n        ),\\n        provider_account_create=PayloadSlot(adapter_model=WatsonxApiProviderAccountCreate),\\n        provider_account_update=PayloadSlot(adapter_model=WatsonxApiProviderAccountUpdate),\\n        provider_account_response=PayloadSlot(\\n            adapter_model=WatsonxApiProviderAccountResponse,\\n            policy=PayloadSlotPolicy.VALIDATE_ONLY,\\n        ),\\n    )\\n\\n    def _validate_create_provider_data(\\n        self,\\n        provider_data: dict[str, Any],\\n    ) -> tuple[WatsonxApiProviderAccountCreate, str]:\\n        \\\"\\\"\\\"Parse, validate, and resolve tenant for create provider_data.\\n\\n        Returns the parsed payload and the resolved tenant_id.\\n        Used by ``resolve_provider_account_create`` which needs the\\n        tenant_id for the DB model.\\n        \\\"\\\"\\\"\\n        parsed = self._parse_and_check_url(provider_data)\\n        tenant_id = parsed.tenant_id\\n        if not tenant_id:\\n            tenant_id = extract_tenant_from_url(\\n                parsed.url,\\n                WATSONX_ORCHESTRATE_DEPLOYMENT_ADAPTER_KEY,\\n            )\\n        if not tenant_id:\\n            msg = (\\n                \\\"provider_data.tenant_id is required for watsonx-orchestrate provider accounts. \\\"\\n                \\\"Provide tenant_id explicitly or use a provider_data.url containing /instances/{tenant_id}.\\\"\\n            )\\n            raise ValueError(msg)\\n        return parsed, tenant_id\\n\\n    def validate_create_provider_url(\\n        self,\\n        *,\\n        provider_data: dict[str, Any],\\n    ) -> str:\\n        return self._parse_and_check_url(provider_data).url\\n\\n    def format_conflict_detail(\\n        self,\\n        raw_message: str,\\n        *,\\n        resource: str | None = None,\\n        resource_name: str | None = None,\\n    ) -> str:\\n        normalized_resource_name = str(resource_name or \\\"\\\").strip() or None\\n        if resource == \\\"tool\\\":\\n            return (\\n                f\\\"A tool with name '{normalized_resource_name}' already exists in the provider. \\\"\\n                \\\"Please choose a different name.\\\"\\n                if normalized_resource_name\\n                else \\\"A tool with this name already exists in the provider. Please choose a different name.\\\"\\n            )\\n        if resource == \\\"connection\\\":\\n            return (\\n                f\\\"A connection with app_id '{normalized_resource_name}' already exists in the provider. \\\"\\n                \\\"Please choose a different name.\\\"\\n                if normalized_resource_name\\n                else \\\"A connection referenced in this request already exists in the provider. \\\"\\n                \\\"Please choose a different name.\\\"\\n            )\\n        if resource == \\\"agent\\\":\\n            return (\\n                f\\\"An agent with name '{normalized_resource_name}' already exists in the provider. \\\"\\n                \\\"Please choose a different name.\\\"\\n                if normalized_resource_name\\n                else \\\"An agent with this name already exists in the provider. Please choose a different name.\\\"\\n            )\\n\\n        return super().format_conflict_detail(\\n            raw_message,\\n            resource=resource,\\n            resource_name=resource_name,\\n        )\\n\\n    def _parse_and_check_url(\\n        self,\\n        provider_data: dict[str, Any],\\n    ) -> WatsonxApiProviderAccountCreate:\\n        \\\"\\\"\\\"Parse and validate provider_data for the create path.\\n\\n        Validates schema, then checks the URL against the hostname allowlist.\\n        \\\"\\\"\\\"\\n        parsed: WatsonxApiProviderAccountCreate = self.parse_api_request_slot(\\n            slot=self.api_payloads.provider_account_create,\\n            slot_name=\\\"provider_account_create\\\",\\n            raw=provider_data,\\n        )\\n        check_provider_url_allowed(parsed.url, WATSONX_ORCHESTRATE_DEPLOYMENT_ADAPTER_KEY)\\n        return parsed\\n\\n    async def resolve_execution_input(self, raw: dict[str, Any] | None, db: AsyncSession) -> dict[str, Any] | None:\\n        \\\"\\\"\\\"Validate run provider_data and reject missing payloads at API boundary.\\\"\\\"\\\"\\n        _ = db\\n        parsed: WatsonxApiExecutionInput = self.parse_api_request_slot(\\n            slot=self.api_payloads.execution_input,\\n            slot_name=\\\"execution_input\\\",\\n            raw=raw,\\n        )\\n        return parsed.model_dump(mode=\\\"json\\\", exclude_none=True)\\n\\n    def resolve_load_from_provider_deployment_list_params(self) -> dict[str, Any] | None:\\n        \\\"\\\"\\\"Force provider-backed list mode to draft agents only.\\\"\\\"\\\"\\n        return {\\\"environment\\\": \\\"draft\\\"}\\n\\n    def _parse_deployment_create_request(self, payload: DeploymentCreateRequest) -> WatsonxApiDeploymentCreatePayload:\\n        api_provider_payload: WatsonxApiDeploymentCreatePayload = self.parse_api_request_slot(\\n            slot=self.api_payloads.deployment_create,\\n            slot_name=\\\"deployment_create\\\",\\n            raw=payload.provider_data,\\n            outer_payload=payload,\\n        )\\n        return api_provider_payload\\n\\n    def resolve_deployment_model_for_create(\\n        self,\\n        *,\\n        result: DeploymentCreateResult,\\n        user_id: UUID,\\n        project_id: UUID,\\n        deployment_provider_account_id: UUID,\\n    ) -> Deployment:\\n        \\\"\\\"\\\"Assemble the DB model for a wxO deployment create.\\\"\\\"\\\"\\n        adapter_provider_result = self.parse_adapter_slot(\\n            slot=WXO_ADAPTER_PAYLOAD_SCHEMAS.deployment_create_result,\\n            slot_name=\\\"deployment_create_result\\\",\\n            raw=result.provider_result,\\n            operation=\\\"creating the deployment row in Langflow\\\",\\n        )\\n        return Deployment(\\n            user_id=user_id,\\n            project_id=project_id,\\n            deployment_provider_account_id=deployment_provider_account_id,\\n            resource_key=str(result.id),\\n            display_name=adapter_provider_result.display_name,\\n            deployment_type=result.type,\\n            description=result.description,\\n        )\\n\\n    def resolve_deployment_model_from_existing_resource_for_create(\\n        self,\\n        *,\\n        payload: DeploymentCreateRequest,\\n        existing_provider_resource: DeploymentGetResult,\\n        user_id: UUID,\\n        project_id: UUID,\\n        deployment_provider_account_id: UUID,\\n    ) -> Deployment:\\n        \\\"\\\"\\\"Assemble the DB model for tracking an existing wxO agent.\\\"\\\"\\\"\\n        existing_provider_data = self.parse_adapter_slot(\\n            slot=WXO_ADAPTER_PAYLOAD_SCHEMAS.deployment_item_data,\\n            slot_name=\\\"deployment_item_data\\\",\\n            raw=existing_provider_resource.provider_data,\\n            operation=\\\"reading deployment metadata from provider when attempting to track the resource in Langflow\\\",\\n        )\\n        return Deployment(\\n            user_id=user_id,\\n            project_id=project_id,\\n            deployment_provider_account_id=deployment_provider_account_id,\\n            resource_key=str(existing_provider_resource.id),\\n            display_name=existing_provider_data.display_name,\\n            deployment_type=payload.type,\\n            description=existing_provider_data.description,\\n        )\\n\\n    def resolve_kwargs_for_metadata_update(self, result: DeploymentUpdateResult) -> dict[str, Any]:\\n        \\\"\\\"\\\"Assemble Deployment metadata update kwargs from the wxO update result.\\\"\\\"\\\"\\n        adapter_provider_result = self.parse_adapter_slot(\\n            slot=WXO_ADAPTER_PAYLOAD_SCHEMAS.deployment_update_result,\\n            slot_name=\\\"deployment_update_result\\\",\\n            raw=result.provider_result,\\n            operation=\\\"syncing deployment metadata after update\\\",\\n        )\\n        return {\\n            \\\"display_name\\\": adapter_provider_result.display_name,\\n            \\\"description\\\": adapter_provider_result.description,\\n        }\\n\\n    def resolve_credentials(\\n        self,\\n        *,\\n        provider_data: dict[str, Any],\\n    ) -> dict[str, Any]:\\n        parsed: WatsonxApiProviderAccountUpdate = self.parse_api_request_slot(\\n            slot=self.api_payloads.provider_account_update,\\n            slot_name=\\\"provider_account_update\\\",\\n            raw=provider_data,\\n        )\\n        return parsed.model_dump()\\n\\n    def resolve_provider_account_create(\\n        self,\\n        *,\\n        payload: DeploymentProviderAccountCreateRequest,\\n        user_id: UUID,\\n    ) -> DeploymentProviderAccount:\\n        \\\"\\\"\\\"Assemble provider-account DB model for create.\\n\\n        The returned model carries a **plaintext** ``api_key``.  The CRUD\\n        layer (``create_provider_account_from_model``) encrypts it before\\n        persistence.\\n        \\\"\\\"\\\"\\n        parsed, tenant_id = self._validate_create_provider_data(payload.provider_data)\\n        return DeploymentProviderAccount(\\n            user_id=user_id,\\n            name=payload.name,\\n            provider_tenant_id=tenant_id,\\n            provider_key=payload.provider_key,\\n            provider_url=parsed.url,\\n            api_key=parsed.api_key,\\n        )\\n\\n    def resolve_provider_account_provider_data(\\n        self,\\n        provider_account: DeploymentProviderAccount,\\n    ) -> dict[str, Any] | None:\\n        parsed = self.parse_adapter_slot(\\n            slot=self.api_payloads.provider_account_response,\\n            slot_name=\\\"provider_account_response\\\",\\n            raw={\\n                \\\"url\\\": provider_account.provider_url,\\n                \\\"tenant_id\\\": provider_account.provider_tenant_id,\\n            },\\n            operation=\\\"building the provider account response\\\",\\n        )\\n        return parsed.model_dump(mode=\\\"json\\\", exclude_none=True)\\n\\n    def resolve_verify_credentials_for_create(\\n        self,\\n        *,\\n        payload: DeploymentProviderAccountCreateRequest,\\n    ) -> VerifyCredentials:\\n        parsed = self._parse_and_check_url(payload.provider_data)\\n        return VerifyCredentials(\\n            base_url=parsed.url,\\n            provider_data={\\\"api_key\\\": parsed.api_key},\\n        )\\n\\n    def resolve_verify_credentials_for_update(\\n        self,\\n        *,\\n        payload: DeploymentProviderAccountUpdateRequest,\\n        existing_account: DeploymentProviderAccount,\\n    ) -> VerifyCredentials | None:\\n        if \\\"provider_data\\\" not in payload.model_fields_set:\\n            return None\\n\\n        parsed: WatsonxApiProviderAccountUpdate = self.parse_api_request_slot(\\n            slot=self.api_payloads.provider_account_update,\\n            slot_name=\\\"provider_account_update\\\",\\n            raw=payload.provider_data,\\n        )\\n\\n        return VerifyCredentials(\\n            base_url=existing_account.provider_url,\\n            provider_data={\\\"api_key\\\": parsed.api_key},\\n        )\\n\\n    def _build_flow_tool_payload(\\n        self,\\n        *,\\n        project_id: UUID,\\n        flow_version_id: UUID,\\n        tool_display_name: str,\\n    ) -> _FlowToolPayload:\\n        parsed_provider_data = self.parse_adapter_slot(\\n            slot=WXO_ADAPTER_PAYLOAD_SCHEMAS.flow_artifact,\\n            slot_name=\\\"flow_artifact\\\",\\n            raw={\\n                \\\"source_ref\\\": str(flow_version_id),\\n                \\\"project_id\\\": str(project_id),\\n                \\\"tool_display_name\\\": tool_display_name,\\n            },\\n            operation=\\\"building flow tool provider data\\\",\\n        )\\n        provider_data = parsed_provider_data.model_dump(mode=\\\"json\\\", exclude_none=True)\\n\\n        try:\\n            technical_name = provider_data[\\\"tool_name\\\"]\\n        except KeyError as exc:\\n            msg = f\\\"Unable to create tool name for flow_version_id: [{flow_version_id}]\\\"\\n            raise HTTPException(status_code=status.HTTP_500_INTERNAL_SERVER_ERROR, detail=msg) from exc\\n        return {\\n            \\\"display_name\\\": tool_display_name,\\n            \\\"provider_data\\\": provider_data,\\n            \\\"raw_name\\\": technical_name,\\n        }\\n\\n    def _get_flow_tool_payload(\\n        self,\\n        *,\\n        flow_tool_by_flow_version_id: dict[UUID, _FlowToolPayload],\\n        flow_version_id: UUID,\\n        field_name: str,\\n    ) -> _FlowToolPayload:\\n        try:\\n            return flow_tool_by_flow_version_id[flow_version_id]\\n        except KeyError as exc:\\n            msg = f\\\"Failed to resolve wxO tool payload for {field_name}: [{flow_version_id}]\\\"\\n            raise HTTPException(status_code=status.HTTP_500_INTERNAL_SERVER_ERROR, detail=msg) from exc\\n\\n    def _build_deployment_create_adapter_payload(\\n        self,\\n        *,\\n        api_provider_payload: WatsonxApiDeploymentCreatePayload,\\n        flow_artifacts: list[tuple[UUID, Any]],\\n        flow_tool_by_flow_version_id: dict[UUID, _FlowToolPayload],\\n        provider_operations: list[AdapterPayload],\\n    ) -> AdapterPayload:\\n        return self.parse_adapter_slot(\\n            slot=WXO_ADAPTER_PAYLOAD_SCHEMAS.deployment_create,\\n            slot_name=\\\"deployment_create\\\",\\n            raw=self._build_provider_payload_body(\\n                llm=api_provider_payload.llm,\\n                display_name=api_provider_payload.display_name,\\n                model_fields_set=api_provider_payload.model_fields_set,\\n                raw_tool_payloads=[\\n                    artifact.model_copy(\\n                        update={\\n                            \\\"provider_data\\\": flow_tool_by_flow_version_id[flow_version_id][\\\"provider_data\\\"],\\n                        }\\n                    ).model_dump(exclude_none=True)\\n                    for flow_version_id, artifact in flow_artifacts\\n                ],\\n                connections=api_provider_payload.connections,\\n                operations=provider_operations,\\n            ),\\n            operation=\\\"building the deployment_create provider payload\\\",\\n        ).model_dump(mode=\\\"json\\\")\\n\\n    def _build_deployment_update_adapter_payload(\\n        self,\\n        *,\\n        api_provider_payload: WatsonxApiDeploymentUpdatePayload,\\n        raw_payloads: list[Any],\\n        provider_operations: list[AdapterPayload],\\n    ) -> AdapterPayload:\\n        return self.parse_adapter_slot(\\n            slot=WXO_ADAPTER_PAYLOAD_SCHEMAS.deployment_update,\\n            slot_name=\\\"deployment_update\\\",\\n            raw=self._build_provider_payload_body(\\n                llm=api_provider_payload.llm,\\n                display_name=api_provider_payload.display_name,\\n                model_fields_set=api_provider_payload.model_fields_set,\\n                raw_tool_payloads=[artifact.model_dump(exclude_none=True) for artifact in raw_payloads],\\n                connections=api_provider_payload.connections,\\n                operations=provider_operations,\\n            ),\\n            operation=\\\"building the deployment_update provider payload\\\",\\n        ).model_dump(mode=\\\"json\\\", exclude_unset=True)\\n\\n    def util_create_flow_version_ids(self, payload: DeploymentCreateRequest) -> list[UUID]:\\n        if \\\"provider_data\\\" not in payload.model_fields_set:\\n            # The create route uses this before provider creation to validate\\n            # referenced flow versions. Omitted provider_data means no\\n            # create-time flow attachments to validate; explicitly provided\\n            # provider_data must still satisfy the wxO create schema.\\n            return []\\n\\n        api_provider_payload = self._parse_deployment_create_request(payload)\\n        return list(dict.fromkeys(item.flow_version_id for item in api_provider_payload.add_flows))\\n\\n    def util_existing_deployment_resource_key_for_create(\\n        self,\\n        payload: DeploymentCreateRequest,\\n    ) -> str | None:\\n        if \\\"provider_data\\\" not in payload.model_fields_set:\\n            # The create route uses None to mean \\\"create a new provider\\n            # resource\\\" when provider_data is omitted. Explicit provider_data\\n            # must still satisfy the wxO create schema before we inspect it.\\n            return None\\n\\n        api_provider_payload = self._parse_deployment_create_request(payload)\\n        return api_provider_payload.existing_agent_id\\n\\n    def util_create_result_from_existing_resource(\\n        self,\\n        *,\\n        existing_resource: DeploymentGetResult,\\n    ) -> DeploymentCreateResult:\\n        \\\"\\\"\\\"Build a create-style result payload for tracking an existing wxO agent.\\n\\n        This path is used when create request includes ``existing_agent_id``\\n        without create-time mutation operations. ``created_*`` fields represent\\n        what this request created, so they are intentionally empty here.\\n        \\\"\\\"\\\"\\n        existing_provider_data = self.parse_adapter_slot(\\n            slot=WXO_ADAPTER_PAYLOAD_SCHEMAS.deployment_item_data,\\n            slot_name=\\\"deployment_item_data\\\",\\n            raw=existing_resource.provider_data,\\n            operation=\\\"reading deployment metadata\\\",\\n        )\\n        create_provider_result = self.parse_adapter_slot(\\n            slot=WXO_ADAPTER_PAYLOAD_SCHEMAS.deployment_create_result,\\n            slot_name=\\\"deployment_create_result\\\",\\n            raw={\\n                \\\"display_name\\\": existing_provider_data.display_name,\\n                \\\"app_ids\\\": [],\\n                \\\"tools_with_refs\\\": [],\\n            },\\n            operation=\\\"building the create response for the existing resource\\\",\\n        )\\n        return DeploymentCreateResult(\\n            id=existing_resource.id,\\n            type=existing_resource.type,\\n            name=existing_resource.name,\\n            description=existing_provider_data.description,\\n            provider_result=create_provider_result.model_dump(mode=\\\"json\\\"),\\n        )\\n\\n    async def _resolve_provider_payload_from_create_api(\\n        self,\\n        *,\\n        user_id: UUID,\\n        project_id: UUID,\\n        db: AsyncSession,\\n        api_provider_payload: WatsonxApiDeploymentCreatePayload,\\n    ) -> AdapterPayload:\\n        flow_version_ids = list(dict.fromkeys(item.flow_version_id for item in api_provider_payload.add_flows))\\n        flow_artifacts = await build_project_scoped_flow_artifacts_from_flow_versions(\\n            db=db,\\n            user_id=user_id,\\n            project_id=project_id,\\n            reference_ids=flow_version_ids,\\n        )\\n        _validate_wxo_flow_artifacts(flow_artifacts)\\n        # Start with flow names as display labels, then let user-provided\\n        # tool_display_name overrides replace them. The adapter provider-data\\n        # schema generates the wxO technical tool name once; raw payload names\\n        # and bind operation selectors both reuse that generated value.\\n        tool_display_name_by_flow_version_id: dict[UUID, str] = {\\n            flow_version_id: artifact.name for flow_version_id, artifact in flow_artifacts\\n        }\\n        for item in api_provider_payload.add_flows:\\n            if not item.tool_display_name:\\n                continue\\n            tool_display_name_by_flow_version_id[item.flow_version_id] = item.tool_display_name\\n        flow_tool_by_flow_version_id = {\\n            flow_version_id: self._build_flow_tool_payload(\\n                project_id=project_id,\\n                flow_version_id=flow_version_id,\\n                tool_display_name=tool_display_name,\\n            )\\n            for flow_version_id, tool_display_name in tool_display_name_by_flow_version_id.items()\\n        }\\n        provider_operations = self._build_provider_operations(\\n            add_flows=api_provider_payload.add_flows,\\n            upsert_tools=api_provider_payload.upsert_tools,\\n            flow_tool_by_flow_version_id=flow_tool_by_flow_version_id,\\n        )\\n        return self._build_deployment_create_adapter_payload(\\n            api_provider_payload=api_provider_payload,\\n            flow_artifacts=flow_artifacts,\\n            flow_tool_by_flow_version_id=flow_tool_by_flow_version_id,\\n            provider_operations=provider_operations,\\n        )\\n\\n    async def resolve_deployment_create(\\n        self,\\n        *,\\n        user_id: UUID,\\n        project_id: UUID,\\n        db: AsyncSession,\\n        payload: DeploymentCreateRequest,\\n    ) -> AdapterDeploymentCreate:\\n        api_provider_payload = self._parse_deployment_create_request(payload)\\n        if api_provider_payload.llm is None:\\n            msg = \\\"provider_data.llm is required for wxO deployment create.\\\"\\n            raise HTTPException(status_code=status.HTTP_422_UNPROCESSABLE_CONTENT, detail=msg)\\n        provider_payload = await self._resolve_provider_payload_from_create_api(\\n            user_id=user_id,\\n            project_id=project_id,\\n            db=db,\\n            api_provider_payload=api_provider_payload,\\n        )\\n        if api_provider_payload.display_name is None:\\n            msg = \\\"provider_data.display_name is required for wxO deployment create.\\\"\\n            raise HTTPException(status_code=status.HTTP_422_UNPROCESSABLE_CONTENT, detail=msg)\\n        return AdapterDeploymentCreate(\\n            spec=BaseDeploymentData(\\n                description=payload.description,\\n                type=payload.type,\\n            ),\\n            provider_data=provider_payload,\\n        )\\n\\n    async def resolve_deployment_update(\\n        self,\\n        *,\\n        user_id: UUID,\\n        deployment_db_id: UUID,\\n        db: AsyncSession,\\n        payload: DeploymentUpdateRequest,\\n    ) -> AdapterDeploymentUpdate:\\n        description = payload.description\\n        has_description = \\\"description\\\" in payload.model_fields_set\\n        if \\\"provider_data\\\" not in payload.model_fields_set:\\n            # Metadata-only updates still need an adapter update for the spec,\\n            # but should not fabricate an empty wxO operations payload. If\\n            # provider_data is explicit, the wxO update schema owns validation.\\n            return AdapterDeploymentUpdate(spec=BaseDeploymentDataUpdate(description=description))\\n\\n        api_provider_payload: WatsonxApiDeploymentUpdatePayload = self.parse_api_request_slot(\\n            slot=self.api_payloads.deployment_update,\\n            slot_name=\\\"deployment_update\\\",\\n            raw=payload.provider_data,\\n        )\\n        spec_kwargs: dict[str, Any] = {}\\n        if has_description:\\n            spec_kwargs[\\\"description\\\"] = description\\n        adapter_spec = BaseDeploymentDataUpdate(**spec_kwargs) if spec_kwargs else None\\n        ordered_flow_version_ids = list(\\n            dict.fromkeys(\\n                item.flow_version_id\\n                for item in api_provider_payload.upsert_flows\\n                if item.add_app_ids or not item.remove_app_ids\\n            )\\n        )\\n        flow_artifacts = await build_flow_artifacts_from_flow_versions(\\n            db=db,\\n            user_id=user_id,\\n            deployment_db_id=deployment_db_id,\\n            flow_version_ids=ordered_flow_version_ids,\\n        )\\n        _validate_wxo_flow_artifacts(\\n            [(flow_version_id, artifact) for flow_version_id, _version_number, _project_id, artifact in flow_artifacts]\\n        )\\n        # Start with flow names as display labels, then let user-provided\\n        # tool_display_name overrides replace them. The adapter provider-data\\n        # schema generates the wxO technical tool name once; raw payload names\\n        # and bind operation selectors both reuse that generated value.\\n        tool_display_name_by_flow_version_id: dict[UUID, str] = {\\n            flow_version_id: artifact.name for flow_version_id, _version_number, _project_id, artifact in flow_artifacts\\n        }\\n        for item in api_provider_payload.upsert_flows:\\n            if not item.tool_display_name:\\n                continue\\n            if item.flow_version_id not in tool_display_name_by_flow_version_id:\\n                continue\\n            tool_display_name_by_flow_version_id[item.flow_version_id] = item.tool_display_name\\n        flow_tool_by_flow_version_id = {\\n            flow_version_id: self._build_flow_tool_payload(\\n                project_id=artifact_project_id,\\n                flow_version_id=flow_version_id,\\n                tool_display_name=tool_display_name_by_flow_version_id[flow_version_id],\\n            )\\n            for flow_version_id, _version_number, artifact_project_id, _artifact in flow_artifacts\\n        }\\n        raw_payloads = [\\n            artifact.model_copy(\\n                update={\\n                    \\\"provider_data\\\": flow_tool_by_flow_version_id[flow_version_id][\\\"provider_data\\\"],\\n                }\\n            )\\n            for flow_version_id, _version_number, _project_id, artifact in flow_artifacts\\n        ]\\n\\n        upsert_fv_ids = list(dict.fromkeys(item.flow_version_id for item in api_provider_payload.upsert_flows))\\n        remove_fv_ids = list(dict.fromkeys(api_provider_payload.remove_flows))\\n        all_fv_ids = list(dict.fromkeys(upsert_fv_ids + remove_fv_ids))\\n        flow_version_snapshot_id_map = await self._lookup_snapshot_ids(\\n            user_id=user_id,\\n            deployment_db_id=deployment_db_id,\\n            db=db,\\n            flow_version_ids=all_fv_ids,\\n        )\\n        strict_fv_ids = list(\\n            dict.fromkeys(\\n                [item.flow_version_id for item in api_provider_payload.upsert_flows if item.remove_app_ids]\\n                + remove_fv_ids\\n            )\\n        )\\n        missing_strict = [str(fv) for fv in strict_fv_ids if fv not in flow_version_snapshot_id_map]\\n        if missing_strict:\\n            msg = f\\\"Cannot resolve provider snapshot ids for flow_version_ids in watsonx operations: {missing_strict}\\\"\\n            raise HTTPException(status_code=status.HTTP_422_UNPROCESSABLE_CONTENT, detail=msg)\\n\\n        reused_fv_ids = {\\n            item.flow_version_id\\n            for item in api_provider_payload.upsert_flows\\n            if (item.add_app_ids or not item.remove_app_ids) and item.flow_version_id in flow_version_snapshot_id_map\\n        }\\n        filtered_raw_payloads = (\\n            [\\n                raw_payload\\n                for (flow_version_id, _version_number, _project_id, _artifact), raw_payload in zip(\\n                    flow_artifacts, raw_payloads, strict=True\\n                )\\n                if flow_version_id not in reused_fv_ids\\n            ]\\n            if reused_fv_ids\\n            else raw_payloads\\n        )\\n\\n        provider_operations = self._build_provider_operations(\\n            upsert_flows=api_provider_payload.upsert_flows,\\n            upsert_tools=api_provider_payload.upsert_tools,\\n            remove_flows=api_provider_payload.remove_flows,\\n            remove_tools=api_provider_payload.remove_tools,\\n            flow_tool_by_flow_version_id=flow_tool_by_flow_version_id,\\n            flow_version_snapshot_id_map=flow_version_snapshot_id_map,\\n        )\\n\\n        provider_payload = self._build_deployment_update_adapter_payload(\\n            api_provider_payload=api_provider_payload,\\n            raw_payloads=filtered_raw_payloads,\\n            provider_operations=provider_operations,\\n        )\\n        return AdapterDeploymentUpdate(\\n            spec=adapter_spec,\\n            provider_data=provider_payload,\\n        )\\n\\n    def extract_snapshot_bindings(self, provider_view) -> list[ProviderSnapshotBinding]:\\n        bindings: list[ProviderSnapshotBinding] = []\\n        for item in provider_view.deployments:\\n            resource_key = str(item.id)\\n\\n            item_provider_data = self.parse_adapter_slot(\\n                slot=WXO_ADAPTER_PAYLOAD_SCHEMAS.deployment_item_data,\\n                slot_name=\\\"deployment_item_data\\\",\\n                raw=item.provider_data,\\n                operation=\\\"reading deployment list item metadata\\\",\\n            )\\n            bindings.extend(\\n                ProviderSnapshotBinding(resource_key=resource_key, snapshot_id=str(snapshot_id))\\n                for snapshot_id in item_provider_data.tool_ids\\n            )\\n        return bindings\\n\\n    def extract_list_item_provider_data(\\n        self,\\n        provider_view: DeploymentListResult,\\n    ) -> dict[str, dict[str, Any]]:\\n        provider_data_by_resource_key: dict[str, dict[str, Any]] = {}\\n        for item in provider_view.deployments:\\n            item_provider_data = self.parse_adapter_slot(\\n                slot=WXO_ADAPTER_PAYLOAD_SCHEMAS.deployment_item_data,\\n                slot_name=\\\"deployment_item_data\\\",\\n                raw=item.provider_data,\\n                operation=\\\"reading deployment list item metadata\\\",\\n            )\\n\\n            resource_key = str(item.id)\\n            provider_data_by_resource_key[resource_key] = WatsonxApiDeploymentListItemProviderData(\\n                name=item.name,\\n                display_name=item_provider_data.display_name,\\n                llm=item_provider_data.llm,\\n                environments=item_provider_data.environments,\\n            ).model_dump(mode=\\\"json\\\")\\n\\n        return provider_data_by_resource_key\\n\\n    def extract_metadata_for_list(\\n        self,\\n        provider_view: DeploymentListResult,\\n    ) -> dict[str, dict[str, Any]]:\\n        metadata_by_resource_key: dict[str, dict[str, Any]] = {}\\n        for item in provider_view.deployments:\\n            item_provider_data = self.parse_adapter_slot(\\n                slot=WXO_ADAPTER_PAYLOAD_SCHEMAS.deployment_item_data,\\n                slot_name=\\\"deployment_item_data\\\",\\n                raw=item.provider_data,\\n                operation=\\\"reading deployment list item metadata\\\",\\n            )\\n            resource_key = str(item.id)\\n            metadata_by_resource_key[resource_key] = {\\n                \\\"display_name\\\": item_provider_data.display_name,\\n                \\\"description\\\": item_provider_data.description,\\n            }\\n        return metadata_by_resource_key\\n\\n    def extract_snapshot_bindings_for_get(\\n        self,\\n        get_result: DeploymentGetResult,\\n        *,\\n        resource_key: str,\\n    ) -> list[ProviderSnapshotBinding]:\\n        if get_result.provider_data is None:\\n            msg = \\\"An internal error occured. provider_data is required from wxO adapter for get().\\\"\\n            raise ValueError(msg)\\n        if \\\"tool_ids\\\" not in get_result.provider_data:\\n            msg = \\\"An internal error occured. provider_data must contain 'tool_ids' from wxO adapter for get().\\\"\\n            raise ValueError(msg)\\n\\n        tool_ids = get_result.provider_data[\\\"tool_ids\\\"]\\n\\n        if not isinstance(tool_ids, list):\\n            msg = \\\"An internal error occured. provider_data['tool_ids'] must be a list from wxO adapter for get().\\\"\\n            raise ValueError(msg)  # noqa: TRY004\\n\\n        return [\\n            ProviderSnapshotBinding(resource_key=resource_key, snapshot_id=str(snapshot_id)) for snapshot_id in tool_ids\\n        ]\\n\\n    def extract_metadata_for_get(\\n        self,\\n        get_result: DeploymentGetResult,\\n    ) -> dict[str, Any]:\\n        parsed = self.parse_adapter_slot(\\n            slot=WXO_ADAPTER_PAYLOAD_SCHEMAS.deployment_item_data,\\n            slot_name=\\\"deployment_item_data\\\",\\n            raw=get_result.provider_data,\\n            operation=\\\"reading deployment metadata\\\",\\n        )\\n        return {\\n            \\\"display_name\\\": parsed.display_name,\\n            \\\"description\\\": parsed.description,\\n        }\\n\\n    async def resolve_rollback_update(\\n        self,\\n        *,\\n        user_id: UUID,\\n        deployment_db_id: UUID,\\n        deployment_resource_key: str,\\n        db: AsyncSession,\\n    ) -> AdapterDeploymentUpdate | None:\\n        \\\"\\\"\\\"Build a compensating update from current DB attachment state.\\n\\n        Queries flow_version_deployment_attachment for provider_snapshot_ids\\n        (WXO tool IDs) and constructs an update that declaratively sets the\\n        agent's tool list to match the (still-committed) DB state.  Also\\n        restores deployment display_name and description via spec.\\n\\n        If the provider snapshots were concurrently deleted, the adapter call\\n        may fail; read-path snapshot sync handles that residual divergence.\\n        \\\"\\\"\\\"\\n        from langflow.services.database.models.deployment.crud import get_deployment\\n        from langflow.services.database.models.flow_version_deployment_attachment.crud import (\\n            list_deployment_attachments,\\n        )\\n\\n        _ = deployment_resource_key\\n        deployment = await get_deployment(db, user_id=user_id, deployment_id=deployment_db_id)\\n        if deployment is None:\\n            return None\\n\\n        attachments = await list_deployment_attachments(db, user_id=user_id, deployment_id=deployment_db_id)\\n        existing_tool_ids = [\\n            str(att.provider_snapshot_id).strip()\\n            for att in attachments\\n            if att.provider_snapshot_id and str(att.provider_snapshot_id).strip()\\n        ]\\n\\n        update_slot = WXO_ADAPTER_PAYLOAD_SCHEMAS.deployment_update\\n        if update_slot is None:\\n            return None\\n        # TODO: Reintroduce a non-unique Deployment.name column for provider technical names\\n        # and include it here so rollback can restore wxO `name` from Langflow's stored metadata.\\n        provider_payload = update_slot.apply(\\n            {\\n                \\\"put_tools\\\": existing_tool_ids,\\n                \\\"display_name\\\": deployment.display_name,\\n            }\\n        )\\n        rollback_description = (\\n            deployment.description if deployment.description and deployment.description.strip() else None\\n        )\\n\\n        return AdapterDeploymentUpdate(\\n            spec=BaseDeploymentDataUpdate(\\n                description=rollback_description,\\n            ),\\n            provider_data=provider_payload,\\n        )\\n\\n    def shape_deployment_create_result(\\n        self,\\n        result: DeploymentCreateResult,\\n        deployment_row: Deployment,\\n        *,\\n        provider_key: str,\\n    ) -> DeploymentCreateResponse:\\n        \\\"\\\"\\\"Shape create result provider_data with created-tools semantics.\\n\\n        ``created_tools`` is populated directly from ``tools_with_refs``. Each\\n        entry must carry a flow-version UUID ``source_ref`` and a non-empty\\n        provider ``tool_id``.\\n        \\\"\\\"\\\"\\n        adapter_provider_result = self.parse_adapter_slot(\\n            slot=WXO_ADAPTER_PAYLOAD_SCHEMAS.deployment_create_result,\\n            slot_name=\\\"deployment_create_result\\\",\\n            raw=result.provider_result,\\n            operation=\\\"creating the deployment\\\",\\n        )\\n        created_tools: list[WatsonxApiCreatedTool] = []\\n        for binding in adapter_provider_result.tools_with_refs:\\n            tool_id = str(binding.tool_id or \\\"\\\").strip()\\n            source_ref = str(binding.source_ref or \\\"\\\").strip()\\n            if not tool_id:\\n                msg = \\\"Deployment provider create result contains a tool binding with an empty tool_id.\\\"\\n                raise HTTPException(status_code=status.HTTP_500_INTERNAL_SERVER_ERROR, detail=msg)\\n            if not source_ref:\\n                msg = (\\n                    \\\"Deployment provider create result contains a tool binding with an empty source_ref \\\"\\n                    f\\\"for tool_id={tool_id!r}.\\\"\\n                )\\n                raise HTTPException(status_code=status.HTTP_500_INTERNAL_SERVER_ERROR, detail=msg)\\n            try:\\n                created_tool = WatsonxApiCreatedTool(\\n                    flow_version_id=source_ref,\\n                    tool_id=tool_id,\\n                )\\n            except ValidationError as exc:\\n                msg = (\\n                    \\\"Deployment provider create result contains a created tool binding with a non-UUID \\\"\\n                    f\\\"source_ref={source_ref!r} for tool_id={tool_id!r}. A flow version id was expected.\\\"\\n                )\\n                raise HTTPException(status_code=status.HTTP_500_INTERNAL_SERVER_ERROR, detail=msg) from exc\\n            created_tools.append(created_tool)\\n        provider_api_result = WatsonxApiDeploymentCreateResultData(\\n            name=result.name,\\n            display_name=deployment_row.display_name,\\n            created_app_ids=list(adapter_provider_result.app_ids),\\n            created_tools=created_tools,\\n        )\\n        return DeploymentCreateResponse(\\n            id=deployment_row.id,\\n            provider_id=deployment_row.deployment_provider_account_id,\\n            provider_key=provider_key,\\n            description=deployment_row.description,\\n            type=deployment_row.deployment_type,\\n            created_at=deployment_row.created_at,\\n            updated_at=deployment_row.updated_at,\\n            resource_key=deployment_row.resource_key,\\n            provider_data=provider_api_result.model_dump(mode=\\\"json\\\"),\\n        )\\n\\n    def shape_deployment_update_result(\\n        self,\\n        result: DeploymentUpdateResult,\\n        deployment_row: Deployment,\\n        *,\\n        provider_key: str,\\n    ) -> DeploymentUpdateResponse:\\n        adapter_provider_result = self.parse_adapter_slot(\\n            slot=WXO_ADAPTER_PAYLOAD_SCHEMAS.deployment_update_result,\\n            slot_name=\\\"deployment_update_result\\\",\\n            raw=result.provider_result,\\n            operation=\\\"updating the deployment\\\",\\n        )\\n        created_tools = self._to_api_created_tools(\\n            adapter_created_snapshot_bindings=adapter_provider_result.created_snapshot_bindings\\n        )\\n        provider_api_result = WatsonxApiDeploymentUpdateResultData(\\n            name=adapter_provider_result.name,\\n            display_name=adapter_provider_result.display_name,\\n            created_app_ids=list(adapter_provider_result.created_app_ids),\\n            created_tools=created_tools,\\n        )\\n        return DeploymentUpdateResponse(\\n            id=deployment_row.id,\\n            provider_id=deployment_row.deployment_provider_account_id,\\n            provider_key=provider_key,\\n            description=deployment_row.description,\\n            type=deployment_row.deployment_type,\\n            created_at=deployment_row.created_at,\\n            updated_at=deployment_row.updated_at,\\n            resource_key=deployment_row.resource_key,\\n            provider_data=provider_api_result.model_dump(mode=\\\"json\\\"),\\n        )\\n\\n    def shape_llm_list_result(self, result: DeploymentListLlmsResult) -> DeploymentLlmListResponse:\\n        adapter_provider_result = self.parse_adapter_slot(\\n            slot=WXO_ADAPTER_PAYLOAD_SCHEMAS.deployment_llm_list_result,\\n            slot_name=\\\"deployment_llm_list_result\\\",\\n            raw=result.provider_result,\\n            operation=\\\"listing available models\\\",\\n        )\\n        api_slot = self.api_payloads.deployment_llm_list_result\\n        if api_slot is None:\\n            msg = \\\"Watsonx deployment_llm_list_result payload slot is not configured.\\\"\\n            raise HTTPException(status_code=status.HTTP_500_INTERNAL_SERVER_ERROR, detail=msg)\\n        try:  # straight pass-through today, so just dump + validate\\n            api_provider_result: WatsonxApiDeploymentLlmListResultData = api_slot.parse(\\n                adapter_provider_result.model_dump(exclude_none=True)\\n            )\\n        except AdapterPayloadMissingError as exc:\\n            raise HTTPException(\\n                status_code=status.HTTP_500_INTERNAL_SERVER_ERROR,\\n                detail=\\\"Deployment mapper llm list result payload is missing.\\\",\\n            ) from exc\\n        except AdapterPayloadValidationError as exc:\\n            detail = exc.format_first_error()\\n            raise HTTPException(\\n                status_code=status.HTTP_500_INTERNAL_SERVER_ERROR,\\n                detail=f\\\"Deployment mapper llm list result payload is invalid: {detail}\\\",\\n            ) from exc\\n        return DeploymentLlmListResponse(provider_data=api_provider_result.model_dump(mode=\\\"json\\\", exclude_none=True))\\n\\n    def util_create_snapshot_bindings(\\n        self,\\n        *,\\n        result: DeploymentCreateResult,\\n    ) -> CreateSnapshotBindings:\\n        slot = WXO_ADAPTER_PAYLOAD_SCHEMAS.deployment_create_result\\n        parsed = self.parse_adapter_slot(\\n            slot=slot,\\n            slot_name=\\\"deployment_create_result\\\",\\n            raw=result.provider_result,\\n            operation=\\\"creating the deployment\\\",\\n        )\\n        return CreateSnapshotBindings(\\n            snapshot_bindings=[\\n                CreateSnapshotBinding(\\n                    source_ref=binding.source_ref,\\n                    snapshot_id=binding.tool_id,\\n                )\\n                for binding in parsed.tools_with_refs\\n            ]\\n        )\\n\\n    def util_created_snapshot_ids(\\n        self,\\n        *,\\n        result: DeploymentUpdateResult,\\n    ) -> CreatedSnapshotIds:\\n        slot = WXO_ADAPTER_PAYLOAD_SCHEMAS.deployment_update_result\\n        parsed = self.parse_adapter_slot(\\n            slot=slot,\\n            slot_name=\\\"deployment_update_result\\\",\\n            raw=result.provider_result,\\n            operation=\\\"updating the deployment\\\",\\n        )\\n        if not parsed.created_snapshot_ids and not parsed.added_snapshot_bindings:\\n            msg = \\\"Deployment provider update result is missing required snapshot reconciliation bindings.\\\"\\n            raise HTTPException(status_code=status.HTTP_500_INTERNAL_SERVER_ERROR, detail=msg)\\n        return CreatedSnapshotIds(ids=parsed.created_snapshot_ids)\\n\\n    def util_update_snapshot_bindings(\\n        self,\\n        *,\\n        result: DeploymentUpdateResult,\\n    ) -> UpdateSnapshotBindings:\\n        \\\"\\\"\\\"Extract snapshot bindings for attachment reconciliation.\\n\\n        Only bindings whose ``source_ref`` is a valid UUID are included.\\n        Tool-id-based operations produce bindings with non-UUID\\n        ``source_ref`` values (the provider tool_id itself); these are\\n        excluded because they do not create or modify\\n        ``flow_version_deployment_attachment`` records.\\n        \\\"\\\"\\\"\\n        slot = WXO_ADAPTER_PAYLOAD_SCHEMAS.deployment_update_result\\n        parsed = self.parse_adapter_slot(\\n            slot=slot,\\n            slot_name=\\\"deployment_update_result\\\",\\n            raw=result.provider_result,\\n            operation=\\\"updating the deployment\\\",\\n        )\\n        if not parsed.created_snapshot_ids and not parsed.added_snapshot_bindings:\\n            msg = \\\"Deployment provider update result is missing required snapshot reconciliation bindings.\\\"\\n            raise HTTPException(status_code=status.HTTP_500_INTERNAL_SERVER_ERROR, detail=msg)\\n\\n        flow_version_bindings: list[UpdateSnapshotBinding] = []\\n        for binding in parsed.added_snapshot_bindings:\\n            try:\\n                UUID(binding.source_ref)\\n            except (ValueError, AttributeError):\\n                continue\\n            flow_version_bindings.append(\\n                UpdateSnapshotBinding(\\n                    source_ref=binding.source_ref,\\n                    snapshot_id=binding.tool_id,\\n                )\\n            )\\n        return UpdateSnapshotBindings(snapshot_bindings=flow_version_bindings)\\n\\n    def util_flow_version_patch(self, payload: DeploymentUpdateRequest) -> FlowVersionPatch:\\n        if \\\"provider_data\\\" not in payload.model_fields_set:\\n            # The update route uses this patch to reconcile DB attachments after\\n            # provider mutation. Metadata-only updates have no attachment delta;\\n            # explicit provider_data must still satisfy the wxO update schema.\\n            return FlowVersionPatch()\\n\\n        api_provider_payload: WatsonxApiDeploymentUpdatePayload = self.parse_api_request_slot(\\n            slot=self.api_payloads.deployment_update,\\n            slot_name=\\\"deployment_update\\\",\\n            raw=payload.provider_data,\\n        )\\n        add_ids = list(\\n            dict.fromkeys(\\n                item.flow_version_id\\n                for item in api_provider_payload.upsert_flows\\n                if item.add_app_ids or not item.remove_app_ids\\n            )\\n        )\\n        remove_ids = list(dict.fromkeys(api_provider_payload.remove_flows))\\n        return FlowVersionPatch(\\n            add_flow_version_ids=add_ids,\\n            remove_flow_version_ids=remove_ids,\\n        )\\n\\n    def shape_execution_create_result(\\n        self,\\n        result: ExecutionCreateResult,\\n        *,\\n        deployment_id: UUID,\\n    ) -> RunCreateResponse:\\n        adapter_provider_result = self.parse_adapter_slot(\\n            slot=WXO_ADAPTER_PAYLOAD_SCHEMAS.execution_create_result,\\n            slot_name=\\\"execution_create_result\\\",\\n            raw=result.provider_result,\\n            operation=\\\"starting the execution\\\",\\n        )\\n        api_provider_result = WatsonxApiAgentExecutionCreateResultData(\\n            id=adapter_provider_result.execution_id,\\n            agent_id=adapter_provider_result.agent_id,\\n            thread_id=adapter_provider_result.thread_id,\\n            status=adapter_provider_result.status,\\n            result=adapter_provider_result.result,\\n            started_at=adapter_provider_result.started_at,\\n            completed_at=adapter_provider_result.completed_at,\\n            failed_at=adapter_provider_result.failed_at,\\n            cancelled_at=adapter_provider_result.cancelled_at,\\n            last_error=adapter_provider_result.last_error,\\n        )\\n        return RunCreateResponse(\\n            deployment_id=deployment_id,\\n            provider_data=api_provider_result.model_dump(),\\n            # includes None intentionally, simply passes through\\n            # wxo api response, which can contain null values\\n        )\\n\\n    def shape_execution_status_result(\\n        self,\\n        result: ExecutionStatusResult,\\n        *,\\n        deployment_id: UUID,\\n    ) -> RunStatusResponse:\\n        adapter_provider_result = self.parse_adapter_slot(\\n            slot=WXO_ADAPTER_PAYLOAD_SCHEMAS.execution_status_result,\\n            slot_name=\\\"execution_status_result\\\",\\n            raw=result.provider_result,\\n            operation=\\\"checking execution status\\\",\\n        )\\n        api_provider_result = WatsonxApiAgentExecutionStatusResultData(\\n            id=adapter_provider_result.execution_id,\\n            agent_id=adapter_provider_result.agent_id,\\n            thread_id=adapter_provider_result.thread_id,\\n            status=adapter_provider_result.status,\\n            result=adapter_provider_result.result,\\n            started_at=adapter_provider_result.started_at,\\n            completed_at=adapter_provider_result.completed_at,\\n            failed_at=adapter_provider_result.failed_at,\\n            cancelled_at=adapter_provider_result.cancelled_at,\\n            last_error=adapter_provider_result.last_error,\\n        )\\n        return RunStatusResponse(\\n            deployment_id=deployment_id,\\n            provider_data=api_provider_result.model_dump(),\\n            # includes None intentionally, simply passes through\\n            # wxo api response, which can contain null values\\n        )\\n\\n    def shape_deployment_list_result(\\n        self,\\n        result: DeploymentListResult,\\n    ) -> DeploymentListResponse:\\n        provider_result = {\\n            \\\"deployments\\\": [self._shape_provider_deployment_list_entry(item) for item in result.deployments]\\n        }\\n        validated_payload = self.parse_adapter_slot(\\n            slot=self.api_payloads.deployment_list_result,\\n            slot_name=\\\"deployment_list_result\\\",\\n            raw=provider_result,\\n            operation=\\\"building deployment list provider payload\\\",\\n        )\\n        return DeploymentListResponse(\\n            deployments=None,\\n            provider_data=validated_payload.model_dump(mode=\\\"json\\\"),\\n        )\\n\\n    def shape_deployment_list_items(\\n        self,\\n        *,\\n        rows_with_counts: list[tuple[Any, int, list[tuple[UUID, str | None]]]],\\n        has_flow_filter: bool = False,\\n        provider_key: str,\\n        provider_data_by_resource_key: dict[str, dict[str, Any]] | None = None,\\n    ) -> list[DeploymentListItem]:\\n        if provider_data_by_resource_key is None:\\n            msg = \\\"provider_data_by_resource_key is required from wxO list sync.\\\"\\n            raise ValueError(msg)\\n\\n        items: list[DeploymentListItem] = []\\n        for row, attached_count, matched_attachments in rows_with_counts:\\n            provider_data = provider_data_by_resource_key.get(row.resource_key)\\n            if provider_data is None:\\n                msg = f\\\"Missing provider_data for wxO deployment resource_key={row.resource_key!r}.\\\"\\n                raise ValueError(msg)\\n            items.append(\\n                DeploymentListItem(\\n                    id=row.id,\\n                    provider_id=row.deployment_provider_account_id,\\n                    provider_key=provider_key,\\n                    resource_key=row.resource_key,\\n                    type=row.deployment_type,\\n                    description=row.description,\\n                    attached_count=attached_count,\\n                    created_at=row.created_at,\\n                    updated_at=row.updated_at,\\n                    flow_version_ids=[fv_id for fv_id, _ in matched_attachments] if has_flow_filter else None,\\n                    provider_data=provider_data,\\n                )\\n            )\\n        return items\\n\\n    def shape_config_list_result(\\n        self,\\n        result: ConfigListResult,\\n        *,\\n        page: int,\\n        size: int,\\n    ) -> DeploymentConfigListResponse:\\n        slot = self.api_payloads.config_list_result\\n        if slot is None:\\n            msg = \\\"Watsonx config_list_result payload slot is not configured.\\\"\\n            raise HTTPException(status_code=status.HTTP_500_INTERNAL_SERVER_ERROR, detail=msg)\\n\\n        items_all: list[WatsonxApiConfigListItem] = []\\n        for item in result.configs:\\n            if not isinstance(item.provider_data, dict):\\n                msg = \\\"Invalid config item provider_data payload: expected non-null object.\\\"\\n                raise HTTPException(status_code=status.HTTP_500_INTERNAL_SERVER_ERROR, detail=msg)\\n            items_all.append(\\n                self.shape_config_item_data(\\n                    {\\n                        **item.provider_data,\\n                        \\\"connection_id\\\": item.id,\\n                        \\\"app_id\\\": item.name,\\n                    }\\n                )\\n            )\\n        total = len(items_all)\\n        offset = page_offset(page, size)\\n        provider_payload = {\\n            \\\"connections\\\": [\\n                item.model_dump(mode=\\\"json\\\", exclude_none=True) for item in items_all[offset : offset + size]\\n            ],\\n            \\\"page\\\": page,\\n            \\\"size\\\": size,\\n            \\\"total\\\": total,\\n        }\\n        try:\\n            validated_payload = slot.parse(provider_payload).model_dump(mode=\\\"json\\\", exclude_none=True)\\n        except AdapterPayloadValidationError as exc:\\n            raise HTTPException(\\n                status_code=status.HTTP_500_INTERNAL_SERVER_ERROR,\\n                detail=f\\\"Invalid config list provider_data payload: {exc.format_first_error()}\\\",\\n            ) from exc\\n\\n        return DeploymentConfigListResponse(provider_data=validated_payload)\\n\\n    def shape_snapshot_list_result(\\n        self,\\n        result: SnapshotListResult,\\n        *,\\n        page: int,\\n        size: int,\\n    ) -> DeploymentSnapshotListResponse:\\n        slot = self.api_payloads.snapshot_list_result\\n        if slot is None:\\n            msg = \\\"Watsonx snapshot_list_result payload slot is not configured.\\\"\\n            raise HTTPException(status_code=status.HTTP_500_INTERNAL_SERVER_ERROR, detail=msg)\\n\\n        items_all: list[dict[str, Any]] = []\\n        for item in result.snapshots:\\n            item_provider_data = item.provider_data if isinstance(item.provider_data, dict) else {}\\n            connections = item_provider_data.get(\\\"connections\\\")\\n            display_name = item_provider_data.get(\\\"display_name\\\")\\n            items_all.append(\\n                {\\n                    \\\"id\\\": item.id,\\n                    \\\"name\\\": item.name,\\n                    \\\"display_name\\\": display_name,\\n                    \\\"connections\\\": connections if isinstance(connections, dict) else {},\\n                }\\n            )\\n\\n        total = len(items_all)\\n        offset = page_offset(page, size)\\n        provider_payload = {\\n            \\\"tools\\\": items_all[offset : offset + size],\\n            \\\"page\\\": page,\\n            \\\"size\\\": size,\\n            \\\"total\\\": total,\\n        }\\n        try:\\n            validated_payload = slot.parse(provider_payload).model_dump(mode=\\\"json\\\", exclude_none=True)\\n        except AdapterPayloadValidationError as exc:\\n            raise HTTPException(\\n                status_code=status.HTTP_500_INTERNAL_SERVER_ERROR,\\n                detail=f\\\"Invalid snapshot list provider_data payload: {exc.format_first_error()}\\\",\\n            ) from exc\\n\\n        return DeploymentSnapshotListResponse(provider_data=validated_payload)\\n\\n    def shape_flow_version_list_result(\\n        self,\\n        *,\\n        rows: list[tuple[FlowVersionDeploymentAttachment, FlowVersion, str | None]],\\n        snapshot_result: SnapshotListResult | None,\\n        page: int,\\n        size: int,\\n        total: int,\\n    ) -> DeploymentFlowVersionListResponse:\\n        normalized_rows = self._normalize_flow_version_attachment_rows(rows)\\n        flow_version_item_data_by_snapshot_id = self._resolve_flow_version_item_data_by_snapshot_id(\\n            snapshot_result=snapshot_result,\\n        )\\n\\n        flow_versions = [\\n            DeploymentFlowVersionListItem(\\n                id=row.flow_version.id,\\n                flow_id=row.flow_version.flow_id,\\n                flow_name=row.flow_name,\\n                version_number=row.flow_version.version_number,\\n                attached_at=row.attachment.created_at,\\n                provider_snapshot_id=row.snapshot_id,\\n                provider_data=flow_version_item_data_by_snapshot_id.get(row.snapshot_id),\\n            )\\n            for row in normalized_rows\\n        ]\\n\\n        return DeploymentFlowVersionListResponse(\\n            flow_versions=flow_versions,\\n            page=page,\\n            size=size,\\n            total=total,\\n        )\\n\\n    def _normalize_flow_version_attachment_rows(\\n        self,\\n        rows: list[tuple[FlowVersionDeploymentAttachment, FlowVersion, str | None]],\\n    ) -> list[_NormalizedAttachmentRow]:\\n        normalized_rows: list[_NormalizedAttachmentRow] = []\\n        for attachment, flow_version, flow_name in rows:\\n            snapshot_id = (attachment.provider_snapshot_id or \\\"\\\").strip()\\n            if not snapshot_id:\\n                msg = \\\"Flow version attachment has an invalid provider_snapshot_id.\\\"\\n                raise HTTPException(status_code=status.HTTP_500_INTERNAL_SERVER_ERROR, detail=msg)\\n            normalized_rows.append(\\n                _NormalizedAttachmentRow(\\n                    attachment=attachment,\\n                    flow_version=flow_version,\\n                    flow_name=flow_name,\\n                    snapshot_id=snapshot_id,\\n                )\\n            )\\n        return normalized_rows\\n\\n    def _resolve_flow_version_item_data_by_snapshot_id(\\n        self,\\n        *,\\n        snapshot_result: SnapshotListResult | None,\\n    ) -> dict[str, dict[str, Any]]:\\n        \\\"\\\"\\\"Build API flow-version item provider_data keyed by snapshot id.\\\"\\\"\\\"\\n        if snapshot_result is None:\\n            return {}\\n        if not snapshot_result.snapshots:\\n            return {}\\n\\n        item_data_by_snapshot_id: dict[str, dict[str, Any]] = {}\\n        for snapshot in snapshot_result.snapshots:\\n            snapshot_id = str(snapshot.id).strip()\\n            if not snapshot_id:\\n                msg = \\\"Invalid flow-version provider_data payload: snapshot id must be a non-empty string.\\\"\\n                raise HTTPException(status_code=status.HTTP_500_INTERNAL_SERVER_ERROR, detail=msg)\\n\\n            provider_data = snapshot.provider_data\\n\\n            if not isinstance(provider_data, dict) or not provider_data:\\n                msg = \\\"Invalid flow-version provider_data payload: snapshot provider_data must be a non-empty object.\\\"\\n                raise HTTPException(status_code=status.HTTP_500_INTERNAL_SERVER_ERROR, detail=msg)\\n\\n            raw_connections = provider_data.get(\\\"connections\\\")\\n            if not isinstance(raw_connections, dict):\\n                msg = \\\"Invalid flow-version provider_data payload: connections must be a dict.\\\"\\n                raise HTTPException(status_code=status.HTTP_500_INTERNAL_SERVER_ERROR, detail=msg)\\n            try:\\n                item_data_by_snapshot_id[snapshot_id] = self._validate_slot(\\n                    self.api_payloads.deployment_item_data,\\n                    {\\n                        \\\"app_ids\\\": list(raw_connections.keys()),\\n                        \\\"tool_name\\\": snapshot.name,\\n                        \\\"tool_display_name\\\": provider_data[\\\"display_name\\\"],\\n                    },\\n                )\\n            except KeyError as exc:\\n                raise HTTPException(\\n                    status_code=status.HTTP_500_INTERNAL_SERVER_ERROR,\\n                    detail=f\\\"Failed to load tool data for tool id {snapshot_id}\\\",\\n                ) from exc\\n            except AdapterPayloadValidationError as exc:\\n                detail = exc.format_first_error()\\n                raise HTTPException(\\n                    status_code=status.HTTP_500_INTERNAL_SERVER_ERROR,\\n                    detail=f\\\"Invalid flow-version provider_data payload: {detail}\\\",\\n                ) from exc\\n\\n        return item_data_by_snapshot_id\\n\\n    def _shape_provider_deployment_list_entry(self, item: ItemResult) -> dict[str, Any]:\\n        item_provider_data = item.provider_data\\n        if not isinstance(item_provider_data, dict):\\n            msg = \\\"Invalid deployment list item provider_data payload: expected object.\\\"\\n            raise HTTPException(status_code=status.HTTP_500_INTERNAL_SERVER_ERROR, detail=msg)\\n        return {\\n            **item_provider_data,\\n            \\\"id\\\": str(item.id),\\n            \\\"name\\\": item.name,\\n            \\\"type\\\": item.type,\\n            \\\"created_at\\\": item.created_at,\\n            \\\"updated_at\\\": item.updated_at,\\n        }\\n\\n    def shape_deployment_get_data(\\n        self,\\n        provider_data: AdapterPayload | None,\\n        *,\\n        name: str | None = None,\\n    ) -> dict[str, Any] | None:\\n        parsed = self.parse_adapter_slot(\\n            slot=WXO_ADAPTER_PAYLOAD_SCHEMAS.deployment_item_data,\\n            slot_name=\\\"deployment_item_data\\\",\\n            raw=provider_data,\\n            operation=\\\"reading deployment metadata\\\",\\n        )\\n        if name is None:\\n            msg = \\\"Missing deployment name while shaping wxO deployment metadata.\\\"\\n            raise HTTPException(status_code=status.HTTP_500_INTERNAL_SERVER_ERROR, detail=msg)\\n        return WatsonxApiDeploymentGetProviderData(\\n            llm=parsed.llm,\\n            name=name,\\n            display_name=parsed.display_name,\\n            environments=parsed.environments,\\n        ).model_dump(mode=\\\"json\\\")\\n\\n    def shape_config_item_data(self, provider_data: dict[str, Any]) -> WatsonxApiConfigListItem:\\n        return self.parse_adapter_slot(\\n            slot=self.api_payloads.config_item_data,\\n            slot_name=\\\"config_item_data\\\",\\n            raw=provider_data,\\n            operation=\\\"reading the configuration\\\",\\n        )\\n\\n    def _to_bind_provider_operation(self, *, raw_name: str, app_ids: list[str]) -> AdapterPayload:\\n        return {\\n            \\\"op\\\": \\\"bind\\\",\\n            \\\"tool\\\": {\\\"name_of_raw\\\": raw_name},\\n            \\\"app_ids\\\": app_ids,\\n        }\\n\\n    def _to_bind_existing_tool_provider_operation(\\n        self,\\n        *,\\n        tool_id: str,\\n        source_ref: str,\\n        app_ids: list[str],\\n    ) -> AdapterPayload:\\n        \\\"\\\"\\\"Bind operation that reuses an existing tool via tool_id_with_ref.\\\"\\\"\\\"\\n        return {\\n            \\\"op\\\": \\\"bind\\\",\\n            \\\"tool\\\": {\\\"tool_id_with_ref\\\": {\\\"source_ref\\\": source_ref, \\\"tool_id\\\": tool_id}},\\n            \\\"app_ids\\\": app_ids,\\n        }\\n\\n    def _to_attach_tool_provider_operation(self, *, tool_id: str, source_ref: str) -> AdapterPayload:\\n        \\\"\\\"\\\"Attach an existing tool to the agent without connection bindings.\\\"\\\"\\\"\\n        return {\\n            \\\"op\\\": \\\"attach_tool\\\",\\n            \\\"tool\\\": {\\\"source_ref\\\": source_ref, \\\"tool_id\\\": tool_id},\\n        }\\n\\n    def _to_unbind_provider_operation(\\n        self,\\n        *,\\n        tool_id: str,\\n        source_ref: str,\\n        app_ids: list[str],\\n    ) -> AdapterPayload:\\n        return {\\n            \\\"op\\\": \\\"unbind\\\",\\n            \\\"tool\\\": {\\\"source_ref\\\": source_ref, \\\"tool_id\\\": tool_id},\\n            \\\"app_ids\\\": app_ids,\\n        }\\n\\n    def _to_remove_tool_provider_operation(self, *, tool_id: str, source_ref: str) -> AdapterPayload:\\n        return {\\n            \\\"op\\\": \\\"remove_tool\\\",\\n            \\\"tool\\\": {\\\"source_ref\\\": source_ref, \\\"tool_id\\\": tool_id},\\n        }\\n\\n    def _build_provider_operations(\\n        self,\\n        *,\\n        add_flows: list[WatsonxApiAddFlowItem] | None = None,\\n        upsert_flows: list[WatsonxApiUpsertFlowItem] | None = None,\\n        upsert_tools: list[WatsonxApiUpsertToolItem] | list[WatsonxApiCreateUpsertToolItem] | None = None,\\n        remove_flows: list[UUID] | None = None,\\n        remove_tools: list[str] | None = None,\\n        flow_tool_by_flow_version_id: dict[UUID, _FlowToolPayload],\\n        flow_version_snapshot_id_map: dict[UUID, str] | None = None,\\n    ) -> list[AdapterPayload]:\\n        provider_operations: list[AdapterPayload] = []\\n        add_flows = add_flows or []\\n        upsert_flows = upsert_flows or []\\n        upsert_tools = upsert_tools or []\\n        remove_flows = remove_flows or []\\n        remove_tools = remove_tools or []\\n\\n        # Create path flow semantics.\\n        for item in add_flows:\\n            flow_version_id = item.flow_version_id\\n            existing_tool_id = (flow_version_snapshot_id_map or {}).get(flow_version_id)\\n            if existing_tool_id:\\n                if item.app_ids:\\n                    provider_operations.append(\\n                        self._to_bind_existing_tool_provider_operation(\\n                            tool_id=existing_tool_id,\\n                            source_ref=str(flow_version_id),\\n                            app_ids=item.app_ids,\\n                        )\\n                    )\\n                else:\\n                    provider_operations.append(\\n                        self._to_attach_tool_provider_operation(\\n                            tool_id=existing_tool_id,\\n                            source_ref=str(flow_version_id),\\n                        )\\n                    )\\n                continue\\n\\n            flow_tool = self._get_flow_tool_payload(\\n                flow_tool_by_flow_version_id=flow_tool_by_flow_version_id,\\n                flow_version_id=flow_version_id,\\n                field_name=\\\"add_flows item flow_version_id\\\",\\n            )\\n            if not item.app_ids:\\n                # Raw tool is still created via tools.raw_payloads;\\n                # no provider bind operation needed.\\n                continue\\n            provider_operations.append(\\n                self._to_bind_provider_operation(\\n                    raw_name=flow_tool[\\\"raw_name\\\"],\\n                    app_ids=item.app_ids,\\n                )\\n            )\\n\\n        # Update path flow semantics.\\n        for item in upsert_flows:\\n            flow_version_id = item.flow_version_id\\n            existing_tool_id = (flow_version_snapshot_id_map or {}).get(flow_version_id)\\n            if existing_tool_id:\\n                if item.add_app_ids:\\n                    provider_operations.append(\\n                        self._to_bind_existing_tool_provider_operation(\\n                            tool_id=existing_tool_id,\\n                            source_ref=str(flow_version_id),\\n                            app_ids=item.add_app_ids,\\n                        )\\n                    )\\n                elif not item.remove_app_ids:\\n                    # Empty add/remove means ensure attached.\\n                    provider_operations.append(\\n                        self._to_attach_tool_provider_operation(\\n                            tool_id=existing_tool_id,\\n                            source_ref=str(flow_version_id),\\n                        )\\n                    )\\n                if item.remove_app_ids:\\n                    provider_operations.append(\\n                        self._to_unbind_provider_operation(\\n                            tool_id=existing_tool_id,\\n                            source_ref=str(flow_version_id),\\n                            app_ids=item.remove_app_ids,\\n                        )\\n                    )\\n                if item.tool_display_name:\\n                    provider_operations.append(\\n                        {\\n                            \\\"op\\\": \\\"rename_tool\\\",\\n                            \\\"tool\\\": {\\n                                \\\"source_ref\\\": str(flow_version_id),\\n                                \\\"tool_id\\\": existing_tool_id,\\n                            },\\n                            \\\"tool_display_name\\\": item.tool_display_name,\\n                        }\\n                    )\\n                continue\\n\\n            if item.remove_app_ids:\\n                msg = (\\n                    \\\"Cannot resolve provider snapshot ids for flow_version_ids \\\"\\n                    f\\\"in watsonx operations: [{flow_version_id}]\\\"\\n                )\\n                raise HTTPException(status_code=status.HTTP_422_UNPROCESSABLE_CONTENT, detail=msg)\\n            flow_tool = self._get_flow_tool_payload(\\n                flow_tool_by_flow_version_id=flow_tool_by_flow_version_id,\\n                flow_version_id=flow_version_id,\\n                field_name=\\\"upsert_flows item flow_version_id\\\",\\n            )\\n            if item.add_app_ids:\\n                provider_operations.append(\\n                    self._to_bind_provider_operation(\\n                        raw_name=flow_tool[\\\"raw_name\\\"],\\n                        app_ids=item.add_app_ids,\\n                    )\\n                )\\n\\n        # Update flow removals.\\n        for flow_version_id in remove_flows:\\n            if flow_version_snapshot_id_map is None or flow_version_id not in flow_version_snapshot_id_map:\\n                msg = (\\n                    \\\"Cannot resolve provider snapshot ids for flow_version_ids \\\"\\n                    f\\\"in watsonx operations: [{flow_version_id}]\\\"\\n                )\\n                raise HTTPException(status_code=status.HTTP_422_UNPROCESSABLE_CONTENT, detail=msg)\\n            provider_operations.append(\\n                self._to_remove_tool_provider_operation(\\n                    tool_id=flow_version_snapshot_id_map[flow_version_id],\\n                    source_ref=str(flow_version_id),\\n                )\\n            )\\n\\n        # Tool-id-based semantics (create + update).\\n        for item in upsert_tools:\\n            tool_id = item.tool_id.strip()\\n            remove_app_ids = getattr(item, \\\"remove_app_ids\\\", []) or []\\n            if item.add_app_ids:\\n                provider_operations.append(\\n                    self._to_bind_existing_tool_provider_operation(\\n                        tool_id=tool_id,\\n                        source_ref=tool_id,\\n                        app_ids=item.add_app_ids,\\n                    )\\n                )\\n            elif not remove_app_ids:\\n                provider_operations.append(\\n                    self._to_attach_tool_provider_operation(\\n                        tool_id=tool_id,\\n                        source_ref=tool_id,\\n                    )\\n                )\\n            if remove_app_ids:\\n                provider_operations.append(\\n                    self._to_unbind_provider_operation(\\n                        tool_id=tool_id,\\n                        source_ref=tool_id,\\n                        app_ids=remove_app_ids,\\n                    )\\n                )\\n\\n        for tool_id in remove_tools:\\n            normalized_tool_id = str(tool_id).strip()\\n            provider_operations.append(\\n                self._to_remove_tool_provider_operation(\\n                    tool_id=normalized_tool_id,\\n                    source_ref=normalized_tool_id,\\n                )\\n            )\\n\\n        return provider_operations\\n\\n    def _build_provider_payload_body(\\n        self,\\n        *,\\n        llm: str | None,\\n        display_name: str | None,\\n        model_fields_set: set[str],\\n        raw_tool_payloads: list[dict[str, Any]],\\n        connections: list[Any],\\n        operations: list[AdapterPayload],\\n    ) -> dict[str, Any]:\\n        payload = {\\n            \\\"tools\\\": {\\n                \\\"raw_payloads\\\": raw_tool_payloads or None,\\n            },\\n            \\\"connections\\\": {\\n                \\\"raw_payloads\\\": self._dump_key_value_connection_payloads(connections),\\n            },\\n            \\\"operations\\\": operations,\\n        }\\n        if \\\"llm\\\" in model_fields_set:\\n            payload[\\\"llm\\\"] = llm\\n        if \\\"display_name\\\" in model_fields_set:\\n            payload[\\\"display_name\\\"] = display_name\\n        return payload\\n\\n    def _to_api_created_tools(\\n        self,\\n        *,\\n        adapter_created_snapshot_bindings: list[Any],\\n    ) -> list[WatsonxApiCreatedTool]:\\n        \\\"\\\"\\\"Map adapter created snapshot bindings to API ``created_tools``.\\\"\\\"\\\"\\n        created_tools: list[WatsonxApiCreatedTool] = []\\n        for binding in adapter_created_snapshot_bindings:\\n            tool_id = str(binding.tool_id or \\\"\\\").strip()\\n            source_ref = str(binding.source_ref or \\\"\\\").strip()\\n            if not tool_id or not source_ref:\\n                msg = (\\n                    f\\\"Created snapshot binding has empty tool_id={binding.tool_id!r} or \\\"\\n                    f\\\"source_ref={binding.source_ref!r}; cannot map tool binding.\\\"\\n                )\\n                raise HTTPException(status_code=status.HTTP_500_INTERNAL_SERVER_ERROR, detail=msg)\\n            try:\\n                created_tool = WatsonxApiCreatedTool(\\n                    flow_version_id=source_ref,\\n                    tool_id=tool_id,\\n                )\\n            except ValidationError as exc:\\n                msg = f\\\"Created snapshot binding has non-UUID source_ref={source_ref!r} for tool_id={tool_id!r}.\\\"\\n                raise HTTPException(status_code=status.HTTP_500_INTERNAL_SERVER_ERROR, detail=msg) from exc\\n            created_tools.append(created_tool)\\n        return created_tools\\n\\n    def _dump_key_value_connection_payloads(self, key_value_payloads: list[Any] | None) -> list[dict[str, Any]] | None:\\n        if not key_value_payloads:\\n            return None\\n        normalized: list[dict[str, Any]] = []\\n        for payload in key_value_payloads:\\n            item: dict[str, Any] = {\\\"app_id\\\": payload.app_id}\\n            environment_variables = self._to_adapter_environment_variables(payload.credentials)\\n            if environment_variables is not None:\\n                item[\\\"environment_variables\\\"] = environment_variables\\n            normalized.append(item)\\n        return normalized\\n\\n    def _to_adapter_environment_variables(self, credentials: list[Any] | None) -> dict[str, dict[str, Any]] | None:\\n        if not credentials:\\n            return None\\n        return {\\n            credential.key: {\\n                \\\"value\\\": credential.value,\\n                \\\"source\\\": credential.source,\\n            }\\n            for credential in credentials\\n        }\\n\\n    async def _lookup_snapshot_ids(\\n        self,\\n        *,\\n        user_id: UUID,\\n        deployment_db_id: UUID,\\n        db: AsyncSession,\\n        flow_version_ids: list[UUID],\\n    ) -> dict[UUID, str]:\\n        \\\"\\\"\\\"Raw DB lookup of flow_version -> provider_snapshot_id.\\n\\n        Returns a partial map -- only entries with a non-empty\\n        ``provider_snapshot_id`` are included.  Callers decide whether\\n        missing entries are an error or expected.\\n        \\\"\\\"\\\"\\n        if not flow_version_ids:\\n            return {}\\n        attachments = await list_deployment_attachments_for_flow_version_ids(\\n            db,\\n            user_id=user_id,\\n            deployment_id=deployment_db_id,\\n            flow_version_ids=flow_version_ids,\\n        )\\n        return {\\n            attachment.flow_version_id: str(attachment.provider_snapshot_id).strip()\\n            for attachment in attachments\\n            if isinstance(attachment.provider_snapshot_id, str) and attachment.provider_snapshot_id.strip()\\n        }\\n\\n    async def _resolve_existing_tool_snapshot_ids(\\n        self,\\n        *,\\n        user_id: UUID,\\n        deployment_db_id: UUID,\\n        db: AsyncSession,\\n        flow_version_ids: list[UUID],\\n    ) -> dict[UUID, str]:\\n        \\\"\\\"\\\"Strict lookup: raises 422 if any flow_version_id is missing.\\\"\\\"\\\"\\n        snapshot_map = await self._lookup_snapshot_ids(\\n            user_id=user_id,\\n            deployment_db_id=deployment_db_id,\\n            db=db,\\n            flow_version_ids=flow_version_ids,\\n        )\\n        missing_flow_versions = [\\n            str(flow_version_id) for flow_version_id in flow_version_ids if flow_version_id not in snapshot_map\\n        ]\\n        if missing_flow_versions:\\n            msg = (\\n                \\\"Cannot resolve provider snapshot ids for flow_version_ids in watsonx operations: \\\"\\n                f\\\"{missing_flow_versions}\\\"\\n            )\\n            raise HTTPException(status_code=status.HTTP_422_UNPROCESSABLE_CONTENT, detail=msg)\\n        return snapshot_map\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/api/v1/mappers/deployments/watsonx_orchestrate/payloads.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"b17f96cfe506cafbb89037b94f9ad6e3900db5c8eae8b80a8fe60cdb0ba1b50f\",\"content\":\"\\\"\\\"\\\"Watsonx deployment payload models at API boundary.\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nfrom collections import Counter\\nfrom datetime import datetime\\nfrom typing import TYPE_CHECKING, Annotated, Any, Literal\\nfrom uuid import UUID\\n\\nfrom lfx.services.adapters.deployment.schema import DeploymentType\\nfrom pydantic import (\\n    AfterValidator,\\n    BaseModel,\\n    Field,\\n    StringConstraints,\\n    ValidationInfo,\\n    field_validator,\\n    model_validator,\\n)\\n\\nfrom langflow.api.v1.schemas.deployments import ValidatedUrl\\nfrom langflow.services.database.models.deployment_provider_account.utils import validate_provider_url\\n\\nif TYPE_CHECKING:\\n    from langflow.api.v1.schemas.deployments import DeploymentCreateRequest\\n\\n# Keep API-boundary scalar normalization local to this module instead of\\n# importing adapter-layer aliases, so mapper contracts can evolve independently.\\nNormalizedStr = Annotated[\\n    str,\\n    StringConstraints(\\n        strip_whitespace=True,\\n        min_length=1,\\n    ),\\n]\\n\\n\\ndef _validate_non_empty_string(value: str) -> str:\\n    if not value.strip():\\n        msg = \\\"String must not be empty.\\\"\\n        raise ValueError(msg)\\n    return value\\n\\n\\nNonEmptyString = Annotated[str, AfterValidator(_validate_non_empty_string)]\\n\\n\\nclass WatsonxApiProviderAccountCreate(BaseModel):\\n    \\\"\\\"\\\"WXO provider-account provider_data contract at API boundary.\\n\\n    This schema is owned by the WXO mapper and parsed once to validate the\\n    provider-account provider_data payload before URL policy checks, credential\\n    verification payload shaping, and DB field extraction.\\n    \\\"\\\"\\\"\\n\\n    model_config = {\\\"extra\\\": \\\"forbid\\\"}\\n\\n    url: ValidatedUrl\\n    tenant_id: Annotated[str | None, StringConstraints(strip_whitespace=True, min_length=1)] = None\\n    api_key: Annotated[str, StringConstraints(strip_whitespace=True, min_length=1)]\\n\\n\\nclass WatsonxApiProviderAccountUpdate(BaseModel):\\n    \\\"\\\"\\\"WXO mutable provider-account fields for update requests.\\n\\n    Only credential rotation is supported after create. URL and tenant are\\n    immutable and therefore intentionally absent from this schema.\\n    \\\"\\\"\\\"\\n\\n    model_config = {\\\"extra\\\": \\\"forbid\\\"}\\n\\n    api_key: Annotated[str, StringConstraints(strip_whitespace=True, min_length=1)]\\n\\n\\nclass WatsonxApiProviderAccountResponse(BaseModel):\\n    \\\"\\\"\\\"WXO provider-account provider_data contract for API responses.\\\"\\\"\\\"\\n\\n    model_config = {\\\"extra\\\": \\\"forbid\\\"}\\n\\n    url: Annotated[str, StringConstraints(strip_whitespace=True, min_length=1)]\\n    tenant_id: Annotated[str, StringConstraints(strip_whitespace=True, min_length=1)]\\n\\n    @field_validator(\\\"url\\\")\\n    @classmethod\\n    def validate_url_without_rewriting(cls, value: str) -> str:\\n        # Validate URL policy but preserve stored representation.\\n        validate_provider_url(value, field_name=\\\"url\\\")\\n        return value\\n\\n\\nclass WatsonxApiAddFlowItem(BaseModel):\\n    \\\"\\\"\\\"Create-time flow item (tool is created/attached if absent).\\\"\\\"\\\"\\n\\n    model_config = {\\\"extra\\\": \\\"forbid\\\"}\\n\\n    flow_version_id: UUID\\n    app_ids: list[NormalizedStr] = Field(\\n        default_factory=list,\\n        description=(\\n            \\\"Connection app ids to bind. Use an empty list to create/attach \\\"\\n            \\\"the flow version as a tool with no connection bindings.\\\"\\n        ),\\n    )\\n    tool_display_name: NormalizedStr | None = Field(\\n        default=None,\\n        description=(\\\"Optional user-provided tool label. When omitted, the label is derived from the flow name.\\\"),\\n    )\\n\\n\\nclass WatsonxApiUpsertFlowItem(BaseModel):\\n    \\\"\\\"\\\"Update-time flow item with per-item add/remove app-id deltas.\\\"\\\"\\\"\\n\\n    model_config = {\\\"extra\\\": \\\"forbid\\\"}\\n\\n    flow_version_id: UUID\\n    add_app_ids: list[NormalizedStr] = Field(\\n        default_factory=list,\\n        description=(\\\"Connection app ids to bind. Use an empty list to avoid adding new bindings.\\\"),\\n    )\\n    remove_app_ids: list[NormalizedStr] = Field(\\n        default_factory=list,\\n        description=(\\\"Connection app ids to unbind. Use an empty list to avoid removing bindings.\\\"),\\n    )\\n    tool_display_name: NormalizedStr | None = Field(\\n        default=None,\\n        description=(\\\"Optional user-provided tool label. When omitted, the label is derived from the flow name.\\\"),\\n    )\\n\\n\\nclass WatsonxApiCreateUpsertToolItem(BaseModel):\\n    \\\"\\\"\\\"Create-time existing provider tool item (add connections only).\\\"\\\"\\\"\\n\\n    model_config = {\\\"extra\\\": \\\"forbid\\\"}\\n\\n    tool_id: NormalizedStr = Field(description=\\\"Provider-owned tool identifier.\\\")\\n    add_app_ids: list[NormalizedStr] = Field(\\n        default_factory=list,\\n        description=(\\\"Connection app ids to bind. Use an empty list to attach the tool without connection bindings.\\\"),\\n    )\\n\\n\\nclass WatsonxApiUpsertToolItem(BaseModel):\\n    \\\"\\\"\\\"Update-time existing provider tool item with per-item add/remove app-id deltas.\\\"\\\"\\\"\\n\\n    model_config = {\\\"extra\\\": \\\"forbid\\\"}\\n\\n    tool_id: NormalizedStr = Field(description=\\\"Provider-owned tool identifier.\\\")\\n    add_app_ids: list[NormalizedStr] = Field(\\n        default_factory=list,\\n        description=(\\\"Connection app ids to bind. Use an empty list to avoid adding new bindings.\\\"),\\n    )\\n    remove_app_ids: list[NormalizedStr] = Field(\\n        default_factory=list,\\n        description=(\\\"Connection app ids to unbind. Use an empty list to avoid removing bindings.\\\"),\\n    )\\n\\n\\nclass WatsonxApiConnectionCredentialItem(BaseModel):\\n    \\\"\\\"\\\"API-facing connection credential declaration.\\\"\\\"\\\"\\n\\n    model_config = {\\\"extra\\\": \\\"forbid\\\"}\\n\\n    key: Annotated[str, StringConstraints(strip_whitespace=True, min_length=1)]\\n    value: Annotated[str, StringConstraints(strip_whitespace=True, min_length=1)]\\n    source: Literal[\\\"raw\\\", \\\"variable\\\"] = \\\"variable\\\"\\n\\n\\nclass WatsonxApiKeyValueConnectionPayload(BaseModel):\\n    \\\"\\\"\\\"API-facing key-value connection payload for app id.\\n\\n    Today this API only accepts key-value connections, so ``connections`` is a\\n    flat list of this payload shape with no explicit ``type`` discriminator.\\n    When additional connection types are introduced, a ``type`` field can be\\n    added with a default of ``\\\"key_value\\\"`` for backward compatibility.\\n    \\\"\\\"\\\"\\n\\n    model_config = {\\\"extra\\\": \\\"forbid\\\"}\\n\\n    app_id: NormalizedStr\\n    credentials: list[WatsonxApiConnectionCredentialItem] | None = None\\n\\n    @field_validator(\\\"credentials\\\")\\n    @classmethod\\n    def validate_unique_credential_keys(\\n        cls,\\n        value: list[WatsonxApiConnectionCredentialItem] | None,\\n    ) -> list[WatsonxApiConnectionCredentialItem] | None:\\n        if value is None:\\n            return None\\n        seen: set[str] = set()\\n        duplicates: set[str] = set()\\n        for item in value:\\n            if item.key in seen:\\n                duplicates.add(item.key)\\n            seen.add(item.key)\\n        if duplicates:\\n            msg = f\\\"credentials contains duplicate key values: {sorted(duplicates)}\\\"\\n            raise ValueError(msg)\\n        return value\\n\\n\\ndef _collect_api_referenced_app_ids(operations: list[Any], *, attr_name: str = \\\"app_ids\\\") -> set[str]:\\n    referenced_app_ids: set[str] = set()\\n    for operation in operations:\\n        operation_app_ids = getattr(operation, attr_name, None)\\n        if not operation_app_ids:\\n            continue\\n        referenced_app_ids.update(operation_app_ids)\\n    return referenced_app_ids\\n\\n\\ndef _validate_api_remove_not_raw(*, operations: list[Any], raw_app_ids: set[str], attr_name: str, label: str) -> None:\\n    for operation in operations:\\n        remove_app_ids = getattr(operation, attr_name, None)\\n        if not remove_app_ids:\\n            continue\\n        invalid_raw = sorted(raw_app_ids.intersection(set(remove_app_ids)))\\n        if invalid_raw:\\n            msg = f\\\"{label} must not reference connections app_ids: {invalid_raw}\\\"\\n            raise ValueError(msg)\\n\\n\\ndef _validate_api_add_remove_overlap(*, operations: list[Any], label: str) -> None:\\n    for operation in operations:\\n        add_app_ids = set(getattr(operation, \\\"add_app_ids\\\", []) or [])\\n        remove_app_ids = set(getattr(operation, \\\"remove_app_ids\\\", []) or [])\\n        overlap = sorted(add_app_ids.intersection(remove_app_ids))\\n        if overlap:\\n            msg = f\\\"{label} add_app_ids and remove_app_ids must not overlap: {overlap}\\\"\\n            raise ValueError(msg)\\n\\n\\ndef _validate_api_remove_conflicts(\\n    *,\\n    remove_ids: list[Any],\\n    upsert_operations: list[Any],\\n    remove_label: str,\\n    upsert_attr_name: str,\\n) -> None:\\n    normalized_remove_ids = {str(remove_id).strip() for remove_id in remove_ids if str(remove_id).strip()}\\n    normalized_upsert_ids = {\\n        str(getattr(operation, upsert_attr_name, \\\"\\\")).strip()\\n        for operation in upsert_operations\\n        if str(getattr(operation, upsert_attr_name, \\\"\\\")).strip()\\n    }\\n    conflicts = sorted(normalized_remove_ids.intersection(normalized_upsert_ids))\\n    if conflicts:\\n        msg = f\\\"{remove_label} cannot be combined with upsert for the same id: {conflicts}\\\"\\n        raise ValueError(msg)\\n\\n\\ndef _validate_api_unused_raw_app_ids(*, raw_app_ids: set[str], referenced_app_ids: set[str]) -> None:\\n    unused_raw_app_ids = sorted(raw_app_ids.difference(referenced_app_ids))\\n    if unused_raw_app_ids:\\n        msg = f\\\"connections contains app_id values not referenced by operations: {unused_raw_app_ids}\\\"\\n        raise ValueError(msg)\\n\\n\\ndef _validate_api_unique_connection_app_ids(*, connections: list[WatsonxApiKeyValueConnectionPayload]) -> None:\\n    app_id_counts = Counter(connection.app_id for connection in connections)\\n    duplicates = sorted(app_id for app_id, count in app_id_counts.items() if count > 1)\\n    if duplicates:\\n        msg = f\\\"connections contains duplicate app_id values: {duplicates}\\\"\\n        raise ValueError(msg)\\n\\n\\nclass WatsonxApiDeploymentUpdatePayload(BaseModel):\\n    \\\"\\\"\\\"Watsonx provider_data API contract for deployment update operations.\\n\\n    All operation fields default to empty lists so LLM-only updates\\n    (changing the model without any tool/connection changes) can be\\n    expressed without providing operation entries.\\n    \\\"\\\"\\\"\\n\\n    model_config = {\\\"extra\\\": \\\"forbid\\\"}\\n\\n    display_name: NormalizedStr | None = Field(\\n        default=None,\\n        description=\\\"Optional user-facing label to set on the wxO agent.\\\",\\n    )\\n    llm: NormalizedStr | None = Field(\\n        default=None,\\n        description=(\\n            \\\"Optional provider model identifier to use for the deployment agent. \\\"\\n            \\\"When omitted, the current model is preserved.\\\"\\n        ),\\n    )\\n    connections: list[WatsonxApiKeyValueConnectionPayload] = Field(default_factory=list)\\n    upsert_flows: list[WatsonxApiUpsertFlowItem] = Field(default_factory=list)\\n    upsert_tools: list[WatsonxApiUpsertToolItem] = Field(default_factory=list)\\n    remove_flows: list[UUID] = Field(default_factory=list)\\n    remove_tools: list[NormalizedStr] = Field(default_factory=list)\\n\\n    @field_validator(\\\"display_name\\\", \\\"llm\\\", mode=\\\"before\\\")\\n    @classmethod\\n    def reject_null_optional_strings(cls, value: Any, info: ValidationInfo) -> Any:\\n        if value is None:\\n            msg = f\\\"{info.field_name} cannot be set to null.\\\"\\n            raise ValueError(msg)\\n        return value\\n\\n    @model_validator(mode=\\\"after\\\")\\n    def validate_operation_references(self) -> WatsonxApiDeploymentUpdatePayload:\\n        _validate_api_unique_connection_app_ids(connections=self.connections)\\n        raw_app_ids = {raw.app_id for raw in self.connections}\\n        referenced_app_ids = _collect_api_referenced_app_ids(self.upsert_flows, attr_name=\\\"add_app_ids\\\")\\n        referenced_app_ids.update(_collect_api_referenced_app_ids(self.upsert_tools, attr_name=\\\"add_app_ids\\\"))\\n        _validate_api_remove_not_raw(\\n            operations=self.upsert_flows,\\n            raw_app_ids=raw_app_ids,\\n            attr_name=\\\"remove_app_ids\\\",\\n            label=\\\"upsert_flows.remove_app_ids\\\",\\n        )\\n        _validate_api_remove_not_raw(\\n            operations=self.upsert_tools,\\n            raw_app_ids=raw_app_ids,\\n            attr_name=\\\"remove_app_ids\\\",\\n            label=\\\"upsert_tools.remove_app_ids\\\",\\n        )\\n        _validate_api_add_remove_overlap(operations=self.upsert_flows, label=\\\"upsert_flows\\\")\\n        _validate_api_add_remove_overlap(operations=self.upsert_tools, label=\\\"upsert_tools\\\")\\n        _validate_api_remove_conflicts(\\n            remove_ids=self.remove_flows,\\n            upsert_operations=self.upsert_flows,\\n            remove_label=\\\"remove_flows\\\",\\n            upsert_attr_name=\\\"flow_version_id\\\",\\n        )\\n        _validate_api_remove_conflicts(\\n            remove_ids=self.remove_tools,\\n            upsert_operations=self.upsert_tools,\\n            remove_label=\\\"remove_tools\\\",\\n            upsert_attr_name=\\\"tool_id\\\",\\n        )\\n        _validate_api_unused_raw_app_ids(raw_app_ids=raw_app_ids, referenced_app_ids=referenced_app_ids)\\n        return self\\n\\n\\nclass WatsonxApiDeploymentCreatePayload(BaseModel):\\n    \\\"\\\"\\\"Watsonx provider_data API contract for deployment create operations.\\\"\\\"\\\"\\n\\n    model_config = {\\\"extra\\\": \\\"forbid\\\"}\\n\\n    display_name: NormalizedStr | None = Field(\\n        default=None,\\n        description=(\\n            \\\"User-facing label to set on a new wxO agent. \\\"\\n            \\\"Required unless tracking an existing wxO agent in Langflow (via ``existing_agent_id`` field).\\\"\\n        ),\\n    )\\n    llm: NormalizedStr | None = Field(\\n        default=None,\\n        description=(\\n            \\\"Provider model identifier to use for a new wxO agent.\\\"\\n            \\\"Required unless tracking an existing wxO agent in Langflow (via ``existing_agent_id`` field).\\\"\\n        ),\\n    )\\n    connections: list[WatsonxApiKeyValueConnectionPayload] = Field(default_factory=list)\\n    add_flows: list[WatsonxApiAddFlowItem] = Field(default_factory=list)\\n    upsert_tools: list[WatsonxApiCreateUpsertToolItem] = Field(default_factory=list)\\n    existing_agent_id: NormalizedStr | None = Field(\\n        default=None,\\n        description=(\\n            \\\"Provider-owned agent id to track in Langflow instead of creating a new wxO agent. \\\"\\n            \\\"When provided, the request must not include fields that would update the wxO agent.\\\"\\n        ),\\n    )\\n\\n    @model_validator(mode=\\\"after\\\")\\n    def validate_create_operation_requirements(self) -> WatsonxApiDeploymentCreatePayload:\\n        if \\\"existing_agent_id\\\" in self.model_fields_set:\\n            if self.existing_agent_id is None:\\n                msg = \\\"provider_data.existing_agent_id cannot be set to null.\\\"\\n                raise ValueError(msg)\\n            if len(self.model_fields_set) > 1:\\n                msg = (\\n                    \\\"existing_agent_id is only for tracking existing wxO agents in Langflow and cannot include \\\"\\n                    \\\"fields that update the wxO agent. Update the deployment after it is tracked.\\\"\\n                )\\n                raise ValueError(msg)\\n            return self\\n        if self.display_name is None:\\n            msg = \\\"provider_data.display_name is required for new agent creation.\\\"\\n            raise ValueError(msg)\\n        if self.llm is None:\\n            msg = \\\"provider_data.llm is required for new agent creation.\\\"\\n            raise ValueError(msg)\\n        # TODO: Allow wxO agent creation without initial flows/tools once the adapter create path supports it.\\n        if not (self.add_flows or self.upsert_tools):\\n            msg = \\\"provider_data must include at least one add_flows or upsert_tools item for new agent creation.\\\"\\n            raise ValueError(msg)\\n        _validate_api_unique_connection_app_ids(connections=self.connections)\\n        raw_app_ids = {raw.app_id for raw in self.connections}\\n        referenced_app_ids = _collect_api_referenced_app_ids(self.add_flows, attr_name=\\\"app_ids\\\")\\n        referenced_app_ids.update(_collect_api_referenced_app_ids(self.upsert_tools, attr_name=\\\"add_app_ids\\\"))\\n        _validate_api_unused_raw_app_ids(raw_app_ids=raw_app_ids, referenced_app_ids=referenced_app_ids)\\n        return self\\n\\n    def validate_with_outer_fields(self, outer_payload: DeploymentCreateRequest) -> None:\\n        if self.existing_agent_id is None or \\\"description\\\" not in outer_payload.model_fields_set:\\n            return\\n        msg = \\\"When existing_agent_id is provided, Langflow uses the description already set for the agent in wxO.\\\"\\n        raise ValueError(msg)\\n\\n\\nclass WatsonxApiCreatedTool(BaseModel):\\n    \\\"\\\"\\\"API response shape for a tool created from a Langflow flow version.\\\"\\\"\\\"\\n\\n    model_config = {\\\"extra\\\": \\\"forbid\\\"}\\n\\n    flow_version_id: UUID\\n    tool_id: NonEmptyString = Field(description=\\\"Provider-owned tool identifier.\\\")\\n\\n    @field_validator(\\\"flow_version_id\\\", mode=\\\"before\\\")\\n    @classmethod\\n    def normalize_flow_version_id(cls, value: Any) -> UUID:\\n        if isinstance(value, UUID):\\n            return value\\n        if not isinstance(value, str):\\n            msg = \\\"flow_version_id must be provided as a UUID string or UUID object.\\\"\\n            raise ValueError(msg)  # noqa: TRY004\\n        try:\\n            return UUID(value)\\n        except ValueError as exc:\\n            msg = \\\"flow_version_id must be a valid UUID.\\\"\\n            raise ValueError(msg) from exc\\n\\n\\nclass WatsonxApiDeploymentCreateResultData(BaseModel):\\n    \\\"\\\"\\\"Provider-result payload used by Watsonx mapper create shapers.\\\"\\\"\\\"\\n\\n    model_config = {\\\"extra\\\": \\\"ignore\\\"}\\n\\n    name: NonEmptyString = Field(description=\\\"Provider technical agent name.\\\")\\n    display_name: NonEmptyString\\n    created_app_ids: list[NonEmptyString] = Field(default_factory=list)\\n    created_tools: list[WatsonxApiCreatedTool] = Field(default_factory=list)\\n\\n    @classmethod\\n    def from_provider_result(cls, provider_result: Any) -> WatsonxApiDeploymentCreateResultData:\\n        return cls.model_validate(provider_result)\\n\\n\\nclass WatsonxApiDeploymentUpdateResultData(BaseModel):\\n    \\\"\\\"\\\"Provider-result payload used by Watsonx mapper update shapers.\\\"\\\"\\\"\\n\\n    model_config = {\\\"extra\\\": \\\"ignore\\\"}\\n\\n    name: NonEmptyString = Field(description=\\\"Provider technical agent name.\\\")\\n    display_name: NonEmptyString\\n    created_app_ids: list[NonEmptyString] = Field(default_factory=list)\\n    created_tools: list[WatsonxApiCreatedTool] = Field(default_factory=list)\\n\\n    @classmethod\\n    def from_provider_result(cls, provider_result: Any) -> WatsonxApiDeploymentUpdateResultData:\\n        return cls.model_validate(provider_result)\\n\\n\\nclass WatsonxApiModelOut(BaseModel):\\n    \\\"\\\"\\\"Minimal API-boundary model metadata needed for deployment LLM listing.\\\"\\\"\\\"\\n\\n    model_config = {\\\"extra\\\": \\\"ignore\\\"}\\n\\n    model_name: NonEmptyString\\n\\n\\nclass WatsonxApiDeploymentLlmListResultData(BaseModel):\\n    \\\"\\\"\\\"API-boundary payload used by mapper LLM-list response shaping.\\\"\\\"\\\"\\n\\n    model_config = {\\\"extra\\\": \\\"forbid\\\"}\\n\\n    models: list[WatsonxApiModelOut] = Field(default_factory=list)\\n\\n\\nclass WatsonxApiProviderDeploymentListItem(BaseModel):\\n    \\\"\\\"\\\"Provider-only deployment item returned in list provider_data.\\\"\\\"\\\"\\n\\n    model_config = {\\\"extra\\\": \\\"forbid\\\"}\\n\\n    id: NonEmptyString = Field(description=\\\"Provider-owned deployment identifier.\\\")\\n    name: NonEmptyString\\n    display_name: NonEmptyString\\n    type: DeploymentType\\n    description: str\\n    created_at: datetime\\n    updated_at: datetime\\n    tool_ids: list[NonEmptyString] = Field(default_factory=list)\\n    llm: NonEmptyString\\n    environments: list[NonEmptyString] = Field(default_factory=list)\\n\\n\\nclass WatsonxApiDeploymentListItemProviderData(BaseModel):\\n    \\\"\\\"\\\"Per-item provider_data surfaced on synced wxO deployment list rows.\\\"\\\"\\\"\\n\\n    model_config = {\\\"extra\\\": \\\"forbid\\\"}\\n\\n    name: NonEmptyString\\n    display_name: NonEmptyString\\n    llm: NonEmptyString\\n    environments: list[NonEmptyString]\\n\\n\\nclass WatsonxApiDeploymentGetProviderData(BaseModel):\\n    \\\"\\\"\\\"Provider_data surfaced on wxO deployment detail responses.\\\"\\\"\\\"\\n\\n    model_config = {\\\"extra\\\": \\\"forbid\\\"}\\n\\n    llm: NonEmptyString\\n    name: NonEmptyString\\n    display_name: NonEmptyString\\n    environments: list[NonEmptyString]\\n\\n\\nclass WatsonxApiDeploymentListProviderData(BaseModel):\\n    \\\"\\\"\\\"Provider-level metadata attached to DeploymentListResponse.provider_data.\\\"\\\"\\\"\\n\\n    deployments: list[WatsonxApiProviderDeploymentListItem] = Field(default_factory=list)\\n\\n\\nclass WatsonxApiConfigListItem(BaseModel):\\n    \\\"\\\"\\\"API-facing config list item payload under config-list provider_data.\\\"\\\"\\\"\\n\\n    model_config = {\\\"extra\\\": \\\"forbid\\\"}\\n\\n    connection_id: NonEmptyString\\n    app_id: NonEmptyString\\n    type: NonEmptyString\\n    environment: NonEmptyString\\n\\n\\nclass WatsonxApiConfigListProviderData(BaseModel):\\n    \\\"\\\"\\\"Provider-level metadata attached to DeploymentConfigListResponse.\\\"\\\"\\\"\\n\\n    model_config = {\\\"extra\\\": \\\"forbid\\\"}\\n\\n    connections: list[WatsonxApiConfigListItem] = Field(default_factory=list)\\n    page: int | None = Field(default=None, ge=1)\\n    size: int | None = Field(default=None, ge=1)\\n    total: int | None = Field(default=None, ge=0)\\n\\n\\nclass WatsonxApiSnapshotListItem(BaseModel):\\n    \\\"\\\"\\\"API-facing snapshot list item payload under snapshot-list provider_data.\\\"\\\"\\\"\\n\\n    model_config = {\\\"extra\\\": \\\"forbid\\\"}\\n\\n    id: NonEmptyString\\n    name: NonEmptyString\\n    display_name: NonEmptyString\\n    connections: dict[NonEmptyString, NonEmptyString] = Field(default_factory=dict)\\n\\n\\nclass WatsonxApiSnapshotListProviderData(BaseModel):\\n    \\\"\\\"\\\"Provider-level metadata attached to DeploymentSnapshotListResponse.\\\"\\\"\\\"\\n\\n    model_config = {\\\"extra\\\": \\\"forbid\\\"}\\n\\n    tools: list[WatsonxApiSnapshotListItem] = Field(default_factory=list)\\n    page: int | None = Field(default=None, ge=1)\\n    size: int | None = Field(default=None, ge=1)\\n    total: int | None = Field(default=None, ge=0)\\n\\n\\nclass WatsonxApiDeploymentFlowVersionItemData(BaseModel):\\n    \\\"\\\"\\\"API-facing provider_data contract for deployment flow-version list items.\\n\\n    ``tool_name`` is the provider technical name, while ``tool_display_name`` is\\n    the user-facing label. Missing or blank values indicate corrupt provider\\n    data and the mapper intentionally rejects them with a 500 so the issue\\n    surfaces immediately.\\n    \\\"\\\"\\\"\\n\\n    model_config = {\\\"extra\\\": \\\"forbid\\\"}\\n\\n    app_ids: list[NonEmptyString] = Field(default_factory=list)\\n    tool_name: NonEmptyString\\n    tool_display_name: NonEmptyString\\n\\n\\nclass WatsonxApiExecutionInput(BaseModel):\\n    \\\"\\\"\\\"API-facing provider_data payload for POST deployment runs.\\\"\\\"\\\"\\n\\n    model_config = {\\\"extra\\\": \\\"forbid\\\"}\\n\\n    input: str | None = None\\n    message: dict[str, Any] | None = None\\n    thread_id: str | None = None\\n\\n    @model_validator(mode=\\\"after\\\")\\n    def validate_input_or_message_exclusive(self) -> WatsonxApiExecutionInput:\\n        has_input = self.input is not None\\n        has_message = self.message is not None\\n        if has_input == has_message:\\n            msg = \\\"provider_data must include exactly one of 'input' or 'message'.\\\"\\n            raise ValueError(msg)\\n        return self\\n\\n\\nclass _WatsonxApiAgentExecutionResultBase(BaseModel):\\n    \\\"\\\"\\\"Shared fields for API-facing agent execution result payloads.\\n\\n    All provider-owned identifiers and metadata live here inside\\n    ``provider_data``.  The enclosing response only carries Langflow-owned\\n    fields (``deployment_id``).  ``deployment_id`` (Langflow DB UUID) is\\n    intentionally omitted from this schema to avoid ownership confusion.\\n    \\\"\\\"\\\"\\n\\n    model_config = {\\\"extra\\\": \\\"allow\\\"}\\n\\n    id: NonEmptyString | None = None\\n    agent_id: NonEmptyString | None = None\\n    thread_id: NonEmptyString | None = None\\n    status: str | None = None\\n    result: Any | None = None\\n    started_at: str | None = None\\n    completed_at: str | None = None\\n    failed_at: str | None = None\\n    cancelled_at: str | None = None\\n    last_error: str | None = None\\n\\n    @classmethod\\n    def from_provider_result(cls, provider_result: Any) -> _WatsonxApiAgentExecutionResultBase:\\n        if not isinstance(provider_result, dict):\\n            return cls()\\n        return cls.model_validate(provider_result)\\n\\n\\nclass WatsonxApiAgentExecutionCreateResultData(_WatsonxApiAgentExecutionResultBase):\\n    \\\"\\\"\\\"API-facing provider_result payload returned when an agent execution is created.\\\"\\\"\\\"\\n\\n\\nclass WatsonxApiAgentExecutionStatusResultData(_WatsonxApiAgentExecutionResultBase):\\n    \\\"\\\"\\\"API-facing provider_result payload returned when querying agent execution status.\\\"\\\"\\\"\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/api/v1/mcp.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"001a3bed8cb0af920d6e5fdc1e7fc760b9115eccf16825006b595f714b915f03\",\"content\":\"import asyncio\\nfrom typing import Any\\n\\nimport pydantic\\nfrom anyio import BrokenResourceError\\nfrom fastapi import APIRouter, Depends, HTTPException, Request, Response\\nfrom fastapi.responses import HTMLResponse\\nfrom lfx.log.logger import logger\\nfrom mcp import types\\nfrom mcp.server import NotificationOptions, Server\\nfrom mcp.server.auth.middleware.bearer_auth import AuthenticatedUser\\nfrom mcp.server.auth.provider import AccessToken\\nfrom mcp.server.sse import SseServerTransport\\nfrom mcp.server.streamable_http_manager import StreamableHTTPSessionManager\\n\\nfrom langflow.api.utils import CurrentActiveMCPUser, raise_error_if_astra_cloud_env\\nfrom langflow.api.v1.mcp_utils import (\\n    authenticated_caller_ctx,\\n    current_user_ctx,\\n    handle_call_tool,\\n    handle_list_resources,\\n    handle_list_tools,\\n    handle_mcp_errors,\\n    handle_read_resource,\\n    raise_if_sse_disabled,\\n)\\n\\n\\ndef _ensure_mcp_root_model_ready(model: type[pydantic.BaseModel], root_type: Any, *, force: bool = False) -> None:\\n    \\\"\\\"\\\"Rebuild an MCP RootModel only when Pydantic left it incomplete.\\n\\n    Pydantic 2.14.0a1 can lose the generic root annotation when MCP is first\\n    imported through Langflow's router stack. Complete models, including those\\n    built by stable Pydantic releases, return without mutation.\\n    \\\"\\\"\\\"\\n    if model.__pydantic_complete__ and not force:\\n        return\\n\\n    rebuild_kwargs: dict[str, Any] = {\\\"_types_namespace\\\": {\\\"RootModelRootType\\\": root_type}}\\n    if force:\\n        rebuild_kwargs[\\\"force\\\"] = True\\n    model.model_rebuild(**rebuild_kwargs)\\n\\n\\ndef _ensure_mcp_paginated_request_defaults() -> bool:\\n    \\\"\\\"\\\"Restore optional params defaults lost from MCP paginated request models.\\n\\n    Pydantic 2.14.0a1 drops the inherited ``params=None`` default when it\\n    specializes MCP's generic ``PaginatedRequest``. The MCP client then omits\\n    params from list requests, while the server's validator incorrectly treats\\n    the field as required and returns JSON-RPC -32602.\\n    \\\"\\\"\\\"\\n    repaired = False\\n    paginated_requests = (\\n        types.ListPromptsRequest,\\n        types.ListResourceTemplatesRequest,\\n        types.ListResourcesRequest,\\n        types.ListTasksRequest,\\n        types.ListToolsRequest,\\n    )\\n    for request_model in paginated_requests:\\n        params_field = request_model.model_fields[\\\"params\\\"]\\n        if not params_field.is_required():\\n            continue\\n        params_field.default = None\\n        request_model.model_rebuild(force=True)\\n        repaired = True\\n    return repaired\\n\\n\\ndef _ensure_mcp_root_models_ready() -> None:\\n    \\\"\\\"\\\"Restore MCP SDK RootModel validators after affected Pydantic imports.\\\"\\\"\\\"\\n    paginated_requests_repaired = _ensure_mcp_paginated_request_defaults()\\n    root_models = (\\n        (\\n            types.JSONRPCMessage,\\n            types.JSONRPCRequest | types.JSONRPCNotification | types.JSONRPCResponse | types.JSONRPCError,\\n        ),\\n        (types.ClientRequest, types.ClientRequestType),\\n        (types.ClientNotification, types.ClientNotificationType),\\n        (types.ClientResult, types.ClientResultType),\\n        (types.ServerRequest, types.ServerRequestType),\\n        (types.ServerNotification, types.ServerNotificationType),\\n        (types.ServerResult, types.ServerResultType),\\n    )\\n    for model, root_type in root_models:\\n        _ensure_mcp_root_model_ready(\\n            model,\\n            root_type,\\n            force=paginated_requests_repaired and model is types.ClientRequest,\\n        )\\n\\n\\n_ensure_mcp_root_models_ready()\\n\\nrouter = APIRouter(prefix=\\\"/mcp\\\", tags=[\\\"mcp\\\"], include_in_schema=False)\\n\\nserver = Server(\\\"langflow-mcp-server\\\")\\n\\n\\n@server.list_prompts()\\nasync def handle_list_prompts():\\n    return []\\n\\n\\n@server.list_resources()\\nasync def handle_global_resources():\\n    \\\"\\\"\\\"Handle listing resources for global MCP server.\\\"\\\"\\\"\\n    return await handle_list_resources()\\n\\n\\n@server.read_resource()\\nasync def handle_global_read_resource(uri: str) -> bytes:\\n    \\\"\\\"\\\"Handle resource read requests for global MCP server.\\\"\\\"\\\"\\n    return await handle_read_resource(uri)\\n\\n\\n@server.list_tools()\\nasync def handle_global_tools():\\n    \\\"\\\"\\\"Handle listing tools for global MCP server.\\\"\\\"\\\"\\n    return await handle_list_tools()\\n\\n\\n@server.call_tool()\\n@handle_mcp_errors\\nasync def handle_global_call_tool(name: str, arguments: dict) -> list[types.TextContent]:\\n    \\\"\\\"\\\"Handle tool execution requests for global MCP server.\\\"\\\"\\\"\\n    return await handle_call_tool(name, arguments, server)\\n\\n\\n# The MCP transports emit the full ASGI response themselves; returning a real\\n# Response would start the stream twice, so this no-op satisfies FastAPI instead.\\nclass ResponseNoOp(Response):\\n    async def __call__(self, scope, receive, send) -> None:  # noqa: ARG002\\n        return\\n\\n\\ndef find_validation_error(exc):\\n    \\\"\\\"\\\"Searches for a pydantic.ValidationError in the exception chain.\\\"\\\"\\\"\\n    while exc:\\n        if isinstance(exc, pydantic.ValidationError):\\n            return exc\\n        exc = getattr(exc, \\\"__cause__\\\", None) or getattr(exc, \\\"__context__\\\", None)\\n    return None\\n\\n\\nsse = SseServerTransport(\\\"/api/v1/mcp/\\\")\\n\\n\\ndef _bind_mcp_transport_user(request: Request, current_user: CurrentActiveMCPUser) -> None:\\n    \\\"\\\"\\\"Expose the authenticated Langflow principal to the MCP transport.\\n\\n    The SSE transport binds each session to ``scope[\\\"user\\\"]`` and requires the\\n    same principal on subsequent message requests. Langflow performs its own\\n    authentication, so adapt the resolved user to the identity type expected by\\n    the transport instead of leaving both requests anonymous at the ASGI layer.\\n    \\\"\\\"\\\"\\n    user_id = str(current_user.id)\\n    request.scope[\\\"user\\\"] = AuthenticatedUser(AccessToken(token=\\\"\\\", client_id=user_id, scopes=[], subject=user_id))\\n\\n\\n@router.head(\\n    \\\"/sse\\\",\\n    response_class=HTMLResponse,\\n    dependencies=[Depends(raise_error_if_astra_cloud_env), Depends(raise_if_sse_disabled)],\\n)\\nasync def im_alive():\\n    return Response()\\n\\n\\n@router.get(\\n    \\\"/sse\\\",\\n    response_class=ResponseNoOp,\\n    dependencies=[Depends(raise_error_if_astra_cloud_env), Depends(raise_if_sse_disabled)],\\n)\\nasync def handle_sse(request: Request, current_user: CurrentActiveMCPUser):\\n    msg = f\\\"Starting SSE connection, server name: {server.name}\\\"\\n    await logger.ainfo(msg)\\n    _bind_mcp_transport_user(request, current_user)\\n    authenticated_caller_ctx.set(current_user.id)\\n    token = current_user_ctx.set(current_user)\\n    try:\\n        async with sse.connect_sse(request.scope, request.receive, request._send) as streams:  # noqa: SLF001\\n            try:\\n                msg = \\\"Starting SSE connection\\\"\\n                await logger.adebug(msg)\\n                msg = f\\\"Stream types: read={type(streams[0])}, write={type(streams[1])}\\\"\\n                await logger.adebug(msg)\\n\\n                notification_options = NotificationOptions(\\n                    prompts_changed=True, resources_changed=True, tools_changed=True\\n                )\\n                init_options = server.create_initialization_options(notification_options)\\n                msg = f\\\"Initialization options: {init_options}\\\"\\n                await logger.adebug(msg)\\n\\n                try:\\n                    await server.run(streams[0], streams[1], init_options)\\n                except Exception as exc:  # noqa: BLE001\\n                    validation_error = find_validation_error(exc)\\n                    if validation_error:\\n                        msg = \\\"Validation error in MCP:\\\" + str(validation_error)\\n                        await logger.adebug(msg)\\n                    else:\\n                        msg = f\\\"Error in MCP: {exc!s}\\\"\\n                        await logger.adebug(msg)\\n                        return\\n            except BrokenResourceError:\\n                # Handle gracefully when client disconnects\\n                await logger.ainfo(\\\"Client disconnected from SSE connection\\\")\\n            except asyncio.CancelledError:\\n                await logger.ainfo(\\\"SSE connection was cancelled\\\")\\n                raise\\n            except Exception as e:\\n                msg = f\\\"Error in MCP: {e!s}\\\"\\n                await logger.aexception(msg)\\n                raise\\n    finally:\\n        current_user_ctx.reset(token)\\n\\n\\n@router.post(\\\"/\\\", dependencies=[Depends(raise_error_if_astra_cloud_env), Depends(raise_if_sse_disabled)])\\nasync def handle_messages(request: Request, current_user: CurrentActiveMCPUser):\\n    _bind_mcp_transport_user(request, current_user)\\n    try:\\n        await sse.handle_post_message(request.scope, request.receive, request._send)  # noqa: SLF001\\n    except (BrokenResourceError, BrokenPipeError) as e:\\n        await logger.ainfo(\\\"MCP Server disconnected\\\")\\n        raise HTTPException(status_code=404, detail=f\\\"MCP Server disconnected, error: {e}\\\") from e\\n    except Exception as e:\\n        await logger.aerror(f\\\"Internal server error: {e}\\\")\\n        raise HTTPException(status_code=500, detail=f\\\"Internal server error: {e}\\\") from e\\n\\n\\nclass StreamableHTTP:\\n    def __init__(self, mcp_server: Server | None = None) -> None:\\n        # Default is this module's flows-as-tools server; the agentic MCP passes its own.\\n        self._server = mcp_server if mcp_server is not None else server\\n        self.session_manager: StreamableHTTPSessionManager | None = None\\n        self._started = False\\n        self._start_stop_lock = asyncio.Lock()\\n        # A dedicated task owns the manager lifecycle so __aenter__ and\\n        # __aexit__ of its run() context happen in the same task.\\n        self._mgr_task: asyncio.Task | None = None\\n        self._mgr_ready: asyncio.Event | None = None\\n        self._mgr_close: asyncio.Event | None = None\\n\\n    async def _start_session_manager(self) -> None:\\n        \\\"\\\"\\\"Create and enter the Streamable HTTP session manager lifecycle.\\\"\\\"\\\"\\n        try:\\n            async with self.session_manager.run():  # type: ignore[union-attr]\\n                self._started = True\\n                self._mgr_ready.set()  # type: ignore[union-attr]\\n                await self._mgr_close.wait()  # type: ignore[union-attr]\\n        except Exception as e:\\n            msg = f\\\"Error in Streamable HTTP session manager: {e}\\\"\\n            raise RuntimeError(msg) from e\\n        finally:\\n            self._mgr_ready.set()  # type: ignore[union-attr] # unblock listeners\\n            self._started = False\\n\\n    async def start(self, *, stateless: bool = True) -> None:\\n        \\\"\\\"\\\"Create and enter the Streamable HTTP session manager lifecycle.\\\"\\\"\\\"\\n        async with self._start_stop_lock:\\n            if self._started:\\n                await logger.adebug(\\\"Streamable HTTP session manager already running; skipping start\\\")\\n                return\\n            try:\\n                self.session_manager = StreamableHTTPSessionManager(self._server, stateless=stateless)\\n                self._mgr_ready = asyncio.Event()\\n                self._mgr_close = asyncio.Event()\\n                self._mgr_task = asyncio.create_task(self._start_session_manager())\\n                await self._mgr_ready.wait()\\n                if not self._started:  # did not start properly\\n                    await self._mgr_task  # await to surface the exception\\n            except Exception as e:\\n                self._cleanup()\\n                await logger.aexception(f\\\"Error starting Streamable HTTP session manager: {e}\\\")\\n                raise\\n\\n    def get_manager(self) -> StreamableHTTPSessionManager:\\n        \\\"\\\"\\\"Fetch the active Streamable HTTP session manager or raise if it is unavailable.\\\"\\\"\\\"\\n        if not self._started or self.session_manager is None:\\n            raise HTTPException(status_code=503, detail=\\\"MCP Streamable HTTP transport is not initialized\\\")\\n        return self.session_manager\\n\\n    async def stop(self) -> None:\\n        \\\"\\\"\\\"Close the Streamable HTTP session manager context.\\\"\\\"\\\"\\n        async with self._start_stop_lock:\\n            if not self._started:\\n                return\\n            try:\\n                self._mgr_close.set()  # type: ignore[union-attr]\\n                await self._mgr_task  # type: ignore[misc]\\n            except Exception as e:\\n                await logger.aexception(f\\\"Error stopping Streamable HTTP session manager: {e}\\\")\\n                raise\\n            finally:\\n                self._cleanup()\\n                await logger.adebug(\\\"Streamable HTTP session manager stopped\\\")\\n\\n    def _cleanup(self) -> None:\\n        \\\"\\\"\\\"Cleanup the Streamable HTTP session manager.\\\"\\\"\\\"\\n        self._mgr_task = None\\n        self._mgr_ready = None\\n        self._mgr_close = None\\n        self.session_manager = None\\n        self._started = False\\n\\n\\n_streamable_http = StreamableHTTP()\\n\\n\\nasync def start_streamable_http_manager(stateless: bool = True) -> None:  # noqa: FBT001, FBT002\\n    await _streamable_http.start(stateless=stateless)\\n\\n\\ndef get_streamable_http_manager() -> StreamableHTTPSessionManager:\\n    return _streamable_http.get_manager()\\n\\n\\nasync def stop_streamable_http_manager() -> None:\\n    await _streamable_http.stop()\\n\\n\\nstreamable_http_route_config = {  # use for all streamable http routes (except for the health check)\\n    \\\"methods\\\": [\\\"GET\\\", \\\"POST\\\", \\\"DELETE\\\"],\\n    \\\"response_class\\\": ResponseNoOp,\\n}\\n\\n\\n@router.head(\\\"/streamable\\\")\\nasync def streamable_health():\\n    return Response()\\n\\n\\n@router.api_route(\\\"/streamable\\\", **streamable_http_route_config)\\n@router.api_route(\\\"/streamable/\\\", **streamable_http_route_config)\\nasync def handle_streamable_http(request: Request, current_user: CurrentActiveMCPUser):\\n    \\\"\\\"\\\"Streamable HTTP endpoint for MCP clients that support the new transport.\\\"\\\"\\\"\\n    return await _dispatch_streamable_http(request, current_user)\\n\\n\\nasync def _dispatch_streamable_http(\\n    request: Request,\\n    current_user: CurrentActiveMCPUser,\\n) -> Response:\\n    \\\"\\\"\\\"Common handler for Streamable HTTP requests with user context propagation.\\\"\\\"\\\"\\n    await logger.adebug(\\n        \\\"Handling %s %s via Streamable HTTP for user %s\\\",\\n        request.method,\\n        request.url.path,\\n        current_user.id,\\n    )\\n\\n    authenticated_caller_ctx.set(current_user.id)\\n    context_token = current_user_ctx.set(current_user)\\n    try:\\n        manager = get_streamable_http_manager()\\n        await manager.handle_request(request.scope, request.receive, request._send)  # noqa: SLF001\\n    except HTTPException:\\n        raise\\n    except Exception as exc:\\n        await logger.aexception(f\\\"Error handling Streamable HTTP request: {exc!s}\\\")\\n        raise HTTPException(status_code=500, detail=\\\"Internal server error in Streamable HTTP transport\\\") from exc\\n    finally:\\n        current_user_ctx.reset(context_token)\\n\\n    return ResponseNoOp()\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/api/v1/mcp_projects.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"57931cd2a5989e546f80cf2abcde2405e65fbd6eb220e9491114efd267fd058d\",\"content\":\"import asyncio\\nimport json\\nimport os\\nimport platform\\nfrom asyncio.subprocess import create_subprocess_exec\\nfrom collections.abc import Awaitable, Callable, Sequence\\nfrom contextvars import ContextVar\\nfrom datetime import datetime, timezone\\nfrom ipaddress import ip_address\\nfrom pathlib import Path\\nfrom subprocess import CalledProcessError\\nfrom typing import Annotated, Any, cast\\nfrom uuid import UUID\\n\\nimport anyio\\nfrom anyio import BrokenResourceError\\nfrom anyio.abc import TaskGroup, TaskStatus\\nfrom fastapi import APIRouter, Depends, HTTPException, Request, Response, status\\nfrom fastapi.responses import HTMLResponse, JSONResponse\\nfrom lfx.base.mcp.constants import MAX_MCP_SERVER_NAME_LENGTH\\nfrom lfx.base.mcp.util import sanitize_mcp_name\\nfrom lfx.base.mcp.uvx import mcp_sdk_constraint_args\\nfrom lfx.log import logger\\nfrom lfx.services.deps import get_settings_service, session_scope\\nfrom lfx.services.mcp_composer.service import (\\n    COMPOSER_BACKEND_AUTH_HEADER,\\n    MCPComposerError,\\n    MCPComposerService,\\n)\\nfrom lfx.services.schema import ServiceType\\nfrom mcp import types\\nfrom mcp.server import NotificationOptions, Server\\nfrom mcp.server.sse import SseServerTransport\\nfrom mcp.server.streamable_http_manager import StreamableHTTPSessionManager\\nfrom sqlalchemy.orm import selectinload\\nfrom sqlmodel import select\\n\\nfrom langflow.api.utils import (\\n    CurrentActiveMCPUser,\\n    extract_global_variables_from_headers,\\n    raise_error_if_astra_cloud_env,\\n)\\nfrom langflow.api.utils.mcp import (\\n    auto_configure_starter_projects_mcp,\\n    get_composer_streamable_http_url,\\n    get_project_local_sse_url,\\n    get_project_local_streamable_http_url,\\n    get_project_sse_url,\\n    get_project_streamable_http_url,\\n    get_url_by_os,\\n)\\nfrom langflow.api.v1.auth_helpers import handle_auth_settings_update\\nfrom langflow.api.v1.mcp import ResponseNoOp\\nfrom langflow.api.v1.mcp_utils import (\\n    authenticated_caller_ctx,\\n    current_request_headers_ctx,\\n    current_request_variables_ctx,\\n    current_user_ctx,\\n    handle_call_tool,\\n    handle_list_resources,\\n    handle_list_tools_result,\\n    handle_mcp_errors,\\n    handle_read_resource,\\n    raise_if_sse_disabled,\\n)\\nfrom langflow.api.v1.schemas import (\\n    AuthSettings,\\n    ComposerUrlResponse,\\n    MCPInstallRequest,\\n    MCPProjectResponse,\\n    MCPProjectUpdateRequest,\\n    MCPSettings,\\n)\\nfrom langflow.services.auth.constants import AUTO_LOGIN_ERROR, AUTO_LOGIN_WARNING\\nfrom langflow.services.auth.context import (\\n    AUTH_METHOD_AUTO_LOGIN,\\n    AuthCredentialContext,\\n    clear_current_auth_context,\\n    set_current_auth_context,\\n)\\nfrom langflow.services.auth.mcp_encryption import decrypt_auth_settings, encrypt_auth_settings\\nfrom langflow.services.authorization import ProjectAction, ensure_project_permission\\nfrom langflow.services.authorization.access_ceiling import clear_current_external_access_context\\nfrom langflow.services.database.models import Flow, Folder\\nfrom langflow.services.database.models.api_key.crud import authenticate_api_key, create_api_key\\nfrom langflow.services.database.models.api_key.model import ApiKeyCreate\\nfrom langflow.services.database.models.user.crud import get_user_by_username\\nfrom langflow.services.database.models.user.model import User\\nfrom langflow.services.deps import get_service\\nfrom langflow.services.rate_limit.service import get_last_forwarded_for_hop\\n\\n# Constants\\nALL_INTERFACES_HOST = \\\"0.0.0.0\\\"  # noqa: S104\\n\\nrouter = APIRouter(prefix=\\\"/mcp/project\\\", tags=[\\\"mcp_projects\\\"])\\n\\n\\nasync def verify_project_auth(\\n    project_id: UUID,\\n    query_param: str | None,\\n    header_param: str | None,\\n    composer_backend_token: str | None = None,\\n) -> User:\\n    \\\"\\\"\\\"MCP-specific user authentication that allows fallback to username lookup when not using API key auth.\\n\\n    This function provides authentication for MCP endpoints when using MCP Composer and no API key is provided,\\n    or checks if the API key is valid.\\n    \\\"\\\"\\\"\\n    # Mirror the service.py auth entrypoints: reset request-local credential metadata at entry so a\\n    # later branch (e.g. the composer-token fast path) never inherits stale context from a prior call.\\n    clear_current_auth_context()\\n    authenticated_caller_ctx.set(None)\\n    # Defensive invariant: drop any stale external access ceiling so it can't carry into MCP project auth.\\n    clear_current_external_access_context()\\n\\n    settings_service = get_settings_service()\\n\\n    # Resolve project authentication policy before API-key authentication opens\\n    # its owned transaction. Keep only scalar values after this scope exits.\\n    async with session_scope() as db:\\n        project = (await db.exec(select(Folder).where(Folder.id == project_id))).first()\\n        if not project:\\n            raise HTTPException(status_code=404, detail=\\\"Project not found\\\")\\n        project_user_id = project.user_id\\n        auth_settings = AuthSettings(**project.auth_settings) if project.auth_settings else None\\n\\n    project_auth_type = auth_settings.auth_type if auth_settings else None\\n    if project_auth_type == \\\"oauth\\\" and composer_backend_token:\\n        mcp_composer_service: MCPComposerService = cast(\\n            MCPComposerService, get_service(ServiceType.MCP_COMPOSER_SERVICE)\\n        )\\n        if mcp_composer_service.validate_backend_auth_token(str(project_id), composer_backend_token):\\n            if project_user_id:\\n                async with session_scope() as db:\\n                    project_user = await db.get(User, project_user_id)\\n                    if project_user:\\n                        return project_user\\n            raise HTTPException(status_code=404, detail=\\\"Project owner not found\\\")\\n\\n    # Public MCP projects execute as their owning principal, never as the\\n    # instance-wide superuser used by the legacy single-user fallback.\\n    if project_auth_type == \\\"none\\\":\\n        if project_user_id:\\n            async with session_scope() as db:\\n                project_user = await db.get(User, project_user_id)\\n                if project_user:\\n                    return project_user\\n        raise HTTPException(status_code=404, detail=\\\"Project owner not found\\\")\\n\\n    # OAuth projects must present a valid API key at the Langflow transport endpoint: network-level\\n    # trust (loopback / same-host proxy) is unsafe because it cannot distinguish the local MCP\\n    # Composer subprocess from another loopback peer behind a reverse proxy or sidecar. The\\n    # composer-to-Langflow hop should be authenticated explicitly once mcp-composer can forward\\n    # a project-scoped backend credential; until then, direct backend access requires a key.\\n    requires_api_key = (not auth_settings and not settings_service.auth_settings.AUTO_LOGIN) or (\\n        project_auth_type in {\\\"apikey\\\", \\\"oauth\\\"}\\n    )\\n\\n    # A presented API key is always honoured, even when policy would not have demanded one.\\n    # Under MCP Composer with a default project and AUTO_LOGIN=true, ``requires_api_key`` is\\n    # False; without this, a key minted by ``/install`` would be ignored and the caller would\\n    # fall through to the (now-rejecting) superuser fallback. Callers presenting NO credential\\n    # still reach ``_superuser_fallback`` and get 403 AUTO_LOGIN_ERROR.\\n    api_key = query_param or header_param\\n    if requires_api_key or api_key:\\n        if not api_key:\\n            if project_auth_type == \\\"oauth\\\":\\n                detail = (\\n                    \\\"This project is configured for OAuth authentication, but the MCP transport endpoint \\\"\\n                    \\\"currently requires a valid x-api-key header or query parameter for backend access. \\\"\\n                    \\\"Credential forwarding from MCP Composer is not yet available; use an API key in the \\\"\\n                    \\\"meantime.\\\"\\n                )\\n            else:\\n                detail = \\\"API key required for this project. Provide x-api-key header or query parameter.\\\"\\n            raise HTTPException(\\n                status_code=401,\\n                detail=detail,\\n            )\\n\\n        # Validate the API key\\n        api_key_result = await authenticate_api_key(api_key)\\n        if not api_key_result:\\n            raise HTTPException(status_code=401, detail=\\\"Invalid API key\\\")\\n        set_current_auth_context(AuthCredentialContext.from_api_key_result(api_key_result))\\n        user = api_key_result.user\\n\\n        # Verify user has access to the project\\n        if project_user_id != user.id:\\n            raise HTTPException(status_code=404, detail=\\\"Project not found\\\")\\n\\n        authenticated_caller_ctx.set(user.id)\\n        return user\\n\\n    return await _superuser_fallback(settings_service)\\n\\n\\nasync def _superuser_fallback(settings_service) -> User:\\n    \\\"\\\"\\\"Resolve the configured superuser for unauthenticated MCP paths that allow fallback.\\\"\\\"\\\"\\n    # AUTO_LOGIN parity with the non-MCP entrypoints (``_api_key_security_impl``,\\n    # ``ws_api_key_security``, ``authenticate_with_credentials``): AUTO_LOGIN alone is not\\n    # a credential. Only an explicit ``skip_auth_auto_login`` opt-in may resolve a caller\\n    # that presented no API key and no token to the instance superuser.\\n    if not settings_service.auth_settings.skip_auth_auto_login:\\n        raise HTTPException(\\n            status_code=status.HTTP_403_FORBIDDEN,\\n            detail=AUTO_LOGIN_ERROR,\\n        )\\n    if not settings_service.auth_settings.SUPERUSER:\\n        raise HTTPException(\\n            status_code=status.HTTP_400_BAD_REQUEST,\\n            detail=\\\"Missing superuser username in auth settings\\\",\\n        )\\n    async with session_scope() as db:\\n        result = await get_user_by_username(db, settings_service.auth_settings.SUPERUSER)\\n    if result:\\n        logger.warning(AUTO_LOGIN_WARNING)\\n        set_current_auth_context(AuthCredentialContext(method=AUTH_METHOD_AUTO_LOGIN))\\n        # Auto-login means the deployment has no authentication boundary at all, so the\\n        # caller is this principal by the instance's own definition. A project that opted\\n        # into auth_type=\\\"none\\\" is a different case and returns above without a caller.\\n        authenticated_caller_ctx.set(result.id)\\n        return result\\n    raise HTTPException(\\n        status_code=status.HTTP_403_FORBIDDEN,\\n        detail=\\\"Invalid user\\\",\\n    )\\n\\n\\n# Smart authentication dependency that chooses method based on project settings\\nasync def verify_project_auth_conditional(\\n    project_id: UUID,\\n    request: Request,\\n) -> User:\\n    \\\"\\\"\\\"Choose authentication method based on project settings.\\n\\n    - MCP Composer enabled + API key auth: Only allow API keys\\n    - All other cases: Use standard MCP auth (JWT + API keys)\\n    \\\"\\\"\\\"\\n    # Extract token\\n    token: str | None = None\\n    auth_header = request.headers.get(\\\"authorization\\\")\\n    if auth_header and auth_header.startswith(\\\"Bearer \\\"):\\n        token = auth_header[7:]\\n\\n    # Extract API keys\\n    api_key_query_value = request.query_params.get(\\\"x-api-key\\\")\\n    api_key_header_value = request.headers.get(\\\"x-api-key\\\")\\n    composer_backend_token = request.headers.get(COMPOSER_BACKEND_AUTH_HEADER)\\n\\n    # The composer path performs its own short project-policy read before auth.\\n    if get_settings_service().settings.mcp_composer_enabled:\\n        return await verify_project_auth(\\n            project_id,\\n            api_key_query_value,\\n            api_key_header_value,\\n            composer_backend_token,\\n        )\\n\\n    # Preserve the existing not-found-before-auth behavior, but close this read\\n    # scope before API-key authentication opens its owned transaction.\\n    async with session_scope() as session:\\n        project = (await session.exec(select(Folder).where(Folder.id == project_id))).first()\\n        if not project:\\n            raise HTTPException(status_code=404, detail=\\\"Project not found\\\")\\n        project_user_id = project.user_id\\n\\n    # For all other cases, use standard MCP authentication (allows JWT + API keys).\\n    # This session has not executed a query before API-key authentication.\\n    from langflow.services.auth.utils import get_current_user_mcp\\n\\n    async with session_scope() as session:\\n        user = await get_current_user_mcp(\\n            token=token or \\\"\\\", query_param=api_key_query_value, header_param=api_key_header_value, db=session\\n        )\\n\\n    if project_user_id != user.id:\\n        raise HTTPException(status_code=404, detail=\\\"Project not found\\\")\\n\\n    authenticated_caller_ctx.set(user.id)\\n    return user\\n\\n\\n# Create project-specific context variable\\ncurrent_project_ctx: ContextVar[UUID | None] = ContextVar(\\\"current_project_ctx\\\", default=None)\\n\\n# Mapping of project-specific SSE transports\\nproject_sse_transports: dict[str, SseServerTransport] = {}\\n\\n\\ndef get_project_sse(project_id: UUID | None) -> SseServerTransport:\\n    \\\"\\\"\\\"Get or create an SSE transport for a specific project.\\\"\\\"\\\"\\n    if not project_id:\\n        raise HTTPException(status_code=400, detail=\\\"Project ID is required to start MCP server\\\")\\n\\n    project_id_str = str(project_id)\\n    if project_id_str not in project_sse_transports:\\n        project_sse_transports[project_id_str] = SseServerTransport(f\\\"/api/v1/mcp/project/{project_id_str}/\\\")\\n    return project_sse_transports[project_id_str]\\n\\n\\nasync def _build_project_tools_response(\\n    project_id: UUID,\\n    current_user: CurrentActiveMCPUser,\\n    *,\\n    mcp_enabled: bool,\\n) -> MCPProjectResponse:\\n    \\\"\\\"\\\"Return tool metadata for a project.\\\"\\\"\\\"\\n    tools: list[MCPSettings] = []\\n    try:\\n        async with session_scope() as session:\\n            # Fetch the project first to verify it exists and belongs to the current user\\n            project = (\\n                await session.exec(\\n                    select(Folder)\\n                    .options(selectinload(Folder.flows))\\n                    .where(Folder.id == project_id, Folder.user_id == current_user.id)\\n                )\\n            ).first()\\n\\n            if not project:\\n                raise HTTPException(status_code=404, detail=\\\"Project not found\\\")\\n\\n            # Query flows in the project\\n            flows_query = select(Flow).where(Flow.folder_id == project_id, Flow.is_component == False)  # noqa: E712\\n\\n            # Optionally filter for MCP-enabled flows only\\n            if mcp_enabled:\\n                flows_query = flows_query.where(Flow.mcp_enabled == True)  # noqa: E712\\n\\n            flows = (await session.exec(flows_query)).all()\\n\\n            for flow in flows:\\n                if flow.user_id is None:\\n                    continue\\n\\n                # Format the flow name according to MCP conventions (snake_case)\\n                flow_name = sanitize_mcp_name(flow.name)\\n\\n                # Use action_name and action_description if available, otherwise use defaults\\n                name = sanitize_mcp_name(flow.action_name) if flow.action_name else flow_name\\n                description = flow.action_description or (\\n                    flow.description if flow.description else f\\\"Tool generated from flow: {flow_name}\\\"\\n                )\\n                try:\\n                    tool = MCPSettings(\\n                        id=flow.id,\\n                        action_name=name,\\n                        action_description=description,\\n                        mcp_enabled=flow.mcp_enabled,\\n                        # inputSchema=json_schema_from_flow(flow),\\n                        name=flow.name,\\n                        description=flow.description,\\n                    )\\n                    tools.append(tool)\\n                except Exception as e:  # noqa: BLE001\\n                    msg = f\\\"Error in listing project tools: {e!s} from flow: {name}\\\"\\n                    await logger.awarning(msg)\\n                    continue\\n\\n            # Get project-level auth settings but mask sensitive fields for security\\n            auth_settings = None\\n            if project.auth_settings:\\n                # Decrypt to get the settings structure\\n                decrypted_settings = decrypt_auth_settings(project.auth_settings)\\n                if decrypted_settings:\\n                    # Mask sensitive fields before sending to frontend\\n                    masked_settings = decrypted_settings.copy()\\n                    if masked_settings.get(\\\"oauth_client_secret\\\"):\\n                        masked_settings[\\\"oauth_client_secret\\\"] = \\\"*******\\\"  # noqa: S105\\n                    if masked_settings.get(\\\"api_key\\\"):\\n                        masked_settings[\\\"api_key\\\"] = \\\"*******\\\"\\n                    auth_settings = AuthSettings(**masked_settings)\\n\\n    except Exception as e:\\n        msg = f\\\"Error listing project tools: {e!s}\\\"\\n        await logger.aexception(msg)\\n        raise HTTPException(status_code=500, detail=str(e)) from e\\n\\n    return MCPProjectResponse(tools=tools, auth_settings=auth_settings)\\n\\n\\n@router.get(\\\"/{project_id}\\\")\\nasync def list_project_tools(\\n    project_id: UUID,\\n    current_user: CurrentActiveMCPUser,\\n    *,\\n    mcp_enabled: bool = True,\\n) -> Response:\\n    \\\"\\\"\\\"List project MCP tools.\\\"\\\"\\\"\\n    metadata = await _build_project_tools_response(project_id, current_user, mcp_enabled=mcp_enabled)\\n    return JSONResponse(content=metadata.model_dump(mode=\\\"json\\\"))\\n\\n\\n########################################################\\n# legacy SSE transport routes\\n########################################################\\n\\n\\n@router.head(\\n    \\\"/{project_id}/sse\\\",\\n    response_class=HTMLResponse,\\n    dependencies=[Depends(raise_error_if_astra_cloud_env), Depends(raise_if_sse_disabled)],\\n    include_in_schema=False,\\n)\\nasync def im_alive(project_id: str):  # noqa: ARG001\\n    return Response()\\n\\n\\n@router.get(\\n    \\\"/{project_id}/sse\\\",\\n    response_class=HTMLResponse,\\n    dependencies=[Depends(raise_error_if_astra_cloud_env), Depends(raise_if_sse_disabled)],\\n    include_in_schema=False,\\n)\\nasync def handle_project_sse(\\n    project_id: UUID,\\n    request: Request,\\n    current_user: Annotated[User, Depends(verify_project_auth_conditional)],\\n):\\n    \\\"\\\"\\\"Handle SSE connections for a specific project.\\\"\\\"\\\"\\n    async with session_scope() as session:\\n        project = (\\n            await session.exec(select(Folder).where(Folder.id == project_id, Folder.user_id == current_user.id))\\n        ).first()\\n\\n    if not project:\\n        raise HTTPException(status_code=404, detail=\\\"Project not found\\\")\\n\\n    sse = get_project_sse(project_id)\\n    project_server = get_project_mcp_server(project_id)\\n    await logger.adebug(\\\"Project MCP server name: %s\\\", project_server.server.name)\\n\\n    user_token = current_user_ctx.set(current_user)\\n    project_token = current_project_ctx.set(project_id)\\n    variables = extract_global_variables_from_headers(request.headers, include_auth_headers=True)\\n    req_vars_token = current_request_variables_ctx.set(variables or None)\\n\\n    try:\\n        async with sse.connect_sse(request.scope, request.receive, request._send) as streams:  # noqa: SLF001\\n            try:\\n                await logger.adebug(\\\"Starting SSE connection for project %s\\\", project_id)\\n\\n                notification_options = NotificationOptions(\\n                    prompts_changed=True, resources_changed=True, tools_changed=True\\n                )\\n                init_options = project_server.server.create_initialization_options(notification_options)\\n\\n                try:\\n                    await project_server.server.run(streams[0], streams[1], init_options)\\n                except Exception:  # noqa: BLE001\\n                    await logger.aexception(\\\"Error in project MCP\\\")\\n            except BrokenResourceError:\\n                await logger.ainfo(\\\"Client disconnected from project SSE connection\\\")\\n            except asyncio.CancelledError:\\n                await logger.ainfo(\\\"Project SSE connection was cancelled\\\")\\n                raise\\n            except Exception:\\n                await logger.aexception(\\\"Error in project MCP\\\")\\n                raise\\n    finally:\\n        current_user_ctx.reset(user_token)\\n        current_project_ctx.reset(project_token)\\n        current_request_variables_ctx.reset(req_vars_token)\\n\\n    return ResponseNoOp(status_code=200)\\n\\n\\nasync def _handle_project_sse_messages(\\n    project_id: UUID,\\n    request: Request,\\n    current_user: User,\\n):\\n    \\\"\\\"\\\"Handle POST messages for a project-specific MCP server using SSE transport.\\\"\\\"\\\"\\n    user_token = current_user_ctx.set(current_user)\\n    project_token = current_project_ctx.set(project_id)\\n    variables = extract_global_variables_from_headers(request.headers, include_auth_headers=True)\\n    req_vars_token = current_request_variables_ctx.set(variables or None)\\n\\n    try:\\n        sse = get_project_sse(project_id)\\n        await sse.handle_post_message(request.scope, request.receive, request._send)  # noqa: SLF001\\n    except BrokenResourceError as e:\\n        await logger.ainfo(\\\"Project MCP Server disconnected for project %s\\\", project_id)\\n        raise HTTPException(status_code=404, detail=f\\\"Project MCP Server disconnected, error: {e}\\\") from e\\n    finally:\\n        current_user_ctx.reset(user_token)\\n        current_project_ctx.reset(project_token)\\n        current_request_variables_ctx.reset(req_vars_token)\\n\\n\\n@router.post(\\n    \\\"/{project_id}\\\",\\n    dependencies=[Depends(raise_error_if_astra_cloud_env), Depends(raise_if_sse_disabled)],\\n    include_in_schema=False,\\n)\\n@router.post(\\n    \\\"/{project_id}/\\\",\\n    dependencies=[Depends(raise_error_if_astra_cloud_env), Depends(raise_if_sse_disabled)],\\n    include_in_schema=False,\\n)\\nasync def handle_project_messages(\\n    project_id: UUID,\\n    request: Request,\\n    current_user: Annotated[User, Depends(verify_project_auth_conditional)],\\n):\\n    \\\"\\\"\\\"Handle POST messages for a project-specific MCP server.\\\"\\\"\\\"\\n    return await _handle_project_sse_messages(project_id, request, current_user)\\n\\n\\n########################################################\\n# Streamable HTTP transport routes\\n########################################################\\n\\n\\n@router.head(\\\"/{project_id}/streamable\\\", include_in_schema=False)\\nasync def streamable_health(project_id: UUID):  # noqa: ARG001\\n    return Response()\\n\\n\\nasync def _dispatch_project_streamable_http(\\n    project_id: UUID,\\n    request: Request,\\n    current_user: User,\\n) -> Response:\\n    \\\"\\\"\\\"Common handler for project-specific Streamable HTTP requests.\\\"\\\"\\\"\\n    # Lazily initialize the project's Streamable HTTP manager\\n    # to pick up new projects as they are created.\\n    project_server = get_project_mcp_server(project_id)\\n    await project_server.ensure_session_manager_running()\\n\\n    user_token = current_user_ctx.set(current_user)\\n    project_token = current_project_ctx.set(project_id)\\n    variables = extract_global_variables_from_headers(request.headers, include_auth_headers=True)\\n    request_vars_token = current_request_variables_ctx.set(variables or None)\\n    # Carry the raw request headers into the deep tool dispatch so an MCP-triggered run\\n    # scopes to the serving end-user identity (resolve_serving_scope) like /run does.\\n    request_headers_token = current_request_headers_ctx.set(request.headers)\\n\\n    try:\\n        await project_server.session_manager.handle_request(request.scope, request.receive, request._send)  # noqa: SLF001\\n    except HTTPException:\\n        raise\\n    except Exception as exc:\\n        await logger.aexception(f\\\"Error handling Streamable HTTP request for project {project_id}: {exc!s}\\\")\\n        raise HTTPException(status_code=500, detail=\\\"Internal server error in project MCP transport\\\") from exc\\n    finally:\\n        current_request_headers_ctx.reset(request_headers_token)\\n        current_request_variables_ctx.reset(request_vars_token)\\n        current_project_ctx.reset(project_token)\\n        current_user_ctx.reset(user_token)\\n\\n    return ResponseNoOp(status_code=200)\\n\\n\\nstreamable_http_route_config = {\\n    \\\"methods\\\": [\\\"GET\\\", \\\"POST\\\", \\\"DELETE\\\"],\\n    \\\"response_class\\\": ResponseNoOp,\\n    \\\"include_in_schema\\\": False,\\n}\\n\\n\\n@router.api_route(\\\"/{project_id}/streamable\\\", **streamable_http_route_config)\\n@router.api_route(\\\"/{project_id}/streamable/\\\", **streamable_http_route_config)\\nasync def handle_project_streamable_http(\\n    project_id: UUID,\\n    request: Request,\\n    current_user: Annotated[User, Depends(verify_project_auth_conditional)],\\n):\\n    \\\"\\\"\\\"Handle Streamable HTTP connections for a specific project.\\\"\\\"\\\"\\n    return await _dispatch_project_streamable_http(project_id, request, current_user)\\n\\n\\n@router.patch(\\\"/{project_id}\\\", status_code=200)\\nasync def update_project_mcp_settings(\\n    project_id: UUID,\\n    request: MCPProjectUpdateRequest,\\n    current_user: CurrentActiveMCPUser,\\n):\\n    \\\"\\\"\\\"Update the MCP settings of all flows in a project and project-level auth settings.\\n\\n    On MCP Composer failure, this endpoint should return with a 200 status code and an error message in\\n    the body of the response to display to the user.\\n    \\\"\\\"\\\"\\n    try:\\n        async with session_scope() as session:\\n            # Fetch the project first to verify it exists and belongs to the current user\\n            project = (\\n                await session.exec(\\n                    select(Folder)\\n                    .options(selectinload(Folder.flows))\\n                    .where(Folder.id == project_id, Folder.user_id == current_user.id)\\n                )\\n            ).first()\\n\\n            if not project:\\n                raise HTTPException(status_code=404, detail=\\\"Project not found\\\")\\n\\n            # Mutating flow MCP exposure + project MCP auth settings is a project\\n            # WRITE: enforce so the external access ceiling (e.g. a \\\"viewer\\\")\\n            # cannot change MCP settings. The owner with no ceiling fast-paths via\\n            # owner-override; behavior is unchanged when the feature is off.\\n            await ensure_project_permission(\\n                current_user,\\n                ProjectAction.WRITE,\\n                project_id=project_id,\\n                project_user_id=project.user_id,\\n                workspace_id=project.workspace_id,\\n            )\\n\\n            # Track if MCP Composer needs to be started or stopped\\n            should_handle_mcp_composer = False\\n            should_start_composer = False\\n            should_stop_composer = False\\n            new_auth_type: str | None = None\\n            auth_settings_updated = False\\n\\n            # Store original auth settings in case we need to rollback\\n            original_auth_settings = project.auth_settings\\n\\n            # Update project-level auth settings with encryption\\n            if \\\"auth_settings\\\" in request.model_fields_set and request.auth_settings is not None:\\n                auth_result = handle_auth_settings_update(\\n                    existing_project=project,\\n                    new_auth_settings=request.auth_settings,\\n                )\\n\\n                should_handle_mcp_composer = auth_result[\\\"should_handle_composer\\\"]\\n                should_start_composer = auth_result[\\\"should_start_composer\\\"]\\n                should_stop_composer = auth_result[\\\"should_stop_composer\\\"]\\n                new_auth_type = auth_result[\\\"new_auth_type\\\"]\\n                auth_settings_updated = True\\n\\n            # Query flows in the project\\n            flows = (await session.exec(select(Flow).where(Flow.folder_id == project_id))).all()\\n            flows_to_update = {x.id: x for x in request.settings}\\n\\n            updated_flows = []\\n            for flow in flows:\\n                if flow.user_id is None or flow.user_id != current_user.id:\\n                    continue\\n\\n                if flow.id in flows_to_update:\\n                    settings_to_update = flows_to_update[flow.id]\\n                    flow.mcp_enabled = settings_to_update.mcp_enabled\\n                    flow.action_name = settings_to_update.action_name\\n                    flow.action_description = settings_to_update.action_description\\n                    flow.updated_at = datetime.now(timezone.utc)\\n                    session.add(flow)\\n                    updated_flows.append(flow)\\n\\n            await session.flush()\\n\\n            response: dict[str, Any] = {\\n                \\\"message\\\": f\\\"Updated MCP settings for {len(updated_flows)} flows and project auth settings\\\"\\n            }\\n\\n            # Handle MCP Composer start/stop before committing auth settings\\n            if should_handle_mcp_composer:\\n                # Get MCP Composer service once for all branches\\n                mcp_composer_service: MCPComposerService = cast(\\n                    MCPComposerService, get_service(ServiceType.MCP_COMPOSER_SERVICE)\\n                )\\n\\n                if should_start_composer:\\n                    await logger.adebug(\\n                        f\\\"Auth settings changed to OAuth for project {project.name} ({project_id}), \\\"\\n                        \\\"starting MCP Composer\\\"\\n                    )\\n\\n                    if should_use_mcp_composer(project):\\n                        try:\\n                            auth_config = await _get_mcp_composer_auth_config(project)\\n                            await get_or_start_mcp_composer(auth_config, project.name, project_id)\\n                            composer_streamable_http_url = await get_composer_streamable_http_url(project)\\n                            composer_sse_url = await get_composer_sse_url(project)\\n                            # Clear any previous error on success\\n                            mcp_composer_service.clear_last_error(str(project_id))\\n                            response[\\\"result\\\"] = {\\n                                \\\"project_id\\\": str(project_id),\\n                                \\\"streamable_http_url\\\": composer_streamable_http_url,\\n                                \\\"legacy_sse_url\\\": composer_sse_url,\\n                                \\\"sse_url\\\": composer_sse_url,\\n                                \\\"uses_composer\\\": True,\\n                            }\\n                        except MCPComposerError as e:\\n                            # Don't rollback auth settings - persist them so UI can show the error\\n                            await logger.awarning(f\\\"MCP Composer failed to start for project {project_id}: {e.message}\\\")\\n                            # Store the error message so it can be retrieved via composer-url endpoint\\n                            mcp_composer_service.set_last_error(str(project_id), e.message)\\n                            response[\\\"result\\\"] = {\\n                                \\\"project_id\\\": str(project_id),\\n                                \\\"uses_composer\\\": True,\\n                                \\\"error_message\\\": e.message,\\n                            }\\n                        except Exception as e:\\n                            # Rollback auth settings on unexpected errors\\n                            await logger.aerror(\\n                                f\\\"Unexpected error starting MCP Composer for project {project_id}, \\\"\\n                                f\\\"rolling back auth settings: {e}\\\"\\n                            )\\n                            project.auth_settings = original_auth_settings\\n                            raise HTTPException(status_code=500, detail=str(e)) from e\\n                    else:\\n                        # OAuth is set but MCP Composer is disabled - save settings but return error\\n                        # Don't rollback - keep the auth settings so they can be used when composer is enabled\\n                        await logger.aerror(\\n                            f\\\"PATCH: OAuth set but MCP Composer is disabled in settings for project {project_id}\\\"\\n                        )\\n                        response[\\\"result\\\"] = {\\n                            \\\"project_id\\\": str(project_id),\\n                            \\\"uses_composer\\\": False,\\n                            \\\"error_message\\\": \\\"OAuth authentication is set but MCP Composer is disabled in settings\\\",\\n                        }\\n                elif should_stop_composer:\\n                    await logger.adebug(\\n                        f\\\"Auth settings changed from OAuth for project {project.name} ({project_id}), \\\"\\n                        \\\"stopping MCP Composer\\\"\\n                    )\\n                    await mcp_composer_service.stop_project_composer(str(project_id))\\n                    # Clear any error when user explicitly disables OAuth\\n                    mcp_composer_service.clear_last_error(str(project_id))\\n\\n                    # Provide direct connection URLs since we're no longer using composer\\n                    streamable_http_url = await get_project_streamable_http_url(project_id)\\n                    legacy_sse_url = await get_project_sse_url(project_id)\\n                    if not streamable_http_url:\\n                        raise HTTPException(status_code=500, detail=\\\"Failed to get direct Streamable HTTP URL\\\")\\n\\n                    response[\\\"result\\\"] = {\\n                        \\\"project_id\\\": str(project_id),\\n                        \\\"streamable_http_url\\\": streamable_http_url,\\n                        \\\"legacy_sse_url\\\": legacy_sse_url,\\n                        \\\"sse_url\\\": legacy_sse_url,\\n                        \\\"uses_composer\\\": False,\\n                    }\\n\\n            # Sync MCP server config for apikey/none auth; OAuth is handled by MCP Composer above.\\n            if auth_settings_updated and new_auth_type in {\\\"apikey\\\", \\\"none\\\"}:\\n                from langflow.api.v1.projects_mcp_helpers import reconcile_mcp_server_for_auth_update\\n\\n                try:\\n                    await reconcile_mcp_server_for_auth_update(\\n                        project,\\n                        new_auth_type,\\n                        current_user,\\n                        session,\\n                    )\\n                except HTTPException:\\n                    raise\\n                except Exception as e:  # noqa: BLE001\\n                    await logger.awarning(\\n                        \\\"Failed to reconcile MCP server config for project %s after auth update: %s\\\",\\n                        project_id,\\n                        e,\\n                    )\\n\\n            # Only commit if composer started successfully (or wasn't needed)\\n            session.add(project)\\n            await session.commit()\\n\\n            return response\\n\\n    except HTTPException:\\n        raise\\n    except Exception as e:\\n        msg = f\\\"Error updating project MCP settings: {e!s}\\\"\\n        await logger.aexception(msg)\\n        raise HTTPException(status_code=500, detail=str(e)) from e\\n\\n\\ndef is_local_ip(ip_str: str) -> bool:\\n    \\\"\\\"\\\"Check if an IP address is a loopback address (same machine).\\n\\n    Args:\\n        ip_str: String representation of an IP address\\n\\n    Returns:\\n        bool: True if the IP is a loopback address, False otherwise\\n    \\\"\\\"\\\"\\n    # Check if it's exactly \\\"localhost\\\"\\n    if ip_str == \\\"localhost\\\":\\n        return True\\n\\n    # Check if it's exactly \\\"0.0.0.0\\\" (which binds to all interfaces)\\n    if ip_str == ALL_INTERFACES_HOST:\\n        return True\\n\\n    try:\\n        # Convert string to IP address object\\n        ip = ip_address(ip_str)\\n\\n        # Check if it's a loopback address (127.0.0.0/8 for IPv4, ::1 for IPv6)\\n        return bool(ip.is_loopback)\\n    except ValueError:\\n        # If the IP address is invalid, default to False\\n        return False\\n\\n\\ndef get_client_ip(request: Request) -> str:\\n    \\\"\\\"\\\"Resolve the client IP for the local-only install locality check.\\n\\n    ``X-Forwarded-For`` is client-controlled and must NOT be trusted by default:\\n    trusting it lets a remote caller spoof a loopback address and defeat the\\n    local-only restriction on :func:`install_mcp_config` (which writes MCP client\\n    config to the host filesystem). By default we use the real TCP peer\\n    (``request.client.host``), so a spoofed header has no effect.\\n\\n    Only when the operator has explicitly opted into a trusted proxy\\n    (``rate_limit_trust_proxy``) do we consult ``X-Forwarded-For``, and then we\\n    take the rightmost entry \u2014 the last hop added by the trusted proxy, which a\\n    client cannot forge \u2014 mirroring ``langflow.services.rate_limit.service.get_client_ip``.\\n    Every occurrence of the header is joined first, so a proxy that appends its\\n    own line rather than extending the client's cannot leave the attacker's line\\n    as the one we read.\\n\\n    Args:\\n        request: FastAPI Request object\\n\\n    Returns:\\n        str: The client's IP address\\n    \\\"\\\"\\\"\\n    # Only consult X-Forwarded-For when an operator has explicitly declared a\\n    # trusted proxy; otherwise the header is attacker-controlled.\\n    if get_settings_service().settings.rate_limit_trust_proxy:\\n        last_hop = get_last_forwarded_for_hop(request)\\n        if last_hop:\\n            return last_hop\\n\\n    # Default: trust only the real TCP peer.\\n    if request.client:\\n        return request.client.host\\n\\n    # Fallback if we can't determine the IP - use a non-local IP\\n    return \\\"255.255.255.255\\\"  # Non-routable IP that will never be local\\n\\n\\n@router.post(\\\"/{project_id}/install\\\")\\nasync def install_mcp_config(\\n    project_id: UUID,\\n    body: MCPInstallRequest,\\n    request: Request,\\n    current_user: CurrentActiveMCPUser,\\n):\\n    \\\"\\\"\\\"Install MCP server configuration for Cursor, Windsurf, or Claude.\\\"\\\"\\\"\\n    # Check if the request is coming from a local IP address\\n    client_ip = get_client_ip(request)\\n    if not is_local_ip(client_ip):\\n        raise HTTPException(status_code=500, detail=\\\"MCP configuration can only be installed from a local connection\\\")\\n\\n    removed_servers: list[str] = []  # Track removed servers for reinstallation\\n    try:\\n        project = await verify_project_access(project_id, current_user)\\n\\n        # Check if project requires API key authentication and generate if needed\\n        generated_api_key = None\\n\\n        # Determine if we need to generate an API key\\n        should_generate_api_key = False\\n        if not get_settings_service().settings.mcp_composer_enabled:\\n            # When MCP_COMPOSER is disabled, check auth settings or fallback to auto_login setting\\n            settings_service = get_settings_service()\\n            if project.auth_settings:\\n                # Project has auth settings - check if it requires API key\\n                if project.auth_settings.get(\\\"auth_type\\\") == \\\"apikey\\\":\\n                    should_generate_api_key = True\\n            elif not settings_service.auth_settings.AUTO_LOGIN:\\n                # No project auth settings but auto_login is disabled - generate API key\\n                should_generate_api_key = True\\n        elif project.auth_settings:\\n            # When MCP_COMPOSER is enabled, only generate if auth_type is \\\"apikey\\\"\\n            if project.auth_settings.get(\\\"auth_type\\\") == \\\"apikey\\\":\\n                should_generate_api_key = True\\n\\n        # Get settings service to build the SSE URL\\n        settings_service = get_settings_service()\\n        if settings_service.auth_settings.AUTO_LOGIN and not (\\n            settings_service.auth_settings.skip_auth_auto_login and settings_service.auth_settings.SUPERUSER\\n        ):\\n            # The MCP transport endpoints only resolve a credential-less caller to the\\n            # superuser when skip_auth_auto_login is explicitly enabled and a superuser is\\n            # configured. In every other AUTO_LOGIN configuration the installed client must\\n            # carry an API key, otherwise it would be rejected at connect time.\\n            should_generate_api_key = True\\n        settings = settings_service.settings\\n        host = settings.host or None\\n        port = settings.port or None\\n        if not host or not port:\\n            raise HTTPException(status_code=500, detail=\\\"Host and port are not set in settings\\\")\\n\\n        # Determine command and args based on operating system\\n        os_type = platform.system()\\n\\n        use_mcp_composer = should_use_mcp_composer(project)\\n        connection_urls: list[str]\\n        transport_mode = (body.transport or \\\"sse\\\").lower()\\n        if transport_mode not in {\\\"sse\\\", \\\"streamablehttp\\\"}:\\n            raise HTTPException(status_code=400, detail=\\\"Invalid transport. Use 'sse' or 'streamablehttp'.\\\")\\n\\n        if use_mcp_composer:\\n            try:\\n                auth_config = await _get_mcp_composer_auth_config(project)\\n                await get_or_start_mcp_composer(auth_config, project.name, project_id)\\n                composer_streamable_http_url = await get_composer_streamable_http_url(project)\\n                sse_url = await get_composer_sse_url(project)\\n                connection_urls = [composer_streamable_http_url, sse_url]\\n            except MCPComposerError as e:\\n                await logger.aerror(\\n                    f\\\"Failed to start MCP Composer for project '{project.name}' ({project_id}): {e.message}\\\"\\n                )\\n                raise HTTPException(status_code=500, detail=e.message) from e\\n            except Exception as e:\\n                error_msg = f\\\"Failed to start MCP Composer for project '{project.name}' ({project_id}): {e!s}\\\"\\n                await logger.aerror(error_msg)\\n                error_detail = \\\"Failed to start MCP Composer. See logs for details.\\\"\\n                raise HTTPException(status_code=500, detail=error_detail) from e\\n\\n            # For OAuth/MCP Composer, use the special format\\n            settings = get_settings_service().settings\\n            command = \\\"uvx\\\"\\n            args = [\\n                *mcp_sdk_constraint_args(),\\n                f\\\"mcp-composer{settings.mcp_composer_version}\\\",\\n                \\\"--mode\\\",\\n                \\\"http\\\",\\n                \\\"--endpoint\\\",\\n                composer_streamable_http_url,\\n                \\\"--sse-url\\\",\\n                sse_url,\\n                \\\"--client_auth_type\\\",\\n                \\\"oauth\\\",\\n                \\\"--disable-composer-tools\\\",\\n            ]\\n        else:\\n            # For non-OAuth (API key or no auth), use mcp-proxy\\n            streamable_http_url = await get_project_streamable_http_url(project_id)\\n            legacy_sse_url = await get_project_sse_url(project_id)\\n            command = \\\"uvx\\\"\\n            args = [*mcp_sdk_constraint_args(), \\\"mcp-proxy\\\"]\\n            # Check if we need to add Langflow API key headers\\n            # Necessary only when Project API Key Authentication is enabled\\n\\n            # Generate a Langflow API key for auto-install if needed\\n            # Only add API key headers for projects with \\\"apikey\\\" auth type (not \\\"none\\\" or OAuth)\\n\\n            if should_generate_api_key:\\n                async with session_scope() as api_key_session:\\n                    api_key_create = ApiKeyCreate(name=f\\\"MCP Server {project.name}\\\")\\n                    api_key_response = await create_api_key(api_key_session, api_key_create, current_user.id)\\n                    langflow_api_key = api_key_response.api_key\\n                    args.extend([\\\"--headers\\\", \\\"x-api-key\\\", langflow_api_key])\\n\\n            # Add the target URL for mcp-proxy based on requested transport\\n            proxy_target_url = streamable_http_url if transport_mode == \\\"streamablehttp\\\" else legacy_sse_url\\n            if transport_mode == \\\"streamablehttp\\\":\\n                args.extend([\\\"--transport\\\", \\\"streamablehttp\\\"])\\n            args.append(proxy_target_url)\\n            connection_urls = [streamable_http_url, legacy_sse_url]\\n\\n        if os_type == \\\"Windows\\\" and not use_mcp_composer:\\n            # Only wrap in cmd for Windows when using mcp-proxy\\n            command = \\\"cmd\\\"\\n            args = [\\\"/c\\\", \\\"uvx\\\", *args]\\n            await logger.adebug(\\\"Windows detected, using cmd command\\\")\\n\\n        name = project.name\\n        server_name = f\\\"lf-{sanitize_mcp_name(name)[: (MAX_MCP_SERVER_NAME_LENGTH - 4)]}\\\"\\n\\n        # Create the MCP configuration\\n        server_config: dict[str, Any] = {\\n            \\\"command\\\": command,\\n            \\\"args\\\": args,\\n        }\\n\\n        mcp_config = {\\\"mcpServers\\\": {server_name: server_config}}\\n\\n        await logger.adebug(\\\"Installing MCP config for project: %s (server name: %s)\\\", project.name, server_name)\\n\\n        # Get the config file path and check if client is available\\n        try:\\n            config_path = await get_config_path(body.client.lower())\\n        except ValueError as e:\\n            raise HTTPException(status_code=400, detail=str(e)) from e\\n\\n        # Check if the client application is available (config directory exists)\\n        if not config_path.parent.exists():\\n            raise HTTPException(\\n                status_code=400,\\n                detail=f\\\"{body.client.capitalize()} is not installed on this system. \\\"\\n                f\\\"Please install {body.client.capitalize()} first.\\\",\\n            )\\n\\n        # Create parent directories if they don't exist\\n        config_path.parent.mkdir(parents=True, exist_ok=True)\\n\\n        # Read existing config if it exists\\n        existing_config = {}\\n        if config_path.exists():\\n            try:\\n                with config_path.open(\\\"r\\\") as f:\\n                    existing_config = json.load(f)\\n            except json.JSONDecodeError:\\n                # If file exists but is invalid JSON, start fresh\\n                existing_config = {\\\"mcpServers\\\": {}}\\n\\n        # Ensure mcpServers section exists\\n        if \\\"mcpServers\\\" not in existing_config:\\n            existing_config[\\\"mcpServers\\\"] = {}\\n\\n        # Remove stale entries that point to the same Langflow URLs (e.g. after the project is renamed)\\n        existing_config, removed_servers = remove_server_by_urls(existing_config, connection_urls)\\n\\n        if removed_servers:\\n            await logger.adebug(\\\"Removed existing MCP servers with same SSE URL for reinstall: %s\\\", removed_servers)\\n\\n        # Merge new config with existing config\\n        existing_config[\\\"mcpServers\\\"].update(mcp_config[\\\"mcpServers\\\"])\\n\\n        # Write the updated config\\n        with config_path.open(\\\"w\\\") as f:\\n            json.dump(existing_config, f, indent=2)\\n\\n    except HTTPException:\\n        raise\\n    except Exception as e:\\n        msg = f\\\"Error installing MCP configuration: {e!s}\\\"\\n        await logger.aexception(msg)\\n        raise HTTPException(status_code=500, detail=str(e)) from e\\n    else:\\n        action = \\\"reinstalled\\\" if removed_servers else \\\"installed\\\"\\n        message = f\\\"Successfully {action} MCP configuration for {body.client}\\\"\\n        if removed_servers:\\n            message += f\\\" (replaced existing servers: {', '.join(removed_servers)})\\\"\\n        if generated_api_key:\\n            auth_type = \\\"API key\\\" if get_settings_service().settings.mcp_composer_enabled else \\\"legacy API key\\\"\\n            message += f\\\" with {auth_type} authentication (key name: 'MCP Project {project.name} - {body.client}')\\\"\\n        await logger.adebug(message)\\n        return {\\\"message\\\": message}\\n\\n\\n@router.get(\\\"/{project_id}/composer-url\\\")\\nasync def get_project_composer_url(\\n    project_id: UUID,\\n    current_user: CurrentActiveMCPUser,\\n) -> ComposerUrlResponse:\\n    \\\"\\\"\\\"Get the MCP Composer URL for a specific project.\\n\\n    On failure, this endpoint should return with a 200 status code and an error message in\\n    the body of the response to display to the user.\\n    \\\"\\\"\\\"\\n    try:\\n        project = await verify_project_access(project_id, current_user)\\n        mcp_composer_service: MCPComposerService = cast(\\n            MCPComposerService, get_service(ServiceType.MCP_COMPOSER_SERVICE)\\n        )\\n\\n        if not should_use_mcp_composer(project):\\n            streamable_http_url = await get_project_streamable_http_url(project_id)\\n            legacy_sse_url = await get_project_sse_url(project_id)\\n            # Check if there's a recent error from a failed OAuth attempt\\n            last_error = mcp_composer_service.get_last_error(str(project_id))\\n\\n            # Always return the regular MCP URLs so the UI can fall back to manual installation instructions.\\n            response_payload: dict[str, Any] = {\\n                \\\"project_id\\\": str(project_id),\\n                \\\"uses_composer\\\": False,\\n                \\\"streamable_http_url\\\": streamable_http_url,\\n                \\\"legacy_sse_url\\\": legacy_sse_url,\\n            }\\n            # If there's a recent error, return it even though OAuth is not currently active\\n            # This happens when OAuth was attempted but rolled back due to an error\\n            if last_error:\\n                response_payload[\\\"error_message\\\"] = last_error\\n            return ComposerUrlResponse(**response_payload)\\n\\n        auth_config = await _get_mcp_composer_auth_config(project)\\n\\n        try:\\n            await get_or_start_mcp_composer(auth_config, project.name, project_id)\\n            composer_streamable_http_url = await get_composer_streamable_http_url(project)\\n            composer_sse_url = await get_composer_sse_url(project)\\n            # Clear any previous error on success\\n            mcp_composer_service.clear_last_error(str(project_id))\\n            return ComposerUrlResponse(\\n                project_id=str(project_id),\\n                uses_composer=True,\\n                streamable_http_url=composer_streamable_http_url,\\n                legacy_sse_url=composer_sse_url,\\n            )\\n        except MCPComposerError as e:\\n            await logger.aerror(\\n                \\\"Failed to obtain MCP Composer URL for project %s (%s): %s\\\",\\n                project.name,\\n                project_id,\\n                e.message,\\n            )\\n            return ComposerUrlResponse(\\n                project_id=str(project_id),\\n                uses_composer=True,\\n                error_message=e.message,\\n            )\\n        except Exception as e:  # noqa: BLE001\\n            await logger.aerror(f\\\"Unexpected error getting composer URL: {e}\\\")\\n            return ComposerUrlResponse(\\n                project_id=str(project_id),\\n                uses_composer=True,\\n                error_message=\\\"Failed to start MCP Composer. See logs for details.\\\",\\n            )\\n\\n    except Exception as e:  # noqa: BLE001\\n        msg = f\\\"Error getting composer URL for project {project_id}: {e!s}\\\"\\n        await logger.aerror(msg)\\n        return ComposerUrlResponse(\\n            project_id=str(project_id),\\n            uses_composer=True,\\n            error_message=\\\"Failed to get MCP Composer URL. See logs for details.\\\",\\n        )\\n\\n\\n@router.get(\\\"/{project_id}/installed\\\")\\nasync def check_installed_mcp_servers(\\n    project_id: UUID,\\n    current_user: CurrentActiveMCPUser,\\n):\\n    \\\"\\\"\\\"Check if MCP server configuration is installed for this project in Cursor, Windsurf, or Claude.\\\"\\\"\\\"\\n    try:\\n        # Verify project exists and user has access\\n        async with session_scope() as session:\\n            project = (\\n                await session.exec(select(Folder).where(Folder.id == project_id, Folder.user_id == current_user.id))\\n            ).first()\\n\\n            if not project:\\n                raise HTTPException(status_code=404, detail=\\\"Project not found\\\")\\n\\n        project = await verify_project_access(project_id, current_user)\\n        if should_use_mcp_composer(project):\\n            project_streamable_url = await get_composer_streamable_http_url(project)\\n            project_sse_url = await get_composer_sse_url(project)\\n        else:\\n            project_streamable_url = await get_project_streamable_http_url(project_id)\\n            project_sse_url = await get_project_sse_url(project_id)\\n\\n        await logger.adebug(\\n            \\\"Checking for installed MCP servers for project: %s (SSE URL: %s)\\\", project.name, project_sse_url\\n        )\\n\\n        # Define supported clients\\n        clients = [\\\"cursor\\\", \\\"windsurf\\\", \\\"claude\\\"]\\n        results = []\\n\\n        for client_name in clients:\\n            try:\\n                # Get config path for this client\\n                config_path = await get_config_path(client_name)\\n                available = config_path.parent.exists()\\n                installed = False\\n\\n                await logger.adebug(\\\"Checking %s config at: %s (exists: %s)\\\", client_name, config_path, available)\\n\\n                # If config file exists, check if project is installed\\n                if available:\\n                    try:\\n                        with config_path.open(\\\"r\\\") as f:\\n                            config_data = json.load(f)\\n                        if config_contains_server_url(config_data, [project_streamable_url, project_sse_url]):\\n                            await logger.adebug(\\n                                \\\"Found %s config with matching URL for project %s\\\", client_name, project.name\\n                            )\\n                            installed = True\\n                        else:\\n                            await logger.adebug(\\n                                \\\"%s config exists but no server with URL: %s (available servers: %s)\\\",\\n                                client_name,\\n                                project_sse_url,\\n                                list(config_data.get(\\\"mcpServers\\\", {}).keys()),\\n                            )\\n                    except FileNotFoundError:\\n                        await logger.adebug(\\n                            \\\"%s config file not found at %s (directory exists, app installed but not configured)\\\",\\n                            client_name,\\n                            config_path,\\n                        )\\n                        # available stays True, installed stays False \u2014 app is installed but not yet configured\\n                    except json.JSONDecodeError:\\n                        await logger.awarning(\\\"Failed to parse %s config JSON at: %s\\\", client_name, config_path)\\n                        # available is True but installed remains False due to parse error\\n                else:\\n                    await logger.adebug(\\\"%s config path not found or doesn't exist: %s\\\", client_name, config_path)\\n\\n                # Add result for this client\\n                results.append({\\\"name\\\": client_name, \\\"installed\\\": installed, \\\"available\\\": available})\\n\\n            except Exception as e:  # noqa: BLE001\\n                # If there's an error getting config path or checking the client,\\n                # mark it as not available and not installed\\n                await logger.awarning(\\\"Error checking %s configuration: %s\\\", client_name, str(e))\\n                results.append({\\\"name\\\": client_name, \\\"installed\\\": False, \\\"available\\\": False})\\n\\n    except Exception as e:\\n        msg = f\\\"Error checking MCP configuration: {e!s}\\\"\\n        await logger.aexception(msg)\\n        raise HTTPException(status_code=500, detail=str(e)) from e\\n    return results\\n\\n\\ndef _normalize_url_list(urls: Sequence[str] | str) -> list[str]:\\n    \\\"\\\"\\\"Ensure URL inputs are always handled as a list of strings.\\\"\\\"\\\"\\n    if isinstance(urls, str):\\n        return [urls]\\n    try:\\n        return [str(url) for url in urls]\\n    except TypeError as exc:\\n        error_msg = \\\"urls must be a sequence of strings or a single string\\\"\\n        raise TypeError(error_msg) from exc\\n\\n\\ndef _args_reference_urls(args: Sequence[Any] | None, urls: list[str]) -> bool:\\n    \\\"\\\"\\\"Check whether the given args list references any of the provided URLs.\\\"\\\"\\\"\\n    if not args or not urls:\\n        return False\\n    return bool({arg for arg in args if isinstance(arg, str)}.intersection(urls))\\n\\n\\ndef config_contains_server_url(config_data: dict, urls: Sequence[str] | str) -> bool:\\n    \\\"\\\"\\\"Check if any MCP server in the config uses one of the specified URLs.\\\"\\\"\\\"\\n    normalized_urls = _normalize_url_list(urls)\\n    if not normalized_urls:\\n        return False\\n\\n    mcp_servers = config_data.get(\\\"mcpServers\\\", {})\\n    for server_name, server_config in mcp_servers.items():\\n        if _args_reference_urls(server_config.get(\\\"args\\\", []), normalized_urls):\\n            logger.debug(\\\"Found matching server URL in server: %s\\\", server_name)\\n            return True\\n    return False\\n\\n\\nasync def get_composer_sse_url(project: Folder) -> str:\\n    \\\"\\\"\\\"Get the SSE URL for a project using MCP Composer.\\\"\\\"\\\"\\n    auth_config = await _get_mcp_composer_auth_config(project)\\n    composer_host = auth_config.get(\\\"oauth_host\\\")\\n    composer_port = auth_config.get(\\\"oauth_port\\\")\\n    if not composer_host or not composer_port:\\n        error_msg = \\\"OAuth host and port are required to get the SSE URL for MCP Composer\\\"\\n        raise ValueError(error_msg)\\n\\n    composer_sse_url = f\\\"http://{composer_host}:{composer_port}/sse\\\"\\n    return await get_url_by_os(composer_host, composer_port, composer_sse_url)\\n\\n\\nasync def get_config_path(client: str) -> Path:\\n    \\\"\\\"\\\"Get the configuration file path for a given client and operating system.\\\"\\\"\\\"\\n    os_type = platform.system()\\n    is_wsl = os_type == \\\"Linux\\\" and \\\"microsoft\\\" in platform.uname().release.lower()\\n\\n    if client.lower() == \\\"cursor\\\":\\n        return Path.home() / \\\".cursor\\\" / \\\"mcp.json\\\"\\n    if client.lower() == \\\"windsurf\\\":\\n        return Path.home() / \\\".codeium\\\" / \\\"windsurf\\\" / \\\"mcp_config.json\\\"\\n    if client.lower() == \\\"claude\\\":\\n        if os_type == \\\"Darwin\\\":  # macOS\\n            return Path.home() / \\\"Library\\\" / \\\"Application Support\\\" / \\\"Claude\\\" / \\\"claude_desktop_config.json\\\"\\n        if os_type == \\\"Windows\\\" or is_wsl:  # Windows or WSL (Claude runs on Windows host)\\n            if is_wsl:\\n                # In WSL, we need to access the Windows APPDATA directory\\n                try:\\n                    # First try to get the Windows username\\n                    proc = await create_subprocess_exec(\\n                        \\\"/mnt/c/Windows/System32/cmd.exe\\\",\\n                        \\\"/c\\\",\\n                        \\\"echo %USERNAME%\\\",\\n                        stdout=asyncio.subprocess.PIPE,\\n                        stderr=asyncio.subprocess.PIPE,\\n                    )\\n                    stdout, _stderr = await proc.communicate()\\n\\n                    if proc.returncode == 0 and stdout.strip():\\n                        windows_username = stdout.decode().strip()\\n                        return Path(\\n                            f\\\"/mnt/c/Users/{windows_username}/AppData/Roaming/Claude/claude_desktop_config.json\\\"\\n                        )\\n\\n                    # Fallback: try to find the Windows user directory\\n                    users_dir = Path(\\\"/mnt/c/Users\\\")\\n                    if users_dir.exists():\\n                        # Get the first non-system user directory\\n                        user_dirs = [\\n                            d\\n                            for d in users_dir.iterdir()\\n                            if d.is_dir() and not d.name.startswith((\\\"Default\\\", \\\"Public\\\", \\\"All Users\\\"))\\n                        ]\\n                        if user_dirs:\\n                            return user_dirs[0] / \\\"AppData\\\" / \\\"Roaming\\\" / \\\"Claude\\\" / \\\"claude_desktop_config.json\\\"\\n\\n                    if not Path(\\\"/mnt/c\\\").exists():\\n                        msg = \\\"Windows C: drive not mounted at /mnt/c in WSL\\\"\\n                        raise ValueError(msg)\\n\\n                    msg = \\\"Could not find valid Windows user directory in WSL\\\"\\n                    raise ValueError(msg)\\n                except (OSError, CalledProcessError) as e:\\n                    await logger.awarning(\\\"Failed to determine Windows user path in WSL: %s\\\", str(e))\\n                    msg = f\\\"Could not determine Windows Claude config path in WSL: {e!s}\\\"\\n                    raise ValueError(msg) from e\\n            # Regular Windows\\n            return Path(os.environ[\\\"APPDATA\\\"]) / \\\"Claude\\\" / \\\"claude_desktop_config.json\\\"\\n\\n        msg = \\\"Unsupported operating system for Claude configuration\\\"\\n        raise ValueError(msg)\\n\\n    msg = \\\"Unsupported client\\\"\\n    raise ValueError(msg)\\n\\n\\ndef remove_server_by_urls(config_data: dict, urls: Sequence[str] | str) -> tuple[dict, list[str]]:\\n    \\\"\\\"\\\"Remove any MCP servers that use one of the specified URLs from config data.\\n\\n    Returns:\\n        tuple: (updated_config, list_of_removed_server_names)\\n    \\\"\\\"\\\"\\n    normalized_urls = _normalize_url_list(urls)\\n    if not normalized_urls:\\n        return config_data, []\\n\\n    if \\\"mcpServers\\\" not in config_data:\\n        return config_data, []\\n\\n    removed_servers: list[str] = []\\n    servers_to_remove: list[str] = []\\n\\n    # Find servers to remove\\n    for server_name, server_config in config_data[\\\"mcpServers\\\"].items():\\n        if _args_reference_urls(server_config.get(\\\"args\\\", []), normalized_urls):\\n            servers_to_remove.append(server_name)\\n\\n    # Remove the servers\\n    for server_name in servers_to_remove:\\n        del config_data[\\\"mcpServers\\\"][server_name]\\n        removed_servers.append(server_name)\\n        logger.debug(\\\"Removed existing server with matching SSE URL: %s\\\", server_name)\\n\\n    return config_data, removed_servers\\n\\n\\nasync def _get_mcp_composer_auth_config(project) -> dict:\\n    \\\"\\\"\\\"Get MCP Composer authentication configuration from project settings.\\n\\n    Args:\\n        project: The project object containing auth_settings\\n\\n    Returns:\\n        dict: The decrypted authentication configuration\\n\\n    Raises:\\n        HTTPException: If MCP Composer is not enabled or auth config is missing\\n    \\\"\\\"\\\"\\n    auth_config = None\\n    if project.auth_settings:\\n        decrypted_settings = decrypt_auth_settings(project.auth_settings)\\n        if decrypted_settings:\\n            auth_config = decrypted_settings\\n\\n    if not auth_config:\\n        error_message = \\\"Auth config is missing. Please check your settings and try again.\\\"\\n        raise ValueError(error_message)\\n\\n    return auth_config\\n\\n\\n# Project-specific MCP server instance for handling project-specific tools\\nclass ProjectMCPServer:\\n    def __init__(self, project_id: UUID):\\n        self.project_id = project_id\\n        self.server = Server(f\\\"langflow-mcp-project-{project_id}\\\")\\n        # TODO: implement an environment variable to enable/disable stateless mode\\n        self.session_manager = StreamableHTTPSessionManager(self.server, stateless=True)\\n        # since we lazily initialize the session manager's lifecycle\\n        # via .run(), which can only be called once, otherwise an error is raised,\\n        # we use the lock to prevent race conditions on concurrent requests to prevent such an error\\n        self._manager_lock = anyio.Lock()\\n        self._manager_started = False  # whether or not the session manager is running\\n\\n        # Register handlers that filter by project\\n        @self.server.list_tools()\\n        @handle_mcp_errors\\n        async def handle_list_project_tools(_request: types.ListToolsRequest) -> types.ListToolsResult:\\n            \\\"\\\"\\\"Handle listing tools for this specific project.\\\"\\\"\\\"\\n            result = await handle_list_tools_result(project_id=self.project_id, mcp_enabled_only=True)\\n            # The SDK clears its cache only on the list[Tool] branch; the ListToolsResult\\n            # branch upserts, so a tool that disappeared would linger with a stale schema.\\n            self.server._tool_cache.clear()  # noqa: SLF001\\n            return result\\n\\n        @self.server.list_prompts()\\n        async def handle_list_prompts():\\n            return []\\n\\n        @self.server.list_resources()\\n        async def handle_list_project_resources():\\n            \\\"\\\"\\\"Handle listing resources for this specific project.\\\"\\\"\\\"\\n            return await handle_list_resources(project_id=self.project_id)\\n\\n        @self.server.read_resource()\\n        async def handle_read_project_resource(uri: str) -> bytes:\\n            \\\"\\\"\\\"Handle resource read requests for this specific project.\\\"\\\"\\\"\\n            return await handle_read_resource(uri=uri, project_id=self.project_id)\\n\\n        @self.server.call_tool()\\n        @handle_mcp_errors\\n        async def handle_call_project_tool(name: str, arguments: dict) -> list[types.TextContent]:\\n            \\\"\\\"\\\"Handle tool execution requests for this specific project.\\\"\\\"\\\"\\n            return await handle_call_tool(\\n                name=name,\\n                arguments=arguments,\\n                server=self.server,\\n                project_id=self.project_id,\\n                is_action=True,\\n            )\\n\\n    async def ensure_session_manager_running(self) -> None:\\n        \\\"\\\"\\\"Start the project's Streamable HTTP manager if needed.\\\"\\\"\\\"\\n        if self._manager_started:\\n            return\\n        async with self._manager_lock:\\n            if self._manager_started:\\n                return\\n            try:\\n                task_group = get_project_task_group()\\n                await task_group.start_task(self._run_session_manager)\\n                await logger.adebug(\\\"Streamable HTTP manager started for project %s\\\", self.project_id)\\n            except Exception as e:\\n                await logger.aexception(f\\\"Failed to start session manager for project {self.project_id}: {e}\\\")\\n                raise\\n\\n    async def _run_session_manager(self, *, task_status: TaskStatus[None] = anyio.TASK_STATUS_IGNORED):\\n        \\\"\\\"\\\"Own the lifecycle of the project's Streamable HTTP session manager.\\\"\\\"\\\"\\n        try:\\n            async with self.session_manager.run():\\n                self._manager_started = True  # set flag before unblocking task (ensures waiting requests proceed)\\n                task_status.started()  # unblock\\n                await anyio.sleep_forever()\\n        except anyio.get_cancelled_exc_class():\\n            await logger.adebug(f\\\"Streamable HTTP manager cancelled for project {self.project_id}\\\")\\n        except Exception as e:\\n            await logger.aexception(f\\\"Error in session manager for project {self.project_id}: {e}\\\")\\n            raise\\n        finally:\\n            self._manager_started = False\\n            await logger.adebug(f\\\"Streamable HTTP manager stopped for project {self.project_id}\\\")\\n\\n\\n# Cache of project MCP servers\\nproject_mcp_servers: dict[str, ProjectMCPServer] = {}\\n\\n\\n# Due to the lazy initialization of the project MCP servers'\\n# streamable-http session managers, we implement a global\\n# task group (AnyIO) manager for the session managers.\\n# This ensures that each session manager's .run() context manager is\\n# entered and exited from the same coroutine, otherwise Asyncio will raise a RuntimeError.\\nclass ProjectTaskGroup:\\n    \\\"\\\"\\\"Manage the dynamically created MCP project servers' streamable-http session managers.\\n\\n    Utilizes an AnyIO TaskGroup to manage\\n    the lifecycle of the streamable-http session managers.\\n    This ensures that each session manager's .run()\\n    context manager is entered and exited from the same coroutine,\\n    otherwise Asyncio will raise a RuntimeError.\\n    \\\"\\\"\\\"\\n\\n    def __init__(self) -> None:\\n        self._started = False\\n        self._start_stop_lock = anyio.Lock()\\n        self._task_group: TaskGroup | None = None\\n        self._tg_task: asyncio.Task | None = None\\n        self._tg_ready = anyio.Event()\\n\\n    async def _start_tg(self) -> None:\\n        \\\"\\\"\\\"Background task that owns the task group lifecycle.\\n\\n        This ensures __aenter__ and __aexit__ happen in the same task.\\n        \\\"\\\"\\\"\\n        async with anyio.create_task_group() as tg:\\n            self._task_group = tg\\n            self._tg_ready.set()\\n            await anyio.sleep_forever()\\n\\n    async def start(self) -> None:\\n        \\\"\\\"\\\"Create the project task group.\\\"\\\"\\\"\\n        async with self._start_stop_lock:\\n            if self._started:\\n                return\\n            self._tg_ready = anyio.Event()\\n            self._tg_task = asyncio.create_task(self._start_tg())\\n            await self._tg_ready.wait()\\n            self._started = True\\n\\n    async def stop(self) -> None:\\n        \\\"\\\"\\\"Close the shared project task group and signal all servers to shut down.\\\"\\\"\\\"\\n        async with self._start_stop_lock:\\n            if not self._started:\\n                return\\n            try:  # https://anyio.readthedocs.io/en/stable/cancellation.html, https://docs.python.org/3/library/asyncio-task.html#asyncio.Task.cancel\\n                self._task_group.cancel_scope.cancel()  # type: ignore[union-attr]\\n                await self._tg_task  # type: ignore[misc]\\n            except Exception as e:  # noqa: BLE001\\n                await logger.aexception(f\\\"Failed to stop project task group: {e}\\\")\\n            finally:\\n                self._cleanup()\\n                await logger.adebug(\\\"Project MCP task group stopped\\\")\\n\\n    async def start_task(self, func: Callable[..., Awaitable[Any]], *args) -> Any:\\n        if not self._started or self._task_group is None:\\n            msg = \\\"MCP project task group not initialized. Call start_project_task_group() first.\\\"\\n            raise RuntimeError(msg)\\n        return await self._task_group.start(func, *args)\\n\\n    def _cleanup(self) -> None:\\n        \\\"\\\"\\\"Cleanup the project task group.\\\"\\\"\\\"\\n        self._task_group = None\\n        self._tg_task = None\\n        self._tg_ready = None\\n        self._started = False\\n        project_mcp_servers.clear()\\n\\n\\n_project_task_group = ProjectTaskGroup()\\n\\n\\nasync def start_project_task_group() -> None:\\n    \\\"\\\"\\\"Initialize the shared project task group.\\\"\\\"\\\"\\n    await _project_task_group.start()\\n\\n\\ndef get_project_task_group() -> ProjectTaskGroup:\\n    \\\"\\\"\\\"Get the project task group manager.\\\"\\\"\\\"\\n    return _project_task_group\\n\\n\\nasync def stop_project_task_group() -> None:\\n    \\\"\\\"\\\"Close the shared project task group.\\\"\\\"\\\"\\n    await _project_task_group.stop()\\n\\n\\ndef get_project_mcp_server(project_id: UUID | None) -> ProjectMCPServer:\\n    \\\"\\\"\\\"Get or create an MCP server for a specific project.\\\"\\\"\\\"\\n    if project_id is None:\\n        error_message = \\\"Project ID cannot be None when getting project MCP server\\\"\\n        raise ValueError(error_message)\\n\\n    project_id_str = str(project_id)\\n    if project_id_str not in project_mcp_servers:\\n        project_mcp_servers[project_id_str] = ProjectMCPServer(project_id)\\n    return project_mcp_servers[project_id_str]\\n\\n\\n# Note: Shutdown is handled by stop_project_task_group() in main.py lifespan\\n# This handler was removed because ProjectMCPServer doesn't have stop_session_manager()\\n# Session managers are managed centrally by ProjectTaskGroup\\n\\n\\nasync def register_project_with_composer(project: Folder):\\n    \\\"\\\"\\\"Register a project with MCP Composer by starting a dedicated composer instance.\\\"\\\"\\\"\\n    try:\\n        mcp_composer_service: MCPComposerService = cast(\\n            \\\"MCPComposerService\\\", get_service(ServiceType.MCP_COMPOSER_SERVICE)\\n        )\\n\\n        settings = get_settings_service().settings\\n        if not settings.host or not settings.port:\\n            error_msg = \\\"Langflow host and port must be set in settings to register project with MCP Composer\\\"\\n            raise ValueError(error_msg)\\n\\n        if not project.id:\\n            error_msg = \\\"Project must have an ID to register with MCP Composer\\\"\\n            raise ValueError(error_msg)\\n\\n        streamable_http_url = await get_project_local_streamable_http_url(project.id)\\n        legacy_sse_url = await get_project_local_sse_url(project.id)\\n        auth_config = await _get_mcp_composer_auth_config(project)\\n\\n        error_message = await mcp_composer_service.start_project_composer(\\n            project_id=str(project.id),\\n            streamable_http_url=streamable_http_url,\\n            auth_config=auth_config,\\n            legacy_sse_url=legacy_sse_url,\\n        )\\n        if error_message is not None:\\n            raise RuntimeError(error_message)\\n\\n        await logger.adebug(f\\\"Registered project {project.name} ({project.id}) with MCP Composer\\\")\\n\\n    except Exception as e:  # noqa: BLE001\\n        await logger.awarning(f\\\"Failed to register project {project.id} with MCP Composer: {e}\\\")\\n\\n\\ndef _get_startup_project_auth_settings(\\n    project: Folder,\\n    *,\\n    auto_login: bool,\\n    mcp_composer_enabled: bool,\\n) -> tuple[dict[str, Any] | None, str | None]:\\n    \\\"\\\"\\\"Return the auth state startup should enforce for this project.\\n\\n    Returns:\\n        A tuple of:\\n        - target auth settings used for MCP reconciliation and optional persistence\\n        - a reason string when the project auth settings should be persisted\\n    \\\"\\\"\\\"\\n    auth_type = project.auth_settings.get(\\\"auth_type\\\") if project.auth_settings else None\\n\\n    if not auto_login and auth_type in {None, \\\"none\\\"}:\\n        return {\\\"auth_type\\\": \\\"apikey\\\"}, \\\"auto_enable_apikey\\\"\\n\\n    if not mcp_composer_enabled and auth_type == \\\"oauth\\\":\\n        fallback_auth_type = \\\"apikey\\\" if not auto_login else \\\"none\\\"\\n        return {\\\"auth_type\\\": fallback_auth_type}, \\\"oauth_fallback\\\"\\n\\n    if auth_type in {\\\"apikey\\\", \\\"none\\\"}:\\n        return {\\\"auth_type\\\": auth_type}, None\\n\\n    return None, None\\n\\n\\nasync def init_mcp_servers():\\n    \\\"\\\"\\\"Initialize MCP servers for all projects.\\\"\\\"\\\"\\n    try:\\n        settings_service = get_settings_service()\\n\\n        async with session_scope() as session:\\n            projects = (await session.exec(select(Folder))).all()\\n\\n            for project in projects:\\n                try:\\n                    target_auth_settings, persist_reason = _get_startup_project_auth_settings(\\n                        project,\\n                        auto_login=settings_service.auth_settings.AUTO_LOGIN,\\n                        mcp_composer_enabled=settings_service.settings.mcp_composer_enabled,\\n                    )\\n                    reconciled_mcp_server = False\\n\\n                    async with session.begin_nested():\\n                        if persist_reason is not None and target_auth_settings is not None:\\n                            project.auth_settings = encrypt_auth_settings(target_auth_settings)\\n                            session.add(project)\\n                            await session.flush()\\n\\n                        should_reconcile_project_server = (\\n                            target_auth_settings is not None\\n                            and target_auth_settings.get(\\\"auth_type\\\") in {\\\"apikey\\\", \\\"none\\\"}\\n                            and settings_service.settings.add_projects_to_mcp_servers\\n                            and project.user_id is not None\\n                        )\\n                        if should_reconcile_project_server:\\n                            from langflow.api.v1.projects_mcp_helpers import register_mcp_servers_for_project\\n\\n                            project_user = await session.get(User, project.user_id)\\n                            if project_user is not None:\\n                                reconciled_mcp_server = await register_mcp_servers_for_project(\\n                                    project,\\n                                    target_auth_settings,\\n                                    project_user,\\n                                    session,\\n                                    raise_on_error=True,\\n                                    # This savepoint owns the transaction; a commit inside\\n                                    # would close it and break every later statement.\\n                                    owns_transaction=False,\\n                                )\\n\\n                    if persist_reason == \\\"auto_enable_apikey\\\":\\n                        await logger.ainfo(\\n                            f\\\"Auto-enabled API key authentication for existing project {project.name} \\\"\\n                            f\\\"({project.id}) due to AUTO_LOGIN=false\\\"\\n                        )\\n                    elif persist_reason == \\\"oauth_fallback\\\" and target_auth_settings is not None:\\n                        fallback_auth_type = target_auth_settings[\\\"auth_type\\\"]\\n                        await logger.adebug(\\n                            f\\\"Updated OAuth project {project.name} ({project.id}) to use {fallback_auth_type} \\\"\\n                            f\\\"authentication because MCP Composer is disabled\\\"\\n                        )\\n\\n                    if reconciled_mcp_server:\\n                        await logger.adebug(\\n                            \\\"Reconciled MCP server config for project %s (%s) on startup\\\",\\n                            project.name,\\n                            project.id,\\n                        )\\n\\n                    get_project_sse(project.id)\\n                    get_project_mcp_server(project.id)\\n                    await logger.adebug(f\\\"Initialized MCP server for project: {project.name} ({project.id})\\\")\\n\\n                    # Only register with MCP Composer if OAuth authentication is configured\\n                    if settings_service.settings.mcp_composer_enabled and project.auth_settings:\\n                        auth_type = project.auth_settings.get(\\\"auth_type\\\")\\n                        if auth_type == \\\"oauth\\\":\\n                            await logger.adebug(\\n                                f\\\"Starting MCP Composer for OAuth project {project.name} ({project.id}) on startup\\\"\\n                            )\\n                            await register_project_with_composer(project)\\n\\n                except Exception as e:  # noqa: BLE001\\n                    msg = f\\\"Failed to initialize MCP server for project {project.id}: {e}\\\"\\n                    await logger.aexception(msg)\\n                    # Continue to next project even if this one fails\\n\\n            # Auto-configure starter projects with MCP server settings if enabled\\n            await auto_configure_starter_projects_mcp(session)\\n\\n    except Exception as e:  # noqa: BLE001\\n        msg = f\\\"Failed to initialize MCP servers: {e}\\\"\\n        await logger.aexception(msg)\\n\\n\\nasync def verify_project_access(project_id: UUID, current_user: CurrentActiveMCPUser) -> Folder:\\n    \\\"\\\"\\\"Verify project exists and user has access.\\\"\\\"\\\"\\n    async with session_scope() as session:\\n        project = (\\n            await session.exec(select(Folder).where(Folder.id == project_id, Folder.user_id == current_user.id))\\n        ).first()\\n\\n        if not project:\\n            raise HTTPException(status_code=404, detail=\\\"Project not found\\\")\\n\\n        return project\\n\\n\\ndef should_use_mcp_composer(project: Folder) -> bool:\\n    \\\"\\\"\\\"Check if project uses OAuth authentication and MCP Composer is enabled.\\\"\\\"\\\"\\n    # If MCP Composer is disabled globally, never use it regardless of project settings\\n    if not get_settings_service().settings.mcp_composer_enabled:\\n        return False\\n\\n    return project.auth_settings is not None and project.auth_settings.get(\\\"auth_type\\\", \\\"\\\") == \\\"oauth\\\"\\n\\n\\nasync def get_or_start_mcp_composer(auth_config: dict, project_name: str, project_id: UUID) -> None:\\n    \\\"\\\"\\\"Get MCP Composer or start it if not running.\\n\\n    Raises:\\n        MCPComposerError: If MCP Composer fails to start\\n    \\\"\\\"\\\"\\n    from lfx.services.mcp_composer.service import MCPComposerConfigError\\n\\n    mcp_composer_service: MCPComposerService = cast(\\\"MCPComposerService\\\", get_service(ServiceType.MCP_COMPOSER_SERVICE))\\n\\n    # Prepare current auth config for comparison\\n    settings = get_settings_service().settings\\n    if not settings.host or not settings.port:\\n        error_msg = \\\"Langflow host and port must be set in settings to register project with MCP Composer\\\"\\n        raise ValueError(error_msg)\\n\\n    streamable_http_url = await get_project_local_streamable_http_url(project_id)\\n    legacy_sse_url = await get_project_local_sse_url(project_id)\\n    if not auth_config:\\n        error_msg = f\\\"Auth config is required to start MCP Composer for project {project_name}\\\"\\n        raise MCPComposerConfigError(error_msg, str(project_id))\\n\\n    await mcp_composer_service.start_project_composer(\\n        str(project_id),\\n        streamable_http_url,\\n        auth_config,\\n        legacy_sse_url=legacy_sse_url,\\n    )\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/api/v1/mcp_utils.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"ff059e916d81bc68785f37f826ad928d5dc3b1aeac397b9b8641ae3137ad908e\",\"content\":\"\\\"\\\"\\\"Common MCP handler functions shared between mcp.py and mcp_projects.py.\\n\\nThis module serves as the single source of truth for MCP functionality.\\n\\\"\\\"\\\"\\n\\nimport asyncio\\nimport base64\\nfrom collections.abc import Awaitable, Callable\\nfrom contextvars import ContextVar\\nfrom functools import wraps\\nfrom pathlib import Path\\nfrom types import SimpleNamespace\\nfrom typing import Any, ParamSpec, TypeVar\\nfrom urllib.parse import quote, unquote, urlparse\\nfrom uuid import UUID, uuid4\\n\\nfrom fastapi import HTTPException\\nfrom lfx.base.mcp.constants import MAX_MCP_TOOL_NAME_LENGTH\\nfrom lfx.base.mcp.util import get_flow_snake_case, get_unique_name, sanitize_mcp_name\\nfrom lfx.log.logger import logger\\nfrom lfx.observability import execution_protocol\\nfrom lfx.utils.flow_validation import (\\n    CustomComponentValidationError,\\n    prepare_public_flow_build,\\n    validate_public_flow_no_code_execution,\\n)\\nfrom lfx.utils.helpers import build_content_type_from_extension\\nfrom mcp import types\\nfrom sqlmodel import select\\n\\nfrom langflow.api.utils.core import strip_secret_field_values\\nfrom langflow.api.utils.flow_utils import compute_virtual_flow_id, scope_session_to_namespace\\nfrom langflow.api.v1.endpoints import simple_run_flow\\nfrom langflow.api.v1.run_validation import HITL_UNSUPPORTED_DETAIL, flow_requires_hitl\\nfrom langflow.api.v1.schemas import SimplifiedAPIRequest\\nfrom langflow.helpers.flow import get_flow_input_tweaks, json_schema_from_flow\\nfrom langflow.schema.message import Message\\nfrom langflow.services.authorization import FlowAction, ensure_flow_permission\\nfrom langflow.services.authorization.public_access import public_execution_user\\nfrom langflow.services.database.models import Flow\\nfrom langflow.services.database.models.file.model import File as UserFile\\nfrom langflow.services.database.models.user.model import User\\nfrom langflow.services.deps import get_settings_service, get_storage_service, session_scope\\n\\nT = TypeVar(\\\"T\\\")\\nP = ParamSpec(\\\"P\\\")\\n\\nMCP_SERVERS_FILE = \\\"_mcp_servers\\\"\\n\\n# Create context variables\\ncurrent_user_ctx: ContextVar[User] = ContextVar(\\\"current_user_ctx\\\")\\n\\nauthenticated_caller_ctx: ContextVar[UUID | None] = ContextVar(\\\"authenticated_caller_ctx\\\", default=None)\\n\\n\\ndef caller_owns_resource(owner_id: UUID | None) -> bool:\\n    \\\"\\\"\\\"Whether the credential presented on this request belongs to the resource owner.\\n\\n    The principal a tool call *executes as* is not always the principal that authenticated:\\n    a project with ``auth_type=\\\"none\\\"`` runs as its owner on behalf of an anonymous caller,\\n    so comparing the execution principal to the owner answers yes for everyone. The caller\\n    context defaults to unset, which reads as anonymous, so a path that never establishes a\\n    caller loses the privilege instead of inheriting the owner's.\\n    \\\"\\\"\\\"\\n    caller_id = authenticated_caller_ctx.get()\\n    return caller_id is not None and owner_id is not None and caller_id == owner_id\\n\\n\\ndef _public_mcp_session_namespace(server: Any, project_id: UUID, flow_id: UUID) -> str:\\n    \\\"\\\"\\\"Return a per-MCP-connection namespace for anonymous session IDs.\\\"\\\"\\\"\\n    mcp_session = getattr(getattr(server, \\\"request_context\\\", None), \\\"session\\\", None)\\n    connection_id = getattr(mcp_session, \\\"session_id\\\", None)\\n    if not connection_id:\\n        # The SSE session object is stable for the life of a connection even on\\n        # SDK versions that do not expose a public session identifier.\\n        connection_id = str(id(mcp_session)) if mcp_session is not None else str(uuid4())\\n    identifier = f\\\"mcp:{project_id}:{connection_id}\\\"\\n    return str(compute_virtual_flow_id(identifier, flow_id, principal_type=\\\"client\\\"))\\n\\n\\ndef _restore_public_mcp_request_variable_references(\\n    source: Any,\\n    sanitized: Any,\\n    request_variables: dict[str, str],\\n) -> None:\\n    \\\"\\\"\\\"Restore sanitized variable names only when the current request supplies them.\\n\\n    Public MCP execution scrubs all secret-looking values before building the flow. A\\n    ``load_from_db`` field or table cell contains a variable *name*, not the stored\\n    secret, and the build needs that name to resolve a request-scoped override. Restore\\n    only references that have a matching request value so anonymous execution cannot\\n    fall back to an owner's database variables or ambient environment credentials.\\n    \\\"\\\"\\\"\\n    if isinstance(source, dict) and isinstance(sanitized, dict):\\n        source_value = source.get(\\\"value\\\")\\n        if source.get(\\\"load_from_db\\\") is True and isinstance(source_value, str) and source_value in request_variables:\\n            sanitized[\\\"value\\\"] = source_value\\n\\n        row_load_from_db_fields = source.get(\\\"__load_from_db_fields\\\")\\n        if isinstance(row_load_from_db_fields, dict):\\n            variable_fields = [name for name, enabled in row_load_from_db_fields.items() if enabled is True]\\n        elif isinstance(row_load_from_db_fields, list):\\n            variable_fields = row_load_from_db_fields\\n        else:\\n            variable_fields = []\\n        for field_name in variable_fields:\\n            variable_name = source.get(field_name)\\n            if isinstance(field_name, str) and isinstance(variable_name, str) and variable_name in request_variables:\\n                sanitized[field_name] = variable_name\\n\\n        for key, source_child in source.items():\\n            if key in sanitized:\\n                _restore_public_mcp_request_variable_references(\\n                    source_child,\\n                    sanitized[key],\\n                    request_variables,\\n                )\\n    elif isinstance(source, list) and isinstance(sanitized, list):\\n        for source_item, sanitized_item in zip(source, sanitized, strict=False):\\n            _restore_public_mcp_request_variable_references(source_item, sanitized_item, request_variables)\\n\\n\\nasync def _prepare_public_mcp_execution_flow(\\n    flow: Flow,\\n    request_variables: dict[str, str] | None = None,\\n) -> Flow:\\n    \\\"\\\"\\\"Apply the shared anonymous-flow policy to a detached MCP execution graph.\\\"\\\"\\\"\\n    validate_public_flow_no_code_execution(flow.data)\\n    prepared_data = await prepare_public_flow_build(flow.data)\\n    source_data = prepared_data if prepared_data is not None else flow.data\\n    sanitized_data = strip_secret_field_values(source_data)\\n    if request_variables:\\n        _restore_public_mcp_request_variable_references(source_data, sanitized_data, request_variables)\\n    return flow.model_copy(update={\\\"data\\\": sanitized_data}, deep=True)\\n\\n\\nEXCLUDED_FLOWS_META_KEY = \\\"langflow.org/excluded-flows\\\"\\n# Carries per-request variables injected via HTTP headers (e.g., X-Langflow-Global-Var-*)\\ncurrent_request_variables_ctx: ContextVar[dict[str, str] | None] = ContextVar(\\n    \\\"current_request_variables_ctx\\\", default=None\\n)\\n# Carries the inbound request's headers into the deep MCP tool dispatch. The MCP SDK invokes\\n# handle_call_tool through its own machinery, so the live FastAPI request is not on the call\\n# chain; the streamable/SSE endpoint stashes ``request.headers`` here (same pattern as\\n# current_request_variables_ctx) so a tool run can scope to the serving end-user identity via\\n# the same ``resolve_serving_scope`` path /run and /workflows use. None outside a request.\\ncurrent_request_headers_ctx: ContextVar[Any] = ContextVar(\\\"current_request_headers_ctx\\\", default=None)\\n\\n\\ndef handle_mcp_errors(func: Callable[P, Awaitable[T]]) -> Callable[P, Awaitable[T]]:\\n    \\\"\\\"\\\"Decorator to handle MCP endpoint errors consistently.\\\"\\\"\\\"\\n\\n    @wraps(func)\\n    async def wrapper(*args: P.args, **kwargs: P.kwargs) -> T:\\n        try:\\n            return await func(*args, **kwargs)\\n        except Exception as e:\\n            msg = f\\\"Error in {func.__name__}: {e!s}\\\"\\n            await logger.aexception(msg)\\n            raise\\n\\n    return wrapper\\n\\n\\nasync def with_db_session(operation: Callable[[Any], Awaitable[T]]) -> T:\\n    \\\"\\\"\\\"Execute an operation within a database session context.\\\"\\\"\\\"\\n    async with session_scope() as session:\\n        return await operation(session)\\n\\n\\nclass MCPConfig:\\n    _instance = None\\n\\n    def __new__(cls):\\n        if cls._instance is None:\\n            cls._instance = super().__new__(cls)\\n            cls._instance.enable_progress_notifications = None\\n        return cls._instance\\n\\n\\ndef get_mcp_config():\\n    return MCPConfig()\\n\\n\\ndef raise_if_sse_disabled() -> None:\\n    \\\"\\\"\\\"Reject legacy SSE transport requests when the deployment has turned it off.\\\"\\\"\\\"\\n    if not get_settings_service().settings.mcp_sse_enabled:\\n        raise HTTPException(status_code=404, detail=\\\"SSE transport is disabled. Use the Streamable HTTP endpoint.\\\")\\n\\n\\nasync def handle_list_resources(project_id=None):\\n    \\\"\\\"\\\"Handle listing resources for MCP.\\n\\n    Args:\\n        project_id: Optional project ID to filter resources by project\\n    \\\"\\\"\\\"\\n    resources = []\\n    try:\\n        storage_service = get_storage_service()\\n        settings_service = get_settings_service()\\n\\n        # Build full URL from settings\\n        host = getattr(settings_service.settings, \\\"host\\\", \\\"localhost\\\")\\n        port = getattr(settings_service.settings, \\\"port\\\", 3000)\\n\\n        base_url = f\\\"http://{host}:{port}\\\".rstrip(\\\"/\\\")\\n        try:\\n            current_user = current_user_ctx.get()\\n        except Exception as e:  # noqa: BLE001\\n            msg = f\\\"Error getting current user: {e!s}\\\"\\n            await logger.aexception(msg)\\n            current_user = None\\n\\n        # SECURITY: The current_user context is required to scope resources.\\n        # Without it we cannot safely list files from any flow because the\\n        # global server previously leaked every user's flow URIs (PVR0754098).\\n        if current_user is None:\\n            await logger.awarning(\\\"handle_list_resources called without a current user; returning empty list\\\")\\n            return resources\\n\\n        async with session_scope() as session:\\n            # SECURITY: Always scope to the calling user to prevent cross-user enumeration.\\n            if project_id:\\n                flows_query = select(Flow).where(Flow.folder_id == project_id, Flow.user_id == current_user.id)\\n            else:\\n                flows_query = select(Flow).where(Flow.user_id == current_user.id)\\n\\n            flows = (await session.exec(flows_query)).all()\\n\\n            for flow in flows:\\n                if flow.id:\\n                    try:\\n                        files = await storage_service.list_files(flow_id=str(flow.id))\\n                        for file_name in files:\\n                            # URL encode the filename\\n                            safe_filename = quote(file_name)\\n                            resource = types.Resource(\\n                                uri=f\\\"{base_url}/api/v1/files/download/{flow.id}/{safe_filename}\\\",\\n                                name=file_name,\\n                                description=f\\\"File in flow: {flow.name}\\\",\\n                                mimeType=build_content_type_from_extension(file_name),\\n                            )\\n                            resources.append(resource)\\n                    except FileNotFoundError as e:\\n                        msg = f\\\"Error listing files for flow {flow.id}: {e}\\\"\\n                        await logger.adebug(msg)\\n                        continue\\n            ####################################################\\n            # When a user uploads a file inside a flow\\n            # (e.g., via the File Read component),\\n            # it hits /api/v2/files (POST),\\n            # which saves files at the user-level.\\n            # So the above query for flow files is not enough.\\n            # So we list all user files for the current user.\\n            # This is not good. We need to fix this for 1.8.0.\\n            #\\n            # SECURITY (PVR0754098): user-level files have no project association,\\n            # so they must not be exposed through a project-scoped MCP server \u2014\\n            # doing so would let a project client enumerate files unrelated to\\n            # the project. Only include them on the global (project_id is None) server.\\n            ###################################################\\n            if project_id is None:\\n                user_files_stmt = select(UserFile).where(UserFile.user_id == current_user.id)\\n                user_files = (await session.exec(user_files_stmt)).all()\\n                for user_file in user_files:\\n                    stored_path = getattr(user_file, \\\"path\\\", \\\"\\\") or \\\"\\\"\\n                    stored_filename = Path(stored_path).name if stored_path else user_file.name\\n                    safe_filename = quote(stored_filename)\\n                    if stored_filename.startswith(f\\\"{MCP_SERVERS_FILE}_{current_user.id}\\\"):\\n                        # reserved file name for langflow MCP server config file(s)\\n                        continue\\n                    description = getattr(user_file, \\\"provider\\\", None) or \\\"User file uploaded via File Manager\\\"\\n                    resource = types.Resource(\\n                        uri=f\\\"{base_url}/api/v1/files/download/{current_user.id}/{safe_filename}\\\",\\n                        name=stored_filename,\\n                        description=description,\\n                        mimeType=build_content_type_from_extension(stored_filename),\\n                    )\\n                    resources.append(resource)\\n    except Exception as e:\\n        msg = f\\\"Error in listing resources: {e!s}\\\"\\n        await logger.aexception(msg)\\n        raise\\n    return resources\\n\\n\\nasync def handle_read_resource(uri: str, project_id: UUID | str | None = None) -> bytes:\\n    \\\"\\\"\\\"Handle resource read requests.\\n\\n    Args:\\n        uri: The resource URI; last two path segments are the namespace (flow_id or user_id)\\n            and filename.\\n        project_id: When invoked from a project-scoped server, restricts the lookup so a\\n            caller cannot read resources that live outside the project.\\n    \\\"\\\"\\\"\\n    try:\\n        # Parse the URI properly\\n        parsed_uri = urlparse(str(uri))\\n        # Path will be like /api/v1/files/download/{namespace}/{filename}\\n        path_parts = parsed_uri.path.split(\\\"/\\\")\\n        # Remove empty strings from split\\n        path_parts = [p for p in path_parts if p]\\n\\n        # The flow_id and filename should be the last two parts\\n        two = 2\\n        if len(path_parts) < two:\\n            msg = f\\\"Invalid URI format: {uri}\\\"\\n            raise ValueError(msg)\\n\\n        namespace_id = path_parts[-2]\\n        filename = unquote(path_parts[-1])  # URL decode the filename\\n\\n        # SECURITY (defense-in-depth): reject obvious traversal attempts before any\\n        # service call. The storage service validates as well, but failing fast here\\n        # keeps error logs from the storage layer off the hot path and closes the gap\\n        # between the MCP decode step and the storage layer for future refactors.\\n        if not filename or \\\"..\\\" in filename or \\\"/\\\" in filename or \\\"\\\\\\\\\\\" in filename:\\n            await logger.awarning(f\\\"Rejected MCP resource read with invalid filename: {filename!r}\\\")\\n            msg = \\\"Invalid filename\\\"\\n            raise ValueError(msg)\\n\\n        # SECURITY: authorise the caller before reading. The storage layer alone is\\n        # not enough because the filesystem doesn't know about Langflow users, and\\n        # previously any authenticated user could request any flow_id.\\n        try:\\n            current_user = current_user_ctx.get()\\n        except LookupError as exc:\\n            msg = \\\"Authenticated user context is required to read MCP resources\\\"\\n            raise ValueError(msg) from exc\\n\\n        parsed_project_id = None\\n        if project_id is not None:\\n            try:\\n                parsed_project_id = UUID(str(project_id))\\n            except ValueError as exc:\\n                msg = \\\"Resource not found or access denied\\\"\\n                raise ValueError(msg) from exc\\n\\n        async with session_scope() as session:\\n            try:\\n                flow_id = UUID(namespace_id)\\n            except ValueError:\\n                flow = None\\n            else:\\n                flow_query = select(Flow).where(Flow.id == flow_id, Flow.user_id == current_user.id)\\n                if parsed_project_id is not None:\\n                    flow_query = flow_query.where(Flow.folder_id == parsed_project_id)\\n                flow = (await session.exec(flow_query)).first()\\n\\n            if flow is None:\\n                # The namespace segment may refer to the user's own bucket (user-level\\n                # files uploaded via /api/v2/files) rather than a flow id.\\n                if str(current_user.id) != str(namespace_id):\\n                    msg = \\\"Resource not found or access denied\\\"\\n                    raise ValueError(msg)\\n                # User-level access is never in-scope for a project-scoped server.\\n                if project_id is not None:\\n                    msg = \\\"Resource not found or access denied\\\"\\n                    raise ValueError(msg)\\n\\n        storage_service = get_storage_service()\\n\\n        # Read the file content\\n        content = await storage_service.get_file(flow_id=namespace_id, file_name=filename)\\n        if not content:\\n            msg = f\\\"File {filename} not found in flow {namespace_id}\\\"\\n            raise ValueError(msg)\\n\\n        # Ensure content is base64 encoded\\n        if isinstance(content, str):\\n            content = content.encode()\\n        return base64.b64encode(content)\\n    except Exception as e:\\n        msg = f\\\"Error reading resource {uri}: {e!s}\\\"\\n        await logger.aexception(msg)\\n        raise\\n\\n\\nasync def handle_call_tool(\\n    name: str, arguments: dict, server, project_id=None, *, is_action=False\\n) -> list[types.TextContent]:\\n    \\\"\\\"\\\"Handle tool execution requests.\\n\\n    Args:\\n        name: Tool name\\n        arguments: Tool arguments\\n        server: MCP server instance\\n        project_id: Optional project ID to filter flows by project\\n        is_action: Whether to use action name for flow lookup\\n    \\\"\\\"\\\"\\n    mcp_config = get_mcp_config()\\n    if mcp_config.enable_progress_notifications is None:\\n        settings_service = get_settings_service()\\n        mcp_config.enable_progress_notifications = settings_service.settings.mcp_server_enable_progress_notifications\\n\\n    current_user = current_user_ctx.get()\\n    # Build execution context with request-level variables if present\\n    request_variables = current_request_variables_ctx.get()\\n    exec_context = {\\\"request_variables\\\": request_variables} if request_variables else None\\n\\n    async def execute_tool(session):\\n        # Scoping in the query, not after it: post-filtering let an unexposed flow run by\\n        # name and let one project win a name shared with another, silencing the second.\\n        flow = await get_flow_snake_case(\\n            name,\\n            current_user.id,\\n            session,\\n            is_action=is_action,\\n            project_id=project_id,\\n            mcp_enabled_only=project_id is not None,\\n        )\\n        if not flow:\\n            msg = f\\\"Flow with name '{name}' not found\\\"\\n            raise ValueError(msg)\\n\\n        # Defense in depth: the query above already scopes by project.\\n        if project_id and flow.folder_id != project_id:\\n            msg = f\\\"Flow '{name}' not found in project {project_id}\\\"\\n            raise ValueError(msg)\\n\\n        # Enforce execute permission (owner override + external access ceiling)\\n        # before running the flow. Without this an external \\\"viewer\\\" could run a\\n        # flow as a tool, escaping the deny-only access ceiling.\\n        await ensure_flow_permission(\\n            current_user,\\n            FlowAction.EXECUTE,\\n            flow_id=flow.id,\\n            flow_user_id=flow.user_id,\\n            workspace_id=flow.workspace_id,\\n            folder_id=flow.folder_id,\\n        )\\n\\n        if flow_requires_hitl(flow.data or {}):\\n            raise RuntimeError(HITL_UNSUPPORTED_DETAIL)\\n\\n        is_public_project_call = project_id is not None and authenticated_caller_ctx.get() is None\\n        execution_flow = flow\\n        execution_user = current_user\\n        if is_public_project_call:\\n            try:\\n                execution_flow = await _prepare_public_mcp_execution_flow(flow, request_variables)\\n            except CustomComponentValidationError as exc:\\n                await logger.awarning(f\\\"Public MCP tool call blocked for flow {flow.id}: {exc!s}\\\")\\n                msg = \\\"This flow cannot be executed through a public MCP project.\\\"\\n                raise RuntimeError(msg) from exc\\n            execution_user = public_execution_user()\\n\\n        # Process inputs\\n        processed_inputs = dict(arguments)\\n\\n        # Initial progress notification\\n        if mcp_config.enable_progress_notifications and (progress_token := server.request_context.meta.progressToken):\\n            await server.request_context.session.send_progress_notification(\\n                progress_token=progress_token, progress=0.0, total=1.0\\n            )\\n\\n        session_id = processed_inputs.pop(\\\"session_id\\\", None) or str(uuid4())\\n        if is_public_project_call:\\n            namespace = _public_mcp_session_namespace(server, project_id, flow.id)\\n            session_id = scope_session_to_namespace(session_id, namespace) or namespace\\n        input_value = processed_inputs.pop(\\\"input_value\\\", \\\"\\\")\\n        tweaks = get_flow_input_tweaks(execution_flow, processed_inputs) if processed_inputs else None\\n        input_request = SimplifiedAPIRequest(\\n            input_value=input_value,\\n            session_id=session_id,\\n            tweaks=tweaks or None,\\n        )\\n\\n        async def send_progress_updates(progress_token):\\n            try:\\n                progress = 0.0\\n                while True:\\n                    await server.request_context.session.send_progress_notification(\\n                        progress_token=progress_token, progress=min(0.9, progress), total=1.0\\n                    )\\n                    progress += 0.1\\n                    await asyncio.sleep(1.0)\\n            except asyncio.CancelledError:\\n                if mcp_config.enable_progress_notifications:\\n                    await server.request_context.session.send_progress_notification(\\n                        progress_token=progress_token, progress=1.0, total=1.0\\n                    )\\n                raise\\n\\n        collected_results = []\\n        try:\\n            progress_task = None\\n            if mcp_config.enable_progress_notifications and server.request_context.meta.progressToken:\\n                progress_task = asyncio.create_task(send_progress_updates(server.request_context.meta.progressToken))\\n\\n            try:\\n                # Scope the run to the serving end-user identity exactly as /run and\\n                # /workflows do: the MCP SDK dispatch has no live request on the call\\n                # chain, so replay the endpoint-captured headers through a minimal shim\\n                # (resolve_serving_scope only needs ``headers.get``). None -> feature off\\n                # / no request -> scoping skipped, byte-for-byte the prior behavior.\\n                req_headers = current_request_headers_ctx.get()\\n                http_request_shim = SimpleNamespace(headers=req_headers) if req_headers is not None else None\\n                try:\\n                    with execution_protocol(\\\"mcp\\\"):\\n                        result = await simple_run_flow(\\n                            flow=execution_flow,\\n                            input_request=input_request,\\n                            stream=False,\\n                            api_key_user=execution_user,\\n                            context=exec_context,\\n                            expose_error_details=caller_owns_resource(flow.user_id),\\n                            http_request=http_request_shim,\\n                        )\\n                    # Process all outputs and messages, ensuring no duplicates\\n                    processed_texts = set()\\n\\n                    def add_result(text: str):\\n                        if text not in processed_texts:\\n                            processed_texts.add(text)\\n                            collected_results.append(types.TextContent(type=\\\"text\\\", text=text))\\n\\n                    for run_output in result.outputs:\\n                        for component_output in run_output.outputs:\\n                            # Handle messages\\n                            for msg in component_output.messages or []:\\n                                add_result(msg.message)\\n                            # Handle results\\n                            for value in (component_output.results or {}).values():\\n                                if isinstance(value, Message):\\n                                    add_result(value.get_text())\\n                                else:\\n                                    add_result(str(value))\\n                # Raise rather than return the message as content: an MCP client cannot\\n                # tell a failure from an answer unless the response carries isError.\\n                except CustomComponentValidationError as exc:\\n                    logger.warning(f\\\"MCP tool call blocked for flow {flow.id}: {exc!s}\\\")\\n                    msg = f\\\"Flow build blocked for the {flow.name} tool. Error: {exc!s}\\\"\\n                    raise RuntimeError(msg) from exc\\n                except Exception as exc:\\n                    msg = f\\\"Error Executing the {flow.name} tool. Error: {exc!s}\\\"\\n                    raise RuntimeError(msg) from exc\\n\\n                return collected_results\\n            finally:\\n                if progress_task:\\n                    progress_task.cancel()\\n                    await asyncio.gather(progress_task, return_exceptions=True)\\n\\n        except Exception:\\n            if mcp_config.enable_progress_notifications and (\\n                progress_token := server.request_context.meta.progressToken\\n            ):\\n                await server.request_context.session.send_progress_notification(\\n                    progress_token=progress_token, progress=1.0, total=1.0\\n                )\\n            raise\\n\\n    try:\\n        return await with_db_session(execute_tool)\\n    except Exception as e:\\n        msg = f\\\"Error executing tool {name}: {e!s}\\\"\\n        await logger.aexception(msg)\\n        raise\\n\\n\\nasync def _collect_tools(\\n    project_id: UUID | None = None, *, mcp_enabled_only: bool = False\\n) -> tuple[list[types.Tool], list[dict[str, str]]]:\\n    \\\"\\\"\\\"Build the tool list for MCP, returning the flows that could not be built alongside it.\\n\\n    Args:\\n        project_id: Optional project ID to filter tools by project\\n        mcp_enabled_only: Whether to filter for MCP-enabled flows only\\n\\n    Returns:\\n        The tools that built successfully and one entry per flow dropped from the list.\\n    \\\"\\\"\\\"\\n    tools: list[types.Tool] = []\\n    excluded: list[dict[str, str]] = []\\n    try:\\n        # SECURITY: tools returned from the global server previously included every\\n        # user's flows (PVR0754098). Always scope to the authenticated caller.\\n        try:\\n            current_user = current_user_ctx.get()\\n        except LookupError:\\n            current_user = None\\n\\n        async with session_scope() as session:\\n            # Build query based on parameters\\n            if project_id:\\n                # SECURITY (defense-in-depth): Filter by both folder_id AND user_id.\\n                # While verify_project_auth_conditional already ensures the user owns the project,\\n                # this query-level filter provides an additional safety layer and maintains\\n                # consistency with handle_list_resources() and handle_read_resource().\\n                if current_user is None:\\n                    await logger.awarning(\\n                        \\\"handle_list_tools called with project_id but no current user; returning empty list\\\"\\n                    )\\n                    return tools, excluded\\n                # Ordered for the same reason the call path is: without it, which duplicate\\n                # holds the bare callable name and which gets get_unique_name's _1 suffix\\n                # is heap order, so it can flip between two calls.\\n                flows_query = (\\n                    select(Flow)\\n                    .where(\\n                        Flow.folder_id == project_id,\\n                        Flow.user_id == current_user.id,\\n                        Flow.is_component == False,  # noqa: E712\\n                    )\\n                    .order_by(Flow.id)\\n                )\\n                if mcp_enabled_only:\\n                    flows_query = flows_query.where(Flow.mcp_enabled == True)  # noqa: E712\\n            elif current_user is not None:\\n                # Global server: scope to the calling user only.\\n                flows_query = select(Flow).where(Flow.user_id == current_user.id).order_by(Flow.id)\\n            else:\\n                await logger.awarning(\\n                    \\\"handle_list_tools called without a current user and no project_id; returning empty list\\\"\\n                )\\n                return tools, excluded\\n\\n            flows = (await session.exec(flows_query)).all()\\n\\n            existing_names = set()\\n            for flow in flows:\\n                if flow.user_id is None:\\n                    continue\\n\\n                # For project-specific tools, use action names if available\\n                if project_id:\\n                    base_name = (\\n                        sanitize_mcp_name(flow.action_name) if flow.action_name else sanitize_mcp_name(flow.name)\\n                    )\\n                    name = get_unique_name(base_name, MAX_MCP_TOOL_NAME_LENGTH, existing_names)\\n                    description = flow.action_description or (\\n                        flow.description if flow.description else f\\\"Tool generated from flow: {name}\\\"\\n                    )\\n                else:\\n                    # For global tools, use simple sanitized names\\n                    base_name = sanitize_mcp_name(flow.name)\\n                    name = base_name[:MAX_MCP_TOOL_NAME_LENGTH]\\n                    if name in existing_names:\\n                        i = 1\\n                        while True:\\n                            suffix = f\\\"_{i}\\\"\\n                            truncated_base = base_name[: MAX_MCP_TOOL_NAME_LENGTH - len(suffix)]\\n                            candidate = f\\\"{truncated_base}{suffix}\\\"\\n                            if candidate not in existing_names:\\n                                name = candidate\\n                                break\\n                            i += 1\\n                    description = (\\n                        f\\\"{flow.id}: {flow.description}\\\" if flow.description else f\\\"Tool generated from flow: {name}\\\"\\n                    )\\n\\n                try:\\n                    tool = types.Tool(\\n                        name=name,\\n                        description=description,\\n                        inputSchema=json_schema_from_flow(flow),\\n                    )\\n                    tools.append(tool)\\n                    existing_names.add(name)\\n                except Exception as e:  # noqa: BLE001\\n                    # Type only: the project endpoint answers end users on the serving plane, and a raw\\n                    # exception string carries paths, SQL and component internals. The full\\n                    # message stays in the error log below, where only the operator reads it.\\n                    excluded.append({\\\"flow_id\\\": str(flow.id), \\\"tool_name\\\": base_name, \\\"reason\\\": type(e).__name__})\\n                    await logger.aerror(f\\\"Flow excluded from MCP tool list -- {base_name} ({flow.id}): {e!s}\\\")\\n                    continue\\n\\n            # A project that answers 200 with an empty list reads as \\\"no tools configured\\\".\\n            # If every flow was dropped, say so instead of letting the deploy look healthy.\\n            # Scoped to the project endpoint: the global server is the editor-plane surface,\\n            # where an empty list is a normal state and raising would be a UI regression.\\n            if project_id and excluded and not tools:\\n                raise RuntimeError(_format_excluded(excluded))\\n    except Exception as e:\\n        msg = f\\\"Error in listing tools: {e!s}\\\"\\n        await logger.aexception(msg)\\n        raise\\n    return tools, excluded\\n\\n\\ndef _format_excluded(excluded: list[dict[str, str]]) -> str:\\n    details = \\\"; \\\".join(f\\\"{item['tool_name']} ({item['flow_id']}): {item['reason']}\\\" for item in excluded)\\n    return f\\\"No MCP tools could be built. Excluded flows: {details}\\\"\\n\\n\\nasync def handle_list_tools(project_id: UUID | None = None, *, mcp_enabled_only: bool = False) -> list[types.Tool]:\\n    \\\"\\\"\\\"Handle listing tools for MCP.\\n\\n    Args:\\n        project_id: Optional project ID to filter tools by project\\n        mcp_enabled_only: Whether to filter for MCP-enabled flows only\\n    \\\"\\\"\\\"\\n    tools, _ = await _collect_tools(project_id, mcp_enabled_only=mcp_enabled_only)\\n    return tools\\n\\n\\nasync def handle_list_tools_result(\\n    project_id: UUID | None = None, *, mcp_enabled_only: bool = False\\n) -> types.ListToolsResult:\\n    \\\"\\\"\\\"Handle listing tools for a project, reporting any flow that had to be dropped.\\n\\n    Returning only the surviving tools reads as a complete list, so an operator cannot tell\\n    that a tool went missing and the sole trace is a server-side log line. Partial failures\\n    ride along in ``_meta`` because the tool array itself must stay callable-only.\\n    \\\"\\\"\\\"\\n    tools, excluded = await _collect_tools(project_id, mcp_enabled_only=mcp_enabled_only)\\n    result = types.ListToolsResult(tools=tools)\\n    if excluded:\\n        # Assigned rather than passed to the constructor: the field is aliased to `_meta`\\n        # and the model has no populate_by_name, so `meta=` lands as an extra field.\\n        result.meta = {EXCLUDED_FLOWS_META_KEY: excluded}\\n    return result\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/api/v1/memories.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"f3f8522e284f34958d8fb129806b734087be394dfa1d1d79a901bdc886072312\",\"content\":\"\\\"\\\"\\\"REST API for Memory Base management.\\n\\nEndpoints:\\n    POST   /memories                    - Create\\n    GET    /memories                    - List (current user, paginated)\\n    GET    /memories/{id}               - Get one\\n    GET    /memories/{id}/sessions      - List sessions (tracked + untracked from MessageTable)\\n    GET    /memories/{id}/messages      - List ingested messages (optionally filtered by ?session_id=)\\n    PATCH  /memories/{id}               - Update (name / threshold / auto_capture)\\n    DELETE /memories/{id}               - Delete (cancels active tasks + removes KB from disk)\\n    POST   /memories/{id}/flush        - Manual flush / trigger ingestion\\n    POST   /memories/{id}/regenerate    - Regenerate from mismatch\\n\\nEdge cases enforced:\\n    409 Conflict  - name already in use for this user (on create).\\n    409 Conflict  - active ingestion task already running for same (mb, session).\\n    404 Not Found - memory base does not belong to the current user.\\n    422 Unprocessable - preprocessing=true but preproc_model missing.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport uuid\\nfrom datetime import datetime\\nfrom http import HTTPStatus\\nfrom typing import Annotated, Any\\n\\nfrom fastapi import APIRouter, Body, Depends, HTTPException\\nfrom fastapi_pagination import Page, Params\\nfrom fastapi_pagination.ext.sqlmodel import apaginate\\nfrom lfx.schema.legacy_render import render_v1_content_blocks\\nfrom lfx.services.model_provider_policy import ModelProviderPolicyError\\nfrom pydantic import BaseModel\\n\\nfrom langflow.api.utils import CurrentActiveUser, knowledge_base_service\\nfrom langflow.services.authorization import KnowledgeBaseAction, ensure_knowledge_base_permission\\nfrom langflow.services.authorization.fetch import deny_to_404\\nfrom langflow.services.authorization.listing import visible_scope_prefilter\\nfrom langflow.services.database.models.memory_base.model import (\\n    MemoryBase,\\n    MemoryBaseCreate,\\n    MemoryBaseRead,\\n    MemoryBaseSessionRead,\\n    MemoryBaseUpdate,\\n)\\nfrom langflow.services.deps import get_authorization_service, get_memory_base_service, session_scope\\nfrom langflow.services.jobs import DuplicateJobError\\nfrom langflow.services.memory_base.kb_path_helpers import BackendProvisioningError\\nfrom langflow.services.memory_base.provider_scope import MemoryBaseFlowNotFoundError\\nfrom langflow.services.memory_base.service import EmbeddingProviderValidationError, PreprocessingValidationError\\n\\nrouter = APIRouter(tags=[\\\"Memories\\\"], prefix=\\\"/memories\\\", include_in_schema=False)\\n\\n\\n# ------------------------------------------------------------------ #\\n#  Request / Response schemas                                           #\\n# ------------------------------------------------------------------ #\\n\\n\\nclass MessageReadResponse(BaseModel):\\n    \\\"\\\"\\\"Slim message projection for Memory Base session message listings.\\n\\n    Only messages that have been ingested into the requested Memory Base are returned.\\n    ``job_id`` and ``ingested_at`` are sourced from MessageIngestionRecord.\\n    \\\"\\\"\\\"\\n\\n    model_config = {\\\"from_attributes\\\": True}\\n\\n    id: uuid.UUID\\n    timestamp: datetime | None = None\\n    sender: str\\n    sender_name: str\\n    session_id: str\\n    text: str\\n    content_blocks: list[dict[str, Any]] = []\\n    job_id: uuid.UUID | None = None\\n    ingested_at: datetime | None = None\\n\\n\\nclass FlushRequest(BaseModel):\\n    session_id: str\\n\\n\\nclass MismatchResponse(BaseModel):\\n    mismatch_detected: bool\\n\\n\\nclass RegenerateResponse(BaseModel):\\n    job_ids: list[str]\\n\\n\\nasync def _get_memory_base_for_action(\\n    db: Any,\\n    *,\\n    memory_base_id: uuid.UUID,\\n    current_user: CurrentActiveUser,\\n    action: KnowledgeBaseAction,\\n    owner_scoped_memory_base: MemoryBase | None = None,\\n    owner_lookup_done: bool = False,\\n) -> MemoryBase:\\n    \\\"\\\"\\\"Resolve a Memory Base by id, then authorize against its true owner.\\\"\\\"\\\"\\n    mb = owner_scoped_memory_base\\n    if mb is None and not owner_lookup_done:\\n        mb = await get_memory_base_service().get(memory_base_id, user_id=current_user.id)\\n    if mb is None:\\n        authz = get_authorization_service()\\n        if await authz.is_enabled() and await authz.supports_cross_user_fetch():\\n            mb = await db.get(MemoryBase, memory_base_id)\\n    if mb is None:\\n        raise HTTPException(status_code=404, detail=\\\"Memory base not found\\\")\\n    try:\\n        await ensure_knowledge_base_permission(\\n            current_user,\\n            action,\\n            kb_id=mb.id,\\n            kb_user_id=mb.user_id,\\n            kb_name=mb.kb_name,\\n        )\\n    except HTTPException as exc:\\n        raise deny_to_404(exc, detail=\\\"Memory base not found\\\") from exc\\n    return mb\\n\\n\\n# ------------------------------------------------------------------ #\\n#  CRUD                                                                #\\n# ------------------------------------------------------------------ #\\n\\n\\n@router.post(\\\"\\\", status_code=HTTPStatus.CREATED)\\n@router.post(\\\"/\\\", status_code=HTTPStatus.CREATED)\\nasync def create_memory_base(\\n    current_user: CurrentActiveUser,\\n    payload: Annotated[MemoryBaseCreate, Body(embed=False)],\\n) -> MemoryBaseRead:\\n    \\\"\\\"\\\"Create a new Memory Base.\\n\\n    - kb_name is auto-generated as `{sanitized_name}_{8hex}`.\\n    - The backing ``knowledge_base`` row is created immediately; a local directory\\n      is provisioned only when the resolved backend is local Chroma.\\n    - Returns 409 if a Memory Base with the same name already exists for this user.\\n    - Returns 422 if preprocessing=true but preproc_model is missing.\\n    \\\"\\\"\\\"\\n    # Memory bases are knowledge-base-backed resources; guard via the KB family.\\n    # The actor is only the prospective owner during CREATE, so the shared guard\\n    # still evaluates policy instead of applying the existing-resource override.\\n    await ensure_knowledge_base_permission(\\n        current_user,\\n        KnowledgeBaseAction.CREATE,\\n        kb_user_id=current_user.id,\\n    )\\n    try:\\n        mb = await get_memory_base_service().create(\\n            payload,\\n            user_id=current_user.id,\\n            is_superuser=bool(current_user.is_superuser),\\n        )\\n    except MemoryBaseFlowNotFoundError as exc:\\n        # Flow not found or belongs to another user \u2014 return 404 to avoid info-leak\\n        raise HTTPException(status_code=404, detail=str(exc)) from exc\\n    except ModelProviderPolicyError as exc:\\n        # Keep a hidden provider indistinguishable from one that does not exist.\\n        raise HTTPException(status_code=404, detail=\\\"Model provider not found\\\") from exc\\n    except (PreprocessingValidationError, EmbeddingProviderValidationError) as exc:\\n        raise HTTPException(status_code=422, detail=str(exc)) from exc\\n    except BackendProvisioningError as exc:\\n        # Bad remote vector-store config (unreachable / wrong credentials) \u2014\\n        # rejected up front so we don't create a silently-dead Memory Base.\\n        # Must precede the generic ValueError handler (it is a ValueError\\n        # subclass, and 409 \\\"already exists\\\" would be the wrong signal).\\n        raise HTTPException(status_code=422, detail=str(exc)) from exc\\n    except ValueError as exc:\\n        raise HTTPException(status_code=409, detail=str(exc)) from exc\\n    # ``backend_type``/``backend_config`` live on the knowledge_base row, not the\\n    # memory_base table. Read back the effective server-resolved values so an\\n    # omitted type correctly reports an env-defaulted pgvector backend.\\n    read = MemoryBaseRead.model_validate(mb)\\n    backends = await knowledge_base_service.get_backends_for_names([mb.kb_name])\\n    read.backend_type, read.backend_config = backends.get(mb.kb_name, (\\\"chroma\\\", {}))\\n    return read\\n\\n\\n@router.get(\\\"\\\", status_code=HTTPStatus.OK)\\n@router.get(\\\"/\\\", status_code=HTTPStatus.OK)\\nasync def list_memory_bases(\\n    current_user: CurrentActiveUser,\\n    params: Annotated[Params, Depends()],\\n    flow_id: uuid.UUID | None = None,\\n) -> Page[MemoryBaseRead]:\\n    \\\"\\\"\\\"List all Memory Bases owned by the current user (paginated) for a flow_id.\\n\\n    Query params (from fastapi-pagination):\\n        page  - 1-based page number (default 1)\\n        size  - page size (default 50)\\n    \\\"\\\"\\\"\\n    visibility = await visible_scope_prefilter(\\n        current_user,\\n        resource_type=\\\"knowledge_base\\\",\\n        act=KnowledgeBaseAction.READ,\\n    )\\n    async with session_scope() as db:\\n        stmt = get_memory_base_service().list_for_user_stmt(\\n            user_id=current_user.id,\\n            flow_id=flow_id,\\n            visibility=visibility,\\n        )\\n        raw_page = await apaginate(db, stmt, params=params)\\n        # Convert to response models while the session is still open.\\n        items = [MemoryBaseRead.model_validate(m) for m in raw_page.items]\\n\\n    # Eager-load the backing KB's backend (type + config) for the whole page in\\n    # ONE batched query (an ``IN (...)`` over the page's kb_names) \u2014 the same\\n    # shape SQLAlchemy's ``selectinload`` issues \u2014 so the config dropdown can\\n    # surface the backend without an N+1 per-item lookup.\\n    kb_names = [r.kb_name for r in items if r.kb_name]\\n    backends = await knowledge_base_service.get_backends_for_names(kb_names)\\n    for read in items:\\n        read.backend_type, read.backend_config = backends.get(read.kb_name, (\\\"chroma\\\", {}))\\n    return raw_page.model_copy(update={\\\"items\\\": items})\\n\\n\\n@router.get(\\\"/{memory_base_id}\\\", status_code=HTTPStatus.OK)\\nasync def get_memory_base(\\n    memory_base_id: uuid.UUID,\\n    current_user: CurrentActiveUser,\\n) -> MemoryBaseRead:\\n    \\\"\\\"\\\"Get details for a specific Memory Base.\\\"\\\"\\\"\\n    async with session_scope() as db:\\n        mb = await _get_memory_base_for_action(\\n            db,\\n            memory_base_id=memory_base_id,\\n            current_user=current_user,\\n            action=KnowledgeBaseAction.READ,\\n        )\\n    read = MemoryBaseRead.model_validate(mb)\\n    # Resolve the backing KB's backend from the knowledge_base row so the\\n    # Control Center config dropdown can surface it (config distinguishes\\n    # Chroma Local vs Cloud).\\n    backends = await knowledge_base_service.get_backends_for_names([mb.kb_name])\\n    read.backend_type, read.backend_config = backends.get(mb.kb_name, (\\\"chroma\\\", {}))\\n    return read\\n\\n\\n@router.get(\\\"/{memory_base_id}/sessions\\\", status_code=HTTPStatus.OK)\\nasync def list_sessions(\\n    memory_base_id: uuid.UUID,\\n    current_user: CurrentActiveUser,\\n    params: Annotated[Params, Depends()],\\n) -> Page[MemoryBaseSessionRead]:\\n    \\\"\\\"\\\"List persisted sessions for this Memory Base (paginated).\\n\\n    Only sessions that have been synced at least once (i.e. have a\\n    MemoryBaseSession row) are returned.  Results are ordered by\\n    last_sync_at descending.\\n\\n    Each item includes ``pending_count``: the number of completed flow runs\\n    remaining before the next auto-capture ingestion is triggered.\\n    \\\"\\\"\\\"\\n    from langflow.services.memory_base.ingestion import count_pending_messages\\n\\n    async with session_scope() as db:\\n        try:\\n            owner_scoped_memory_base = await get_memory_base_service().get_memory_base_or_404(\\n                db,\\n                memory_base_id,\\n                current_user.id,\\n            )\\n        except ValueError:\\n            owner_scoped_memory_base = None\\n        mb = await _get_memory_base_for_action(\\n            db,\\n            memory_base_id=memory_base_id,\\n            current_user=current_user,\\n            action=KnowledgeBaseAction.READ,\\n            owner_scoped_memory_base=owner_scoped_memory_base,\\n            owner_lookup_done=True,\\n        )\\n\\n        stmt = get_memory_base_service().sessions_stmt(memory_base_id, mb.user_id)\\n        raw_page = await apaginate(db, stmt, params=params)\\n\\n        items: list[MemoryBaseSessionRead] = []\\n        for s in raw_page.items:\\n            pending_count = await count_pending_messages(db, mb, s)\\n            read = MemoryBaseSessionRead.model_validate(s)\\n            read.pending_count = pending_count\\n            items.append(read)\\n\\n    return raw_page.model_copy(update={\\\"items\\\": items})\\n\\n\\n@router.get(\\\"/{memory_base_id}/messages\\\", status_code=HTTPStatus.OK)\\nasync def list_memory_base_messages(\\n    memory_base_id: uuid.UUID,\\n    current_user: CurrentActiveUser,\\n    params: Annotated[Params, Depends()],\\n    session_id: str | None = None,\\n) -> Page[MessageReadResponse]:\\n    \\\"\\\"\\\"List messages ingested into this Memory Base (paginated).\\n\\n    Only messages that have been successfully ingested into the requested Memory Base\\n    are returned, ordered by timestamp descending. When ``session_id`` is provided,\\n    results are filtered to that session; otherwise all ingested messages across\\n    sessions are returned. Each item includes ``job_id`` and ``ingested_at`` from\\n    the MessageIngestionRecord.\\n\\n    Returns 404 if the Memory Base does not belong to the current user.\\n    \\\"\\\"\\\"\\n    service = get_memory_base_service()\\n    async with session_scope() as db:\\n        mb = await _get_memory_base_for_action(\\n            db,\\n            memory_base_id=memory_base_id,\\n            current_user=current_user,\\n            action=KnowledgeBaseAction.READ,\\n        )\\n\\n        if mb.preprocessing:\\n            # Preprocessing MBs: the KB holds LLM-distilled output, so the\\n            # surface for \\\"what's in the KB\\\" is MemoryBasePreprocessingOutput,\\n            # not MessageTable.  Project the row into the same response shape\\n            # so the API contract is identical from the frontend's perspective.\\n            stmt = service.session_preprocessed_outputs_stmt(memory_base_id, session_id)\\n            return await apaginate(\\n                db,\\n                stmt,\\n                params=params,\\n                transformer=lambda rows: [\\n                    MessageReadResponse(\\n                        id=row.id,\\n                        timestamp=row.created_at,\\n                        sender=\\\"Machine\\\",\\n                        sender_name=\\\"Preprocessor\\\",\\n                        session_id=row.session_id,\\n                        text=row.output_text or \\\"\\\",\\n                        content_blocks=[],\\n                        job_id=row.job_id,\\n                        ingested_at=row.created_at,\\n                    )\\n                    for row in rows\\n                ],\\n            )\\n\\n        stmt = service.session_raw_messages_stmt(memory_base_id, session_id)\\n        return await apaginate(\\n            db,\\n            stmt,\\n            params=params,\\n            transformer=lambda rows: [\\n                MessageReadResponse(\\n                    id=msg.id,\\n                    timestamp=msg.timestamp,\\n                    sender=msg.sender,\\n                    sender_name=msg.sender_name,\\n                    session_id=msg.session_id,\\n                    text=msg.text,\\n                    content_blocks=render_v1_content_blocks(msg.content_blocks) or [],\\n                    job_id=mir.job_id,\\n                    ingested_at=mir.ingested_at,\\n                )\\n                for msg, mir in rows\\n            ],\\n        )\\n\\n\\n@router.patch(\\\"/{memory_base_id}\\\", status_code=HTTPStatus.OK)\\nasync def update_memory_base(\\n    memory_base_id: uuid.UUID,\\n    current_user: CurrentActiveUser,\\n    patch: Annotated[MemoryBaseUpdate, Body(embed=False)],\\n) -> MemoryBaseRead:\\n    \\\"\\\"\\\"Update mutable parameters (name, threshold, auto_capture).\\n\\n    Threshold changes only take effect at the next auto-capture trigger.\\n    Any already-running ingestion task continues with its original arguments.\\n    Preprocessing fields (preprocessing, preproc_model, preproc_instructions, preproc_kill_phrase)\\n    are immutable after creation and cannot be patched.\\n    \\\"\\\"\\\"\\n    async with session_scope() as db:\\n        mb = await _get_memory_base_for_action(\\n            db,\\n            memory_base_id=memory_base_id,\\n            current_user=current_user,\\n            action=KnowledgeBaseAction.WRITE,\\n        )\\n    try:\\n        mb = await get_memory_base_service().update(\\n            memory_base_id,\\n            owner_user_id=mb.user_id,\\n            patch=patch,\\n            actor_user_id=current_user.id,\\n            actor_is_superuser=bool(current_user.is_superuser),\\n        )\\n    except MemoryBaseFlowNotFoundError as exc:\\n        raise HTTPException(status_code=404, detail=str(exc)) from exc\\n    except PreprocessingValidationError as exc:\\n        raise HTTPException(status_code=403, detail=str(exc)) from exc\\n    if mb is None:\\n        raise HTTPException(status_code=404, detail=\\\"Memory base not found\\\")\\n    return MemoryBaseRead.model_validate(mb)\\n\\n\\n@router.delete(\\\"/{memory_base_id}\\\", status_code=HTTPStatus.NO_CONTENT)\\nasync def delete_memory_base(\\n    memory_base_id: uuid.UUID,\\n    current_user: CurrentActiveUser,\\n) -> None:\\n    \\\"\\\"\\\"Delete a Memory Base.\\n\\n    Active ingestion tasks are forcefully cancelled before the DB record is\\n    removed. The associated KB directory is deleted from disk afterwards\\n    (best-effort \u2014 a disk failure will not affect the 204 response).\\n    \\\"\\\"\\\"\\n    async with session_scope() as db:\\n        mb = await _get_memory_base_for_action(\\n            db,\\n            memory_base_id=memory_base_id,\\n            current_user=current_user,\\n            action=KnowledgeBaseAction.DELETE,\\n        )\\n    deleted = await get_memory_base_service().delete(memory_base_id, user_id=mb.user_id)\\n    if not deleted:\\n        raise HTTPException(status_code=404, detail=\\\"Memory base not found\\\")\\n\\n\\n# ------------------------------------------------------------------ #\\n#  Ingestion trigger                                                   #\\n# ------------------------------------------------------------------ #\\n\\n\\n@router.post(\\\"/{memory_base_id}/flush\\\", status_code=HTTPStatus.ACCEPTED)\\nasync def flush_memory_base(\\n    memory_base_id: uuid.UUID,\\n    current_user: CurrentActiveUser,\\n    body: Annotated[FlushRequest, Body(embed=False)],\\n) -> dict:\\n    \\\"\\\"\\\"Manually trigger an ingestion / sync job regardless of the threshold.\\n\\n    Returns 409 Conflict if an ingestion task is already in progress for the\\n    given (memory_base_id, session_id) pair to prevent concurrent indexing.\\n    \\\"\\\"\\\"\\n    async with session_scope() as db:\\n        mb = await _get_memory_base_for_action(\\n            db,\\n            memory_base_id=memory_base_id,\\n            current_user=current_user,\\n            action=KnowledgeBaseAction.INGEST,\\n        )\\n    try:\\n        job_id = await get_memory_base_service().trigger_ingestion(\\n            memory_base_id=memory_base_id,\\n            owner_user_id=mb.user_id,\\n            actor_user_id=current_user.id,\\n            session_id=body.session_id,\\n        )\\n    except ValueError as exc:\\n        raise HTTPException(status_code=404, detail=str(exc)) from exc\\n    except DuplicateJobError as exc:\\n        raise HTTPException(status_code=409, detail=str(exc)) from exc\\n    except RuntimeError as exc:\\n        raise HTTPException(status_code=409, detail=str(exc)) from exc\\n\\n    return {\\\"job_id\\\": job_id}\\n\\n\\n# ------------------------------------------------------------------ #\\n#  Mismatch detection & regeneration                                   #\\n# ------------------------------------------------------------------ #\\n\\n\\n@router.get(\\\"/{memory_base_id}/mismatch\\\", status_code=HTTPStatus.OK)\\nasync def check_mismatch(\\n    memory_base_id: uuid.UUID,\\n    current_user: CurrentActiveUser,\\n) -> MismatchResponse:\\n    \\\"\\\"\\\"Detect if the vector store is empty while metadata records processed messages.\\n\\n    The UI should surface a \\\"Mismatch Detected\\\" warning and offer a Regenerate button.\\n    \\\"\\\"\\\"\\n    async with session_scope() as db:\\n        mb = await _get_memory_base_for_action(\\n            db,\\n            memory_base_id=memory_base_id,\\n            current_user=current_user,\\n            action=KnowledgeBaseAction.READ,\\n        )\\n    try:\\n        detected = await get_memory_base_service().check_mismatch(memory_base_id, user_id=mb.user_id)\\n    except ValueError as exc:\\n        raise HTTPException(status_code=404, detail=str(exc)) from exc\\n    return MismatchResponse(mismatch_detected=detected)\\n\\n\\n@router.post(\\\"/{memory_base_id}/regenerate\\\", status_code=HTTPStatus.ACCEPTED)\\nasync def regenerate_memory_base(\\n    memory_base_id: uuid.UUID,\\n    current_user: CurrentActiveUser,\\n) -> RegenerateResponse:\\n    \\\"\\\"\\\"Regenerate the Knowledge Base by resetting all session cursors and re-ingesting.\\n\\n    Use this to recover from external Chroma directory deletions or vector DB corruption.\\n    All MemoryBaseSession.cursor_id values are set to None before re-running ingestion.\\n    \\\"\\\"\\\"\\n    async with session_scope() as db:\\n        mb = await _get_memory_base_for_action(\\n            db,\\n            memory_base_id=memory_base_id,\\n            current_user=current_user,\\n            action=KnowledgeBaseAction.INGEST,\\n        )\\n    try:\\n        job_ids = await get_memory_base_service().regenerate(\\n            memory_base_id=memory_base_id,\\n            owner_user_id=mb.user_id,\\n            actor_user_id=current_user.id,\\n        )\\n    except ValueError as exc:\\n        raise HTTPException(status_code=404, detail=str(exc)) from exc\\n    return RegenerateResponse(job_ids=job_ids)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/api/v1/model_options.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"cfc5cab4c49230eb4d6e2f2cc287671b9a0e74684fb906be35f80d28f16c07f9\",\"content\":\"from typing import Annotated, Literal\\n\\nfrom fastapi import APIRouter, Query\\nfrom lfx.base.models.provider_registry import resolve_provider_id\\nfrom lfx.base.models.unified_models import (\\n    get_embedding_model_options,\\n    get_language_model_options,\\n    get_model_providers,\\n)\\nfrom lfx.services.model_provider_policy import (\\n    ModelProviderPolicyPurpose,\\n    ModelProviderPolicySnapshot,\\n    aresolve_model_provider_policy,\\n)\\n\\nfrom langflow.api.utils import CurrentActiveUser\\nfrom langflow.api.v1.model_provider_policy_scope import (\\n    ProviderPolicyAttributes,\\n    ProviderPolicyAttributesDependency,\\n)\\n\\nrouter = APIRouter(prefix=\\\"/model_options\\\", tags=[\\\"Model Options\\\"], include_in_schema=False)\\n\\nProviderReadPurpose = Literal[\\\"use\\\", \\\"configure\\\"]\\n\\n\\nasync def _resolve_option_policy(\\n    current_user: CurrentActiveUser,\\n    purpose: ProviderReadPurpose | None,\\n    attributes: ProviderPolicyAttributes,\\n) -> ModelProviderPolicySnapshot:\\n    providers = get_model_providers()\\n    baseline = await aresolve_model_provider_policy(\\n        user_id=current_user.id,\\n        providers=providers,\\n        purpose=ModelProviderPolicyPurpose.USE,\\n        attributes=attributes,\\n    )\\n    requested = ModelProviderPolicyPurpose(purpose) if purpose is not None else ModelProviderPolicyPurpose.USE\\n    if requested is ModelProviderPolicyPurpose.USE:\\n        return baseline\\n    requested_snapshot = await aresolve_model_provider_policy(\\n        user_id=current_user.id,\\n        providers=providers,\\n        purpose=requested,\\n        attributes=attributes,\\n    )\\n    return ModelProviderPolicySnapshot(\\n        context=baseline.context,\\n        purpose=requested,\\n        candidate_provider_ids=baseline.candidate_provider_ids,\\n        allowed_provider_ids=baseline.allowed_provider_ids & requested_snapshot.allowed_provider_ids,\\n    )\\n\\n\\ndef _annotate_options(\\n    options: list[dict],\\n    provider_policy: ModelProviderPolicySnapshot,\\n) -> list[dict]:\\n    annotated_options = []\\n    for option in options:\\n        provider = option.get(\\\"provider\\\")\\n        if not isinstance(provider, str) or not provider_policy.allows(provider):\\n            continue\\n        annotated_options.append(\\n            {\\n                **option,\\n                \\\"provider_id\\\": resolve_provider_id(provider),\\n            }\\n        )\\n    return annotated_options\\n\\n\\n@router.get(\\\"/language\\\", status_code=200)\\nasync def get_language_model_options_endpoint(\\n    current_user: CurrentActiveUser,\\n    provider_policy_attributes: ProviderPolicyAttributesDependency,\\n    purpose: Annotated[ProviderReadPurpose | None, Query()] = None,\\n):\\n    \\\"\\\"\\\"Get language model options filtered by user's enabled providers and models.\\\"\\\"\\\"\\n    provider_policy = await _resolve_option_policy(current_user, purpose, provider_policy_attributes)\\n    return _annotate_options(\\n        get_language_model_options(user_id=current_user.id, provider_policy=provider_policy),\\n        provider_policy,\\n    )\\n\\n\\n@router.get(\\\"/embedding\\\", status_code=200)\\nasync def get_embedding_model_options_endpoint(\\n    current_user: CurrentActiveUser,\\n    provider_policy_attributes: ProviderPolicyAttributesDependency,\\n    purpose: Annotated[ProviderReadPurpose | None, Query()] = None,\\n):\\n    \\\"\\\"\\\"Get embedding model options filtered by user's enabled providers and models.\\\"\\\"\\\"\\n    provider_policy = await _resolve_option_policy(current_user, purpose, provider_policy_attributes)\\n    return _annotate_options(\\n        get_embedding_model_options(user_id=current_user.id, provider_policy=provider_policy),\\n        provider_policy,\\n    )\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/api/v1/model_provider_policy.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"a0cf8de71d2a76577c7401140dbff680c7de072272f8af156d47fd96dd00952d\",\"content\":\"\\\"\\\"\\\"Superuser administration for the install-wide approved-provider policy.\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nfrom typing import Annotated\\n\\nfrom fastapi import APIRouter, Depends, HTTPException, status\\nfrom lfx.base.models.provider_registry import get_registry_snapshot, resolve_provider_id\\nfrom lfx.services.deps import get_model_provider_policy_service\\nfrom pydantic import BaseModel, Field, StringConstraints, field_validator\\n\\nfrom langflow.api.utils import DbSession, DbSessionReadOnly\\nfrom langflow.api.v1.policy_bundle_errors import policy_bundle_revision_conflict\\nfrom langflow.services.auth.utils import get_current_active_superuser\\nfrom langflow.services.authorization.audit import AUDIT_ALLOW, audit_decision\\nfrom langflow.services.database.models.user.model import User\\nfrom langflow.services.model_provider_policy import (\\n    ModelProviderPolicyNotInitializedError,\\n    apply_model_provider_policy_state,\\n    get_model_provider_policy_state,\\n    replace_model_provider_policy_state,\\n)\\nfrom langflow.services.policy_bundle import (\\n    PolicyBundleApplicationNotSupportedError,\\n    PolicyBundleRevisionConflictError,\\n)\\n\\nrouter = APIRouter(prefix=\\\"/model-provider-policy\\\", tags=[\\\"Model Provider Policy\\\"])\\n\\nProviderId = Annotated[str, StringConstraints(pattern=r\\\"^[a-z0-9][a-z0-9._-]*$\\\", max_length=255)]\\n\\n\\nclass RegisteredModelProviderRead(BaseModel):\\n    \\\"\\\"\\\"Stable provider identity exposed to the administrative picker.\\\"\\\"\\\"\\n\\n    provider_id: str\\n    display_name: str\\n    provider: str\\n\\n\\nclass ModelProviderPolicyWrite(BaseModel):\\n    \\\"\\\"\\\"Complete replacement for the install-wide approved-provider set.\\\"\\\"\\\"\\n\\n    approved_provider_ids: Annotated[list[ProviderId], Field(max_length=1000)]\\n\\n    @field_validator(\\\"approved_provider_ids\\\", mode=\\\"before\\\")\\n    @classmethod\\n    def canonicalize_provider_ids(cls, provider_ids):\\n        if not isinstance(provider_ids, list):\\n            return provider_ids\\n        return [\\n            resolve_provider_id(provider_id) if isinstance(provider_id, str) else provider_id\\n            for provider_id in provider_ids\\n        ]\\n\\n    @field_validator(\\\"approved_provider_ids\\\")\\n    @classmethod\\n    def deduplicate_provider_ids(cls, provider_ids: list[str]) -> list[str]:\\n        return sorted(set(provider_ids))\\n\\n\\nclass ModelProviderPolicyRead(BaseModel):\\n    \\\"\\\"\\\"Current deployment ceiling plus every provider registered in this process.\\\"\\\"\\\"\\n\\n    approved_provider_ids: list[str]\\n    registered_providers: list[RegisteredModelProviderRead]\\n    managed_externally: bool\\n\\n\\ndef _build_policy_response(\\n    approved_provider_ids: set[str] | frozenset[str],\\n    *,\\n    managed_externally: bool = False,\\n) -> ModelProviderPolicyRead:\\n    snapshot = get_registry_snapshot()\\n    registered_providers = [\\n        RegisteredModelProviderRead(\\n            provider_id=provider_id,\\n            display_name=descriptor.display_name or descriptor.name,\\n            provider=descriptor.name,\\n        )\\n        for provider_id, descriptor in snapshot.descriptors_by_id.items()\\n    ]\\n    registered_providers.sort(key=lambda descriptor: (descriptor.display_name.casefold(), descriptor.provider_id))\\n    return ModelProviderPolicyRead(\\n        approved_provider_ids=sorted(approved_provider_ids),\\n        registered_providers=registered_providers,\\n        managed_externally=managed_externally,\\n    )\\n\\n\\ndef _policy_unavailable() -> HTTPException:\\n    return HTTPException(\\n        status_code=status.HTTP_503_SERVICE_UNAVAILABLE,\\n        detail=\\\"Model-provider policy is not initialized. Apply the latest database migrations and restart Langflow.\\\",\\n    )\\n\\n\\ndef _externally_managed() -> HTTPException:\\n    return HTTPException(\\n        status_code=status.HTTP_409_CONFLICT,\\n        detail=\\\"Model-provider policy is externally managed and cannot be changed through this API.\\\",\\n    )\\n\\n\\n@router.get(\\\"\\\", response_model=ModelProviderPolicyRead)\\n@router.get(\\\"/\\\", response_model=ModelProviderPolicyRead, include_in_schema=False)\\nasync def read_model_provider_policy(\\n    _admin: Annotated[User, Depends(get_current_active_superuser)],\\n    session: DbSessionReadOnly,\\n) -> ModelProviderPolicyRead:\\n    \\\"\\\"\\\"Read the global provider policy. An empty approved list is unrestricted.\\\"\\\"\\\"\\n    external_provider_ids = get_model_provider_policy_service().external_approved_provider_ids\\n    if external_provider_ids is not None:\\n        return _build_policy_response(external_provider_ids, managed_externally=True)\\n\\n    try:\\n        state = await get_model_provider_policy_state(session)\\n    except ModelProviderPolicyNotInitializedError as exc:\\n        raise _policy_unavailable() from exc\\n    return _build_policy_response(state.approved_provider_ids)\\n\\n\\n@router.post(\\\"\\\", response_model=ModelProviderPolicyRead)\\n@router.post(\\\"/\\\", response_model=ModelProviderPolicyRead, include_in_schema=False)\\n@router.put(\\\"\\\", response_model=ModelProviderPolicyRead)\\n@router.put(\\\"/\\\", response_model=ModelProviderPolicyRead, include_in_schema=False)\\nasync def replace_model_provider_policy(\\n    payload: ModelProviderPolicyWrite,\\n    admin: Annotated[User, Depends(get_current_active_superuser)],\\n    session: DbSession,\\n) -> ModelProviderPolicyRead:\\n    \\\"\\\"\\\"Atomically replace the global provider policy and invalidate snapshots.\\\"\\\"\\\"\\n    if get_model_provider_policy_service().external_approved_provider_ids is not None:\\n        raise _externally_managed()\\n\\n    try:\\n        state = await replace_model_provider_policy_state(\\n            session,\\n            payload.approved_provider_ids,\\n            actor_user_id=admin.id,\\n            reason=\\\"Replace approved model providers\\\",\\n        )\\n    except ModelProviderPolicyNotInitializedError as exc:\\n        raise _policy_unavailable() from exc\\n    except PolicyBundleApplicationNotSupportedError as exc:\\n        raise HTTPException(status_code=status.HTTP_409_CONFLICT, detail=str(exc)) from exc\\n    except PolicyBundleRevisionConflictError as exc:\\n        raise policy_bundle_revision_conflict(exc) from exc\\n\\n    try:\\n        await audit_decision(\\n            user_id=admin.id,\\n            action=\\\"model_provider_policy:replace\\\",\\n            obj=\\\"model_provider_policy:1\\\",\\n            result=AUDIT_ALLOW,\\n            details={\\n                \\\"approved_provider_ids\\\": sorted(state.approved_provider_ids),\\n                \\\"version\\\": state.version,\\n            },\\n        )\\n    finally:\\n        # Never publish uncommitted policy to the runtime. A failed commit\\n        # leaves the previous in-memory ceiling and cached decisions intact.\\n        # Queue the committed audit first, but still publish if enqueueing\\n        # fails so this worker cannot keep enforcing stale state.\\n        apply_model_provider_policy_state(state)\\n    return _build_policy_response(state.approved_provider_ids)\\n\\n\\n__all__ = [\\n    \\\"ModelProviderPolicyRead\\\",\\n    \\\"ModelProviderPolicyWrite\\\",\\n    \\\"RegisteredModelProviderRead\\\",\\n    \\\"router\\\",\\n]\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/api/v1/model_provider_policy_scope.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"52f00798c51b1373dc1f65725b1325b4e6a34e3f956c21843fc72c8f441dacf3\",\"content\":\"\\\"\\\"\\\"Trusted request scope for model-provider policy decisions.\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nfrom typing import Annotated\\nfrom uuid import UUID\\n\\nfrom fastapi import Depends, HTTPException, Query, status\\n\\nfrom langflow.api.utils import CurrentActiveUser, DbSession\\nfrom langflow.services.authorization import (\\n    FlowAction,\\n    ProjectAction,\\n    authorized_or_owner_scoped,\\n    deny_to_404,\\n    ensure_flow_permission,\\n    ensure_project_permission,\\n)\\nfrom langflow.services.database.models.flow.model import Flow\\nfrom langflow.services.database.models.folder.model import Folder\\nfrom langflow.services.model_provider_policy_scope import (\\n    ProviderPolicyAttributes,\\n    provider_policy_attributes_for_flow,\\n    scoped_model_provider_policy_for_flow,\\n)\\n\\n\\nasync def resolve_provider_policy_attributes(\\n    current_user: CurrentActiveUser,\\n    session: DbSession,\\n    flow_id: Annotated[UUID | None, Query()] = None,\\n    project_id: Annotated[UUID | None, Query()] = None,\\n) -> ProviderPolicyAttributes:\\n    \\\"\\\"\\\"Resolve an optional flow/project handle to its authorized server scope.\\n\\n    Clients deliberately cannot supply a workspace id. The workspace is read\\n    from the selected project (or from a projectless stored flow).\\n    \\\"\\\"\\\"\\n    if flow_id is not None and project_id is not None:\\n        raise HTTPException(\\n            status_code=status.HTTP_422_UNPROCESSABLE_CONTENT,\\n            detail=\\\"Provide either flow_id or project_id, not both\\\",\\n        )\\n\\n    attributes: ProviderPolicyAttributes = {\\n        \\\"is_superuser\\\": bool(getattr(current_user, \\\"is_superuser\\\", False)),\\n    }\\n    if flow_id is not None:\\n        flow = await authorized_or_owner_scoped(\\n            session,\\n            Flow,\\n            id_column=Flow.id,\\n            resource_id=flow_id,\\n            owner_column=Flow.user_id,\\n            owner_id=current_user.id,\\n        )\\n        if flow is None:\\n            raise HTTPException(status_code=status.HTTP_404_NOT_FOUND, detail=\\\"Flow not found\\\")\\n        try:\\n            await ensure_flow_permission(\\n                current_user,\\n                FlowAction.READ,\\n                flow_id=flow.id,\\n                flow_user_id=flow.user_id,\\n                workspace_id=flow.workspace_id,\\n                folder_id=flow.folder_id,\\n            )\\n        except HTTPException as exc:\\n            raise deny_to_404(exc, \\\"Flow not found\\\") from exc\\n\\n        if flow.folder_id is not None:\\n            project = await session.get(Folder, flow.folder_id)\\n            if project is None:\\n                raise HTTPException(status_code=status.HTTP_404_NOT_FOUND, detail=\\\"Project not found\\\")\\n            attributes[\\\"project_id\\\"] = project.id\\n            if project.workspace_id is not None:\\n                attributes[\\\"workspace_id\\\"] = project.workspace_id\\n        elif flow.workspace_id is not None:\\n            attributes[\\\"workspace_id\\\"] = flow.workspace_id\\n        return attributes\\n\\n    if project_id is not None:\\n        project = await authorized_or_owner_scoped(\\n            session,\\n            Folder,\\n            id_column=Folder.id,\\n            resource_id=project_id,\\n            owner_column=Folder.user_id,\\n            owner_id=current_user.id,\\n        )\\n        if project is None:\\n            raise HTTPException(status_code=status.HTTP_404_NOT_FOUND, detail=\\\"Project not found\\\")\\n        try:\\n            await ensure_project_permission(\\n                current_user,\\n                ProjectAction.READ,\\n                project_id=project_id,\\n                project_user_id=project.user_id,\\n                workspace_id=project.workspace_id,\\n            )\\n        except HTTPException as exc:\\n            raise deny_to_404(exc, \\\"Project not found\\\") from exc\\n        attributes[\\\"project_id\\\"] = project.id\\n        if project.workspace_id is not None:\\n            attributes[\\\"workspace_id\\\"] = project.workspace_id\\n    return attributes\\n\\n\\nProviderPolicyAttributesDependency = Annotated[\\n    ProviderPolicyAttributes,\\n    Depends(resolve_provider_policy_attributes),\\n]\\n\\n\\n__all__ = [\\n    \\\"ProviderPolicyAttributes\\\",\\n    \\\"ProviderPolicyAttributesDependency\\\",\\n    \\\"provider_policy_attributes_for_flow\\\",\\n    \\\"resolve_provider_policy_attributes\\\",\\n    \\\"scoped_model_provider_policy_for_flow\\\",\\n]\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/api/v1/models.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"b6bf06791571e30a92eb6fe9710ddd911f99930290cbac77a98f46617f65916e\",\"content\":\"from __future__ import annotations\\n\\nimport json\\nfrom collections.abc import Collection\\nfrom typing import Annotated, Literal\\n\\nfrom fastapi import APIRouter, HTTPException, Query\\nfrom lfx.base.models.model_metadata import EXPLICIT_ENABLE_ONLY_PROVIDERS, LIVE_MODEL_PROVIDERS\\nfrom lfx.base.models.model_utils import inject_custom_enabled_models, replace_with_live_models\\nfrom lfx.base.models.provider_registry import (\\n    get_provider_descriptor,\\n    is_api_key_optional,\\n    provider_id_for,\\n    resolve_provider_id,\\n)\\nfrom lfx.base.models.unified_models import (\\n    get_live_only_providers,\\n    get_model_provider_metadata,\\n    get_model_provider_variable_mapping,\\n    get_model_providers,\\n    get_provider_all_variables,\\n    get_unified_models_detailed,\\n)\\nfrom lfx.base.models.unified_models.credentials import (\\n    model_status_contains,\\n    model_status_key,\\n    parse_model_status_key,\\n)\\nfrom lfx.interface.components import get_and_cache_all_types_dict\\nfrom lfx.services.model_provider_policy import (\\n    ModelProviderPolicyError,\\n    ModelProviderPolicyPurpose,\\n    ModelProviderPolicySnapshot,\\n    aresolve_model_provider_policy,\\n)\\nfrom loguru import logger\\nfrom pydantic import BaseModel, field_validator\\n\\nfrom langflow.api.utils import CurrentActiveUser, DbSession\\nfrom langflow.api.v1.model_provider_policy_scope import (\\n    ProviderPolicyAttributes,\\n    ProviderPolicyAttributesDependency,\\n)\\nfrom langflow.services.authorization import VariableAction, ensure_variable_permission\\nfrom langflow.services.deps import get_settings_service, get_variable_service\\nfrom langflow.services.variable.constants import GENERIC_TYPE\\nfrom langflow.services.variable.service import DatabaseVariableService\\n\\nrouter = APIRouter(prefix=\\\"/models\\\", tags=[\\\"Models\\\"], include_in_schema=False)\\n\\n# Variable names for storing disabled models and default models\\nDISABLED_MODELS_VAR = \\\"__disabled_models__\\\"\\nENABLED_MODELS_VAR = \\\"__enabled_models__\\\"\\nDEFAULT_LANGUAGE_MODEL_VAR = \\\"__default_language_model__\\\"\\nDEFAULT_EMBEDDING_MODEL_VAR = \\\"__default_embedding_model__\\\"\\n\\n# Security limits\\nMAX_STRING_LENGTH = 200  # Maximum length for model IDs and provider names\\nMAX_BATCH_UPDATE_SIZE = 100  # Maximum number of models that can be updated at once\\n\\nProviderReadPurpose = Literal[\\\"use\\\", \\\"configure\\\"]\\n\\n\\nasync def _aresolve_policy(\\n    current_user: CurrentActiveUser,\\n    purpose: ModelProviderPolicyPurpose,\\n    attributes: ProviderPolicyAttributes,\\n) -> ModelProviderPolicySnapshot:\\n    return await _aresolve_policy_for_providers(current_user, get_model_providers(), purpose, attributes)\\n\\n\\nasync def _aresolve_policy_for_providers(\\n    current_user: CurrentActiveUser,\\n    providers: Collection[str],\\n    purpose: ModelProviderPolicyPurpose,\\n    attributes: ProviderPolicyAttributes,\\n) -> ModelProviderPolicySnapshot:\\n    return await aresolve_model_provider_policy(\\n        user_id=current_user.id,\\n        providers=providers,\\n        purpose=purpose,\\n        attributes=attributes,\\n    )\\n\\n\\nasync def _aresolve_read_policy(\\n    current_user: CurrentActiveUser,\\n    purpose: ProviderReadPurpose | None,\\n    *,\\n    default: ModelProviderPolicyPurpose,\\n    attributes: ProviderPolicyAttributes,\\n    providers: Collection[str] | None = None,\\n) -> ModelProviderPolicySnapshot:\\n    \\\"\\\"\\\"Resolve an endpoint baseline plus an optional narrowing purpose.\\n\\n    The query parameter selects an additional UI context; it must never let a\\n    caller replace and widen the endpoint's own DISCOVER/CONFIGURE/USE check.\\n    \\\"\\\"\\\"\\n    candidates = tuple(providers) if providers is not None else tuple(get_model_providers())\\n    baseline = await _aresolve_policy_for_providers(current_user, candidates, default, attributes)\\n    requested = ModelProviderPolicyPurpose(purpose) if purpose is not None else default\\n    if requested is default:\\n        return baseline\\n    requested_snapshot = await _aresolve_policy_for_providers(current_user, candidates, requested, attributes)\\n    return ModelProviderPolicySnapshot(\\n        context=baseline.context,\\n        purpose=requested,\\n        candidate_provider_ids=baseline.candidate_provider_ids,\\n        allowed_provider_ids=baseline.allowed_provider_ids & requested_snapshot.allowed_provider_ids,\\n    )\\n\\n\\ndef _require_provider_from_policy(provider_policy: ModelProviderPolicySnapshot, provider: str) -> None:\\n    try:\\n        provider_policy.require(provider)\\n    except ModelProviderPolicyError as exc:\\n        # Do not confirm whether a hidden provider is registered or merely blocked.\\n        raise HTTPException(status_code=404, detail=\\\"Model provider not found\\\") from exc\\n\\n\\nasync def _require_provider(\\n    current_user: CurrentActiveUser,\\n    provider: str,\\n    purpose: ModelProviderPolicyPurpose,\\n    attributes: ProviderPolicyAttributes,\\n) -> None:\\n    provider_policy = await _aresolve_policy(current_user, purpose, attributes)\\n    _require_provider_from_policy(provider_policy, provider)\\n\\n\\ndef get_provider_from_variable_name(variable_name: str) -> str | None:\\n    \\\"\\\"\\\"Get provider name from a model provider variable name.\\n\\n    Args:\\n        variable_name: The variable name (e.g., \\\"OPENAI_API_KEY\\\")\\n\\n    Returns:\\n        The provider name (e.g., \\\"OpenAI\\\") or None if not a model provider variable\\n    \\\"\\\"\\\"\\n    # Resolve against every declared provider variable, not just the primary\\n    # API-key mapping. This remains dynamic so providers registered by an\\n    # extension during startup participate without a process restart cache.\\n    for provider in get_model_providers():\\n        if any(variable.get(\\\"variable_key\\\") == variable_name for variable in get_provider_all_variables(provider)):\\n            return provider\\n    return None\\n\\n\\nclass ModelStatusUpdate(BaseModel):\\n    \\\"\\\"\\\"Request model for updating model enabled status.\\\"\\\"\\\"\\n\\n    provider: str\\n    model_id: str\\n    enabled: bool\\n    model_type: Literal[\\\"llm\\\", \\\"embeddings\\\"] | None = None\\n\\n    @field_validator(\\\"model_id\\\", \\\"provider\\\")\\n    @classmethod\\n    def validate_non_empty_string(cls, v: str) -> str:\\n        \\\"\\\"\\\"Ensure strings are non-empty and reasonable length.\\\"\\\"\\\"\\n        if not v or not v.strip():\\n            msg = \\\"Field cannot be empty\\\"\\n            raise ValueError(msg)\\n        if len(v) > MAX_STRING_LENGTH:\\n            msg = f\\\"Field exceeds maximum length of {MAX_STRING_LENGTH} characters\\\"\\n            raise ValueError(msg)\\n        return v.strip()\\n\\n\\nclass ValidateProviderRequest(BaseModel):\\n    \\\"\\\"\\\"Request model for validating provider credentials.\\\"\\\"\\\"\\n\\n    provider: str\\n    variables: dict[str, str]  # {variable_key: value}\\n\\n    @field_validator(\\\"provider\\\")\\n    @classmethod\\n    def validate_provider(cls, v: str) -> str:\\n        \\\"\\\"\\\"Ensure provider name is valid.\\\"\\\"\\\"\\n        if not v or not v.strip():\\n            msg = \\\"Provider cannot be empty\\\"\\n            raise ValueError(msg)\\n        if len(v) > MAX_STRING_LENGTH:\\n            msg = f\\\"Provider exceeds maximum length of {MAX_STRING_LENGTH} characters\\\"\\n            raise ValueError(msg)\\n        return v.strip()\\n\\n\\nclass ValidateProviderResponse(BaseModel):\\n    \\\"\\\"\\\"Response model for provider validation.\\\"\\\"\\\"\\n\\n    valid: bool\\n    error: str | None = None\\n\\n\\nclass ModelProviderDescriptorRead(BaseModel):\\n    \\\"\\\"\\\"Stable provider identity for authorization and administrative pickers.\\\"\\\"\\\"\\n\\n    provider_id: str\\n    display_name: str\\n    provider: str\\n\\n\\n@router.get(\\\"/providers\\\", status_code=200)\\nasync def list_model_providers(\\n    current_user: CurrentActiveUser,\\n    provider_policy_attributes: ProviderPolicyAttributesDependency,\\n    purpose: Annotated[ProviderReadPurpose | None, Query()] = None,\\n) -> list[str]:\\n    \\\"\\\"\\\"Return available model providers.\\\"\\\"\\\"\\n    policy = await _aresolve_read_policy(\\n        current_user,\\n        purpose,\\n        default=ModelProviderPolicyPurpose.DISCOVER,\\n        attributes=provider_policy_attributes,\\n    )\\n    return policy.filter(get_model_providers())\\n\\n\\n@router.get(\\\"/provider-descriptors\\\", status_code=200, response_model=list[ModelProviderDescriptorRead])\\nasync def list_model_provider_descriptors(\\n    current_user: CurrentActiveUser,\\n    provider_policy_attributes: ProviderPolicyAttributesDependency,\\n    purpose: Annotated[ProviderReadPurpose | None, Query()] = None,\\n) -> list[ModelProviderDescriptorRead]:\\n    \\\"\\\"\\\"Return discovery-authorized providers with stable IDs and display names.\\n\\n    ``/providers`` intentionally retains its historical ``list[str]`` wire\\n    contract; administrative clients can opt into this additive descriptor\\n    route when compiling provider-specific component permissions.\\n    \\\"\\\"\\\"\\n    # Build/cache extension templates first: extension loading can register new\\n    # unified providers and stamps legacy standalone model/embedding components\\n    # with provider identities not represented by ``get_model_providers()``.\\n    all_types = await get_and_cache_all_types_dict(settings_service=get_settings_service())\\n    descriptors_by_id: dict[str, ModelProviderDescriptorRead] = {}\\n\\n    for provider in get_model_providers():\\n        provider_id = provider_id_for(provider)\\n        if provider_id is None:\\n            continue\\n        descriptor = get_provider_descriptor(provider)\\n        descriptors_by_id[provider_id] = ModelProviderDescriptorRead(\\n            provider_id=provider_id,\\n            display_name=(descriptor.display_name if descriptor and descriptor.display_name else provider),\\n            provider=provider,\\n        )\\n\\n    for components in all_types.values():\\n        for component in components.values():\\n            if not isinstance(component, dict) or not isinstance(component.get(\\\"metadata\\\"), dict):\\n                continue\\n            metadata = component[\\\"metadata\\\"]\\n            provider_id = metadata.get(\\\"model_provider_id\\\")\\n            if not isinstance(provider_id, str) or not provider_id or provider_id in descriptors_by_id:\\n                continue\\n            display_name = metadata.get(\\\"model_provider_display_name\\\")\\n            descriptors_by_id[provider_id] = ModelProviderDescriptorRead(\\n                provider_id=provider_id,\\n                display_name=(\\n                    display_name\\n                    if isinstance(display_name, str) and display_name\\n                    else provider_id.replace(\\\"_\\\", \\\" \\\").replace(\\\"-\\\", \\\" \\\").title()\\n                ),\\n                provider=provider_id,\\n            )\\n\\n    policy = await _aresolve_read_policy(\\n        current_user,\\n        purpose,\\n        default=ModelProviderPolicyPurpose.DISCOVER,\\n        attributes=provider_policy_attributes,\\n        providers=descriptors_by_id,\\n    )\\n    return sorted(\\n        (descriptor for provider_id, descriptor in descriptors_by_id.items() if policy.allows(provider_id)),\\n        key=lambda descriptor: (descriptor.display_name.casefold(), descriptor.provider_id),\\n    )\\n\\n\\n@router.get(\\\"\\\", status_code=200)\\nasync def list_models(\\n    *,\\n    provider: Annotated[list[str] | None, Query(description=\\\"Repeat to include multiple providers\\\")] = None,\\n    model_name: str | None = None,\\n    model_type: str | None = None,\\n    include_unsupported: bool = False,\\n    include_deprecated: bool = False,\\n    # common metadata filters\\n    tool_calling: bool | None = None,\\n    reasoning: bool | None = None,\\n    search: bool | None = None,\\n    preview: bool | None = None,\\n    deprecated: bool | None = None,\\n    not_supported: bool | None = None,\\n    purpose: Annotated[ProviderReadPurpose | None, Query()] = None,\\n    session: DbSession,\\n    current_user: CurrentActiveUser,\\n    provider_policy_attributes: ProviderPolicyAttributesDependency,\\n):\\n    \\\"\\\"\\\"Return model catalog filtered by query parameters.\\n\\n    Pass providers as repeated query params, e.g. `?provider=OpenAI&provider=Anthropic`.\\n    \\\"\\\"\\\"\\n    provider_policy = await _aresolve_read_policy(\\n        current_user,\\n        purpose,\\n        default=ModelProviderPolicyPurpose.DISCOVER,\\n        attributes=provider_policy_attributes,\\n    )\\n    selected_providers: list[str] | None = provider_policy.filter(provider) if provider is not None else None\\n    if provider is not None and not selected_providers:\\n        return []\\n    configuration_policy = await _aresolve_read_policy(\\n        current_user,\\n        purpose,\\n        default=ModelProviderPolicyPurpose.CONFIGURE,\\n        attributes=provider_policy_attributes,\\n    )\\n    metadata_filters = {\\n        k: v\\n        for k, v in {\\n            \\\"tool_calling\\\": tool_calling,\\n            \\\"reasoning\\\": reasoning,\\n            \\\"search\\\": search,\\n            \\\"preview\\\": preview,\\n            \\\"deprecated\\\": deprecated,\\n            \\\"not_supported\\\": not_supported,\\n        }.items()\\n        if v is not None\\n    }\\n\\n    # Get enabled providers status (now just checks if variables exist)\\n    enabled_providers_result = await _get_enabled_providers_result(\\n        session=session,\\n        current_user=current_user,\\n        provider_policy=configuration_policy,\\n    )\\n    provider_configured_status = enabled_providers_result.get(\\\"provider_status\\\", {})\\n\\n    # Get enabled models map for current user to determine \\\"active\\\" providers\\n    enabled_models_result = await _get_enabled_models_result(\\n        session=session,\\n        current_user=current_user,\\n        provider_policy=configuration_policy,\\n        provider_status=provider_configured_status,\\n    )\\n    enabled_models_map = enabled_models_result.get(\\\"enabled_models\\\", {})\\n\\n    # Get default model if model_type is specified\\n    default_provider = None\\n    if model_type:\\n        try:\\n            default_model_result = await get_default_model(\\n                session=session,\\n                current_user=current_user,\\n                provider_policy_attributes=provider_policy_attributes,\\n                model_type=model_type,\\n            )\\n            if default_model_result.get(\\\"default_model\\\"):\\n                default_provider = default_model_result[\\\"default_model\\\"].get(\\\"provider\\\")\\n        except Exception:  # noqa: BLE001\\n            # Default model fetch failed, continue without it\\n            # This is not critical for the main operation - we suppress to avoid breaking the list\\n            logger.debug(\\\"Failed to fetch default model, continuing without it\\\", exc_info=True)\\n\\n    # Get filtered models - pass providers directly to avoid filtering after\\n    filtered_models = get_unified_models_detailed(\\n        providers=selected_providers,\\n        model_name=model_name,\\n        include_unsupported=include_unsupported,\\n        include_deprecated=include_deprecated,\\n        model_type=model_type,\\n        **metadata_filters,\\n    )\\n\\n    # Live-discovery-only providers (contributed by extension bundles, e.g. vLLM or\\n    # OpenAI Compatible) ship no static catalog rows, so the catalog query above can\\n    # never emit them, and replace_with_live_models below only fills providers that\\n    # are already configured. Union them in with an empty model list so the Model\\n    # Providers dialog can offer their configuration form in the first place; once\\n    # configured, replace_with_live_models fills this same entry with the endpoint's\\n    # discovered models. Skipped for model_name/metadata queries, which ask about\\n    # concrete models rather than which providers exist.\\n    if model_name is None and not metadata_filters:\\n        provider_metadata = get_model_provider_metadata()\\n        listed_providers = {provider_dict.get(\\\"provider\\\") for provider_dict in filtered_models}\\n        for live_only_provider in get_live_only_providers():\\n            if not provider_policy.allows(live_only_provider):\\n                continue\\n            if live_only_provider in listed_providers:\\n                continue\\n            if selected_providers and live_only_provider not in selected_providers:\\n                continue\\n            filtered_models.append(\\n                {\\n                    **provider_metadata.get(live_only_provider, {}),\\n                    \\\"provider\\\": live_only_provider,\\n                    \\\"models\\\": [],\\n                    \\\"num_models\\\": 0,\\n                }\\n            )\\n\\n    # Run before status is computed so live-only providers appended here (providers\\n    # that ship no static catalog rows) still receive is_enabled/is_configured (#13735).\\n    configured_providers = {p for p, configured in provider_configured_status.items() if configured}\\n    configured_providers = {provider for provider in configured_providers if provider_policy.allows(provider)}\\n    replace_with_live_models(filtered_models, current_user.id, configured_providers, model_type)\\n\\n    # Merge free-text custom deployments into the catalog (honors list_models filters).\\n    explicitly_enabled_models = await _get_enabled_models(session=session, current_user=current_user)\\n    inject_custom_enabled_models(\\n        filtered_models,\\n        explicitly_enabled_models,\\n        model_name=model_name,\\n        model_type=model_type,\\n        metadata_filters=metadata_filters or None,\\n    )\\n    filtered_models = [\\n        provider_data for provider_data in filtered_models if provider_policy.allows(provider_data.get(\\\"provider\\\", \\\"\\\"))\\n    ]\\n\\n    # replace_with_live_models iterates every live-capable provider regardless of\\n    # the ?provider= filter, so it can append providers the caller excluded (e.g.\\n    # a configured OpenRouter appearing in a ?provider=OpenAI response). Re-apply\\n    # the filter so the response honors its own contract.\\n    if selected_providers:\\n        filtered_models = [p for p in filtered_models if p.get(\\\"provider\\\") in selected_providers]\\n\\n    # Providers whose model list is discovered from the provider's endpoint\\n    # once credentials are configured. The UI uses this to explain an empty\\n    # (or seed-only) catalog instead of presenting it as \\\"no models exist\\\".\\n    live_discovery_providers = set(LIVE_MODEL_PROVIDERS) | set(get_live_only_providers())\\n\\n    for provider_dict in filtered_models:\\n        prov_name = provider_dict.get(\\\"provider\\\")\\n        provider_dict[\\\"provider_id\\\"] = resolve_provider_id(prov_name) if isinstance(prov_name, str) else None\\n        provider_dict[\\\"is_configured\\\"] = provider_configured_status.get(prov_name, False)\\n        provider_dict[\\\"live_discovery\\\"] = prov_name in live_discovery_providers\\n        prov_models_status = enabled_models_map.get(prov_name, {})\\n        has_active_model = any(prov_models_status.values())\\n        provider_dict[\\\"is_enabled\\\"] = has_active_model\\n\\n    def sort_key(provider_dict):\\n        provider_name = provider_dict.get(\\\"provider\\\", \\\"\\\")\\n        is_configured = provider_dict.get(\\\"is_configured\\\", False)\\n        is_default = provider_name == default_provider\\n        # default first, then configured, then alphabetical (False sorts before True)\\n        return (not is_default, not is_configured, provider_name)\\n\\n    filtered_models.sort(key=sort_key)\\n\\n    return filtered_models\\n\\n\\n@router.get(\\\"/provider-variable-mapping\\\", status_code=200)\\nasync def get_model_provider_mapping(\\n    current_user: CurrentActiveUser,\\n    provider_policy_attributes: ProviderPolicyAttributesDependency,\\n    purpose: Annotated[ProviderReadPurpose | None, Query()] = None,\\n) -> dict[str, list[dict]]:\\n    \\\"\\\"\\\"Return provider variables mapping with full variable info.\\n\\n    Each provider maps to a list of variable objects containing:\\n    - variable_name: Display name shown to user\\n    - variable_key: Environment variable key\\n    - description: Help text for the variable\\n    - required: Whether the variable is required\\n    - is_secret: Whether to treat as credential\\n    - is_list: Whether it accepts multiple values\\n    - options: Predefined options for dropdowns\\n    \\\"\\\"\\\"\\n    metadata = get_model_provider_metadata()\\n    policy = await _aresolve_read_policy(\\n        current_user,\\n        purpose,\\n        default=ModelProviderPolicyPurpose.CONFIGURE,\\n        attributes=provider_policy_attributes,\\n    )\\n    return {provider: meta.get(\\\"variables\\\", []) for provider, meta in metadata.items() if policy.allows(provider)}\\n\\n\\nasync def _get_enabled_providers_result(\\n    *,\\n    session: DbSession,\\n    current_user: CurrentActiveUser,\\n    provider_policy: ModelProviderPolicySnapshot,\\n    providers: list[str] | None = None,\\n):\\n    \\\"\\\"\\\"Get enabled providers for the current user.\\n\\n    Providers are considered enabled if they have a credential variable stored.\\n    API key validation is performed when credentials are saved, not on every read,\\n    to avoid latency from external API calls.\\n    \\\"\\\"\\\"\\n    variable_service = get_variable_service()\\n    try:\\n        if not isinstance(variable_service, DatabaseVariableService):\\n            raise HTTPException(\\n                status_code=500,\\n                detail=\\\"Variable service is not an instance of DatabaseVariableService\\\",\\n            )\\n        provider_variable_map = get_model_provider_variable_mapping()\\n        provider_candidates = [\\n            *provider_variable_map,\\n            *(\\n                provider\\n                for provider in get_model_providers()\\n                if provider not in provider_variable_map and is_api_key_optional(provider)\\n            ),\\n        ]\\n\\n        required_variable_names: set[str] = set()\\n        for provider in provider_candidates:\\n            if not provider_policy.allows(provider):\\n                continue\\n            for variable in get_provider_all_variables(provider):\\n                variable_key = variable.get(\\\"variable_key\\\")\\n                if variable.get(\\\"required\\\", False) and isinstance(variable_key, str):\\n                    required_variable_names.add(variable_key)\\n\\n        # Only provider credentials matter here. Avoid materializing every user\\n        # variable while still treating credentials encrypted under another\\n        # LANGFLOW_SECRET_KEY as unavailable.\\n        available_variable_names = await variable_service.get_available_variable_names(\\n            user_id=current_user.id,\\n            names=required_variable_names,\\n            session=session,\\n        )\\n\\n        # Check which providers have all required variables saved\\n        enabled_providers = []\\n        provider_status = {}\\n\\n        for provider in provider_candidates:\\n            if not provider_policy.allows(provider):\\n                continue\\n            # Get ALL variables for this provider\\n            provider_vars = get_provider_all_variables(provider)\\n\\n            # Check if all REQUIRED variables are present\\n            required_vars = [v for v in provider_vars if v.get(\\\"required\\\", False)]\\n            all_required_present = (\\n                is_api_key_optional(provider)\\n                if not provider_vars\\n                else all(v.get(\\\"variable_key\\\") in available_variable_names for v in required_vars)\\n            )\\n\\n            provider_status[provider] = all_required_present\\n            if all_required_present:\\n                enabled_providers.append(provider)\\n\\n        result = {\\n            \\\"enabled_providers\\\": enabled_providers,\\n            \\\"provider_status\\\": provider_status,\\n        }\\n\\n        if providers:\\n            # Filter enabled_providers and provider_status by requested providers\\n            filtered_enabled = [p for p in result[\\\"enabled_providers\\\"] if p in providers]\\n            provider_status_dict = result.get(\\\"provider_status\\\", {})\\n            if not isinstance(provider_status_dict, dict):\\n                provider_status_dict = {}\\n            filtered_status = {p: v for p, v in provider_status_dict.items() if p in providers}\\n            return {\\n                \\\"enabled_providers\\\": filtered_enabled,\\n                \\\"provider_status\\\": filtered_status,\\n            }\\n    except HTTPException:\\n        raise\\n    except Exception as e:\\n        logger.exception(\\\"Failed to get enabled providers for user %s\\\", current_user.id)\\n        raise HTTPException(\\n            status_code=500,\\n            detail=\\\"Failed to retrieve enabled providers. Please try again later.\\\",\\n        ) from e\\n    else:\\n        return result\\n\\n\\n@router.get(\\\"/enabled_providers\\\", status_code=200)\\nasync def get_enabled_providers(\\n    *,\\n    session: DbSession,\\n    current_user: CurrentActiveUser,\\n    provider_policy_attributes: ProviderPolicyAttributesDependency,\\n    providers: Annotated[list[str] | None, Query()] = None,\\n    purpose: Annotated[ProviderReadPurpose | None, Query()] = None,\\n):\\n    \\\"\\\"\\\"Get policy-visible providers configured for the current user.\\\"\\\"\\\"\\n    provider_policy = aw";
